using Microsoft.ServiceBus.Messaging;
using System.Collections.Generic;
using Newtonsoft.Json;

/// <summary>
/// Batch processor for incoming Service Bus messages
/// Implements dead letter queue handling and retry policies
/// </summary>
class ServiceBusMessageProcessor extends RunBaseBatch
{
    private str connectionString;
    private str subscriptionName;
    private str topicName;
    private SubscriptionClient subscriptionClient;
    private int maxBatchSize;
    private int maxRetryCount;

    protected void new()
    {
        super();
        this.maxBatchSize = 10;
        this.maxRetryCount = 3;
        this.topicName = 'customer-events';
        this.subscriptionName = 'customer-sync';
    }

    public static ServiceBusMessageProcessor construct()
    {
        return new ServiceBusMessageProcessor();
    }

    public void run()
    {
        System.Collections.Generic.IEnumerable<BrokeredMessage> messages;
        System.Exception ex;

        try
        {
            this.initializeSubscriptionClient();

            while (!this.isCancellationRequested())
            {
                // Receive batch of messages with timeout
                messages = this.subscriptionClient.ReceiveBatch(
                    this.maxBatchSize,
                    System.TimeSpan::FromSeconds(30));

                if (messages)
                {
                    this.processBatch(messages);
                }
                else
                {
                    // No messages available, wait before next poll
                    System.Threading.Thread::Sleep(5000);
                }
            }
        }
        catch (ex)
        {
            error(strFmt('Message processing error: %1', ex.get_Message()));
            throw ex;
        }
        finally
        {
            if (this.subscriptionClient)
            {
                this.subscriptionClient.Close();
            }
        }
    }

    private void initializeSubscriptionClient()
    {
        SysGlobalConfiguration config = SysGlobalConfiguration::find();
        this.connectionString = config.ServiceBusConnectionString;

        this.subscriptionClient = SubscriptionClient::CreateFromConnectionString(
            this.connectionString,
            this.topicName,
            this.subscriptionName);

        // Configure retry policy
        RetryPolicy retryPolicy = new RetryExponential(
            System.TimeSpan::FromSeconds(1),
            System.TimeSpan::FromMinutes(1),
            this.maxRetryCount);

        this.subscriptionClient.RetryPolicy = retryPolicy;
    }

    private void processBatch(System.Collections.Generic.IEnumerable<BrokeredMessage> _messages)
    {
        BrokeredMessage message;
        List<BrokeredMessage> completedMessages = new List<BrokeredMessage>();
        List<BrokeredMessage> deadLetterMessages = new List<BrokeredMessage>();
        System.Exception processingEx;

        var enumerator = _messages.GetEnumerator();

        while (enumerator.MoveNext())
        {
            message = enumerator.get_Current();

            try
            {
                if (this.processMessage(message))
                {
                    completedMessages.Add(message);
                }
                else
                {
                    // Processing failed, check retry count
                    if (message.DeliveryCount >= this.maxRetryCount)
                    {
                        deadLetterMessages.Add(message);
                    }
                    else
                    {
                        // Let message return to queue for retry
                        message.Abandon();
                    }
                }
            }
            catch (processingEx)
            {
                error(strFmt('Message processing failed: %1', processingEx.get_Message()));

                // Send to dead letter queue if max retries exceeded
                if (message.DeliveryCount >= this.maxRetryCount)
                {
                    deadLetterMessages.Add(message);
                }
                else
                {
                    message.Abandon();
                }
            }
        }

        // Batch complete/dead letter operations for efficiency
        this.completeMessages(completedMessages);
        this.deadLetterMessages(deadLetterMessages);

        info(strFmt('Processed batch: %1 completed, %2 dead letters',
            completedMessages.Count,
            deadLetterMessages.Count));
    }

    private boolean processMessage(BrokeredMessage _message)
    {
        str messageBody;
        str eventType;
        CustomerEventBase eventData;
        System.Exception ex;

        try
        {
            // Extract message properties
            eventType = _message.Properties.get_Item('EventType');

            // Get message body as string
            messageBody = System.Text.Encoding::UTF8.GetString(_message.GetBody());

            info(strFmt('Processing %1 message: %2', eventType, _message.MessageId));

            // Route to appropriate handler based on event type
            switch (eventType)
            {
                case 'CustomerCreated':
                    eventData = JsonConvert::DeserializeObject(messageBody, classIdGet(CustomerCreatedEvent));
                    return this.handleCustomerCreated(eventData as CustomerCreatedEvent);

                case 'CustomerChanged':
                    eventData = JsonConvert::DeserializeObject(messageBody, classIdGet(CustomerChangedEvent));
                    return this.handleCustomerChanged(eventData as CustomerChangedEvent);

                default:
                    warning(strFmt('Unknown event type: %1', eventType));
                    return true; // Complete unknown messages to avoid infinite retry
            }
        }
        catch (ex)
        {
            error(strFmt('Message processing error: %1', ex.get_Message()));
            return false;
        }
    }

    private boolean handleCustomerCreated(CustomerCreatedEvent _event)
    {
        ExternalCustomerSync syncRecord;

        ttsbegin;
        try
        {
            // Create sync record for external system processing
            syncRecord.clear();
            syncRecord.CustomerAccount = _event.CustomerAccount;
            syncRecord.EventType = 'Created';
            syncRecord.ProcessingStatus = ExternalSyncStatus::Pending;
            syncRecord.ReceivedDateTime = DateTimeUtil::utcNow();
            syncRecord.EventData = JsonConvert::SerializeObject(_event);
            syncRecord.insert();

            ttscommit;

            info(strFmt('Customer creation event processed: %1', _event.CustomerAccount));
            return true;
        }
        catch
        {
            ttsabort;
            return false;
        }
    }

    private boolean handleCustomerChanged(CustomerChangedEvent _event)
    {
        ExternalCustomerSync syncRecord;

        ttsbegin;
        try
        {
            syncRecord.clear();
            syncRecord.CustomerAccount = _event.CustomerAccount;
            syncRecord.EventType = 'Changed';
            syncRecord.ProcessingStatus = ExternalSyncStatus::Pending;
            syncRecord.ReceivedDateTime = DateTimeUtil::utcNow();
            syncRecord.EventData = JsonConvert::SerializeObject(_event);
            syncRecord.insert();

            ttscommit;

            info(strFmt('Customer change event processed: %1', _event.CustomerAccount));
            return true;
        }
        catch
        {
            ttsabort;
            return false;
        }
    }

    private void completeMessages(List<BrokeredMessage> _messages)
    {
        System.Collections.Generic.IEnumerable<System.Guid> lockTokens;
        System.Exception ex;

        if (_messages.Count > 0)
        {
            try
            {
                lockTokens = _messages.Select(x => x.LockToken);
                this.subscriptionClient.CompleteBatch(lockTokens);
            }
            catch (ex)
            {
                error(strFmt('Batch complete failed: %1', ex.get_Message()));
            }
        }
    }

    private void deadLetterMessages(List<BrokeredMessage> _messages)
    {
        BrokeredMessage message;
        System.Exception ex;
        var enumerator = _messages.GetEnumerator();

        while (enumerator.MoveNext())
        {
            message = enumerator.get_Current();
            try
            {
                message.DeadLetter('MaxRetryExceeded', 'Message exceeded maximum retry count');
            }
            catch (ex)
            {
                error(strFmt('Dead letter failed for message %1: %2', message.MessageId, ex.get_Message()));
            }
        }
    }

    public ClassDescription caption()
    {
        return 'Service Bus Message Processor';
    }

    public boolean canGoBatch()
    {
        return true;
    }

    public boolean canRunInNewSession()
    {
        return false;
    }
}

/// <summary>
/// Service class for handling Logic Apps integration errors with retry logic
/// </summary>
class LogicAppsErrorHandler
{
    private IntegrationLog integrationLog;
    private int maxRetryAttempts;
    private int baseDelaySeconds;

    public void new(int _maxRetries = 5, int _baseDelay = 30)
    {
        maxRetryAttempts = _maxRetries;
        baseDelaySeconds = _baseDelay;
    }

    /// <summary>
    /// Process error with exponential backoff retry logic
    /// </summary>
    public boolean processIntegrationError(str _integrationId, str _errorMessage, Exception _exception, int _currentRetry = 0)
    {
        IntegrationErrorLog errorLog;
        boolean shouldRetry = false;
        int nextRetryDelay;

        ttsbegin;

        try
        {
            // Log the error
            errorLog.clear();
            errorLog.IntegrationId = _integrationId;
            errorLog.ErrorMessage = _errorMessage;
            errorLog.ExceptionType = enum2Str(_exception);
            errorLog.RetryAttempt = _currentRetry;
            errorLog.CreatedDateTime = DateTimeUtil::utcNow();
            errorLog.Status = IntegrationErrorStatus::Failed;

            // Determine if we should retry based on error type
            shouldRetry = this.shouldRetryError(_exception, _currentRetry);

            if (shouldRetry && _currentRetry < maxRetryAttempts)
            {
                // Calculate exponential backoff delay
                nextRetryDelay = baseDelaySeconds * Power(2, _currentRetry);
                errorLog.NextRetryDateTime = DateTimeUtil::addSeconds(DateTimeUtil::utcNow(), nextRetryDelay);
                errorLog.Status = IntegrationErrorStatus::PendingRetry;

                info(strFmt("Integration %1 failed, scheduling retry %2 in %3 seconds", 
                    _integrationId, _currentRetry + 1, nextRetryDelay));
            }
            else
            {
                errorLog.Status = IntegrationErrorStatus::Failed;
                error(strFmt("Integration %1 failed permanently after %2 attempts: %3", 
                    _integrationId, _currentRetry, _errorMessage));
            }

            errorLog.insert();
            ttscommit;

            // Schedule retry if applicable
            if (shouldRetry && _currentRetry < maxRetryAttempts)
            {
                this.scheduleRetry(_integrationId, nextRetryDelay, _currentRetry + 1);
            }
        }
        catch (Exception::Error)
        {
            ttsabort;
            error("Failed to log integration error");
            throw Exception::Error;
        }

        return shouldRetry;
    }

    private boolean shouldRetryError(Exception _exception, int _currentRetry)
    {
        // Implement business logic for retryable errors
        switch (_exception)
        {
            case Exception::UpdateConflict:
            case Exception::Timeout:
            case Exception::CLRError:
                return true;
            case Exception::Error:
            case Exception::Info:
                return false;
            default:
                return _currentRetry < 3; // Conservative retry for unknown errors
        }
    }

    private void scheduleRetry(str _integrationId, int _delaySeconds, int _retryNumber)
    {
        BatchHeader batchHeader;
        BatchJob batchJob;

        // Create a batch job for delayed retry
        batchHeader = BatchHeader::construct();
        batchHeader.parmCaption(strFmt("Logic Apps Retry - %1", _integrationId));
        batchHeader.parmStartDateTime(DateTimeUtil::addSeconds(DateTimeUtil::utcNow(), _delaySeconds));
        batchHeader.save();

        batchJob = batchHeader.addTask(classStr(LogicAppsRetryTask));
        batchJob.parmMethodName(methodStr(LogicAppsRetryTask, retryIntegration));
        batchJob.parmParmObject(con2Str([_integrationId, _retryNumber]));

        batchHeader.submit();
    }
}

/// <summary>
/// Circuit breaker implementation for Logic Apps endpoints
/// </summary>
class LogicAppsCircuitBreaker
{
    private str endpointUrl;
    private CircuitBreakerState state;
    private int failureCount;
    private utcdatetime lastFailureTime;
    private int failureThreshold;
    private int timeoutSeconds;
    private int halfOpenRetryDelay;

    public void new(str _endpointUrl, int _failureThreshold = 5, int _timeoutSeconds = 60)
    {
        endpointUrl = _endpointUrl;
        state = CircuitBreakerState::Closed;
        failureThreshold = _failureThreshold;
        timeoutSeconds = _timeoutSeconds;
        halfOpenRetryDelay = 300; // 5 minutes
        this.loadState();
    }

    /// <summary>
    /// Execute request through circuit breaker
    /// </summary>
    public container executeRequest(str _requestData, str _method = 'POST')
    {
        container result;
        boolean success = false;
        str errorMessage;

        // Check circuit breaker state
        if (!this.canExecuteRequest())
        {
            throw error(strFmt("Circuit breaker is OPEN for endpoint %1. Service temporarily unavailable.", endpointUrl));
        }

        try
        {
            // Execute the actual Logic Apps request
            result = this.makeHttpRequest(_requestData, _method);
            success = true;

            // Reset on successful call
            this.onSuccess();
        }
        catch (Exception::Error)
        {
            errorMessage = infolog.text();
            this.onFailure(errorMessage);
            throw;
        }
        catch (Exception::CLRError)
        {
            errorMessage = "HTTP request failed";
            this.onFailure(errorMessage);
            throw;
        }

        return result;
    }

    private boolean canExecuteRequest()
    {
        utcdatetime currentTime = DateTimeUtil::utcNow();

        switch (state)
        {
            case CircuitBreakerState::Closed:
                return true;

            case CircuitBreakerState::Open:
                // Check if we should transition to half-open
                if (DateTimeUtil::getDifference(currentTime, lastFailureTime) > halfOpenRetryDelay)
                {
                    state = CircuitBreakerState::HalfOpen;
                    info(strFmt("Circuit breaker transitioning to HALF-OPEN for %1", endpointUrl));
                    return true;
                }
                return false;

            case CircuitBreakerState::HalfOpen:
                return true;

            default:
                return false;
        }
    }

    private void onSuccess()
    {
        if (state != CircuitBreakerState::Closed)
        {
            info(strFmt("Circuit breaker CLOSED for %1 - service recovered", endpointUrl));
        }

        state = CircuitBreakerState::Closed;
        failureCount = 0;
        this.saveState();
    }

    private void onFailure(str _errorMessage)
    {
        failureCount++;
        lastFailureTime = DateTimeUtil::utcNow();

        if (state == CircuitBreakerState::HalfOpen)
        {
            // Immediately open on half-open failure
            state = CircuitBreakerState::Open;
            warning(strFmt("Circuit breaker OPEN for %1 - half-open test failed", endpointUrl));
        }
        else if (failureCount >= failureThreshold)
        {
            state = CircuitBreakerState::Open;
            warning(strFmt("Circuit breaker OPEN for %1 - threshold exceeded (%2 failures)", 
                endpointUrl, failureCount));
        }

        this.saveState();
    }

    private container makeHttpRequest(str _requestData, str _method)
    {
        System.Net.Http.HttpClient httpClient;
        System.Net.Http.HttpRequestMessage request;
        System.Net.Http.HttpResponseMessage response;
        System.Net.Http.StringContent content;
        str responseText;

        try
        {
            httpClient = new System.Net.Http.HttpClient();
            httpClient.Timeout = System.TimeSpan::FromSeconds(timeoutSeconds);

            content = new System.Net.Http.StringContent(_requestData, 
                System.Text.Encoding::UTF8, "application/json");

            request = new System.Net.Http.HttpRequestMessage(
                new System.Net.Http.HttpMethod(_method), endpointUrl);
            request.Content = content;

            response = httpClient.SendAsync(request).Result;

            if (!response.IsSuccessStatusCode)
            {
                throw error(strFmt("HTTP %1: %2", response.StatusCode, response.ReasonPhrase));
            }

            responseText = response.Content.ReadAsStringAsync().Result;
            return [true, responseText];
        }
        finally
        {
            if (httpClient)
                httpClient.Dispose();
        }
    }

    private void loadState()
    {
        CircuitBreakerState stateRecord;

        select firstonly stateRecord
            where stateRecord.EndpointUrl == endpointUrl;

        if (stateRecord.RecId)
        {
            state = stateRecord.State;
            failureCount = stateRecord.FailureCount;
            lastFailureTime = stateRecord.LastFailureTime;
        }
    }

    private void saveState()
    {
        CircuitBreakerState stateRecord;

        ttsbegin;
        select forupdate stateRecord
            where stateRecord.EndpointUrl == endpointUrl;

        if (!stateRecord.RecId)
        {
            stateRecord.clear();
            stateRecord.EndpointUrl = endpointUrl;
        }

        stateRecord.State = state;
        stateRecord.FailureCount = failureCount;
        stateRecord.LastFailureTime = lastFailureTime;
        stateRecord.ModifiedDateTime = DateTimeUtil::utcNow();

        if (stateRecord.RecId)
            stateRecord.update();
        else
            stateRecord.insert();

        ttscommit;
    }
}

