    /// Custom method to determine approval requirement
    /// Power Automate can use this for conditional logic
    /// </summary>
    [DataMember('RequiresApproval')]
    public boolean requiresApproval()
    {
        PurchReqTable purchReqTable;
        PurchReqLine  purchReqLine;
        AmountCur     lineTotal;

        select sum(LineAmount) from purchReqLine
            where purchReqLine.PurchReqId == this.requisitionId;

        // Business rule: requires approval if over $10,000
        return purchReqLine.LineAmount > 10000.00;
    }

