    [Wrappable(true), Replaceable(true)]
    public BusinessEventsContract getSchema()
    {
        BusinessEventsContract contract = BusinessEventsContract::construct();

        contract.parmEventId(this.eventId());
        contract.parmEventTime(DateTimeUtil::utcNow());

        // Payload structure for Power Automate
        Map payload = new Map(Types::String, Types::Container);
        payload.insert('PurchReqId', this.purchReqId);
        payload.insert('RequestedBy', this.requestedBy);
        payload.insert('TotalAmount', this.totalAmount);
        payload.insert('RequestorEmail', this.requestorEmail);
        payload.insert('CompanyId', curext());

        contract.parmPayload(payload.pack());

        return contract;
    }

    /// <summary>
    /// Event identifier for Power Automate subscription
    /// </summary>
    public str eventId()
    {
        return 'PurchReqApprovalRequired';
    }

    /// <summary>
    /// Helper method to get requestor email
    /// </summary>
    private Email getRequestorEmail(UserId _userId)
    {
        UserInfo        userInfo;
        DirPersonUser   dirPersonUser;
        DirPerson       dirPerson;
        LogisticsElectronicAddress electronicAddress;

        try
        {
            select firstonly Email from electronicAddress
                join dirPerson
                    where dirPerson.RecId == electronicAddress.Party
                join dirPersonUser
                    where dirPersonUser.PersonParty == dirPerson.RecId
                join userInfo
                    where userInfo.Id == dirPersonUser.User &&
                          userInfo.Id == _userId;

            return electronicAddress.Locator;
        }
        catch (Exception::Error)
        {
            // Fallback to user ID if email not found
            return _userId;
        }
    }

    /// <summary>
    /// Send the business event to configured endpoints
    /// </summary>
    public void send()
    {
        BusinessEventsParameters parameters = BusinessEventsParameters::find();

        if (parameters.Enabled)
        {
            BusinessEventsClient::sendEvent(this.getSchema());
            info(strFmt('Purchase requisition approval event sent for %1', this.purchReqId));
        }
    }
}

