/// <summary>
/// Service to handle Power Automate webhook responses
/// Processes approval decisions and updates F&O records
/// </summary>
[SysRestServiceAttribute('PowerAutomateWebhookService', 'Power Automate Webhook Handler'),
 SysRestCollectionAttribute('PowerAutomateCallbacks')]
class PowerAutomateWebhookService
{
    /// <summary>
    /// Handle purchase requisition approval response from Power Automate
    /// </summary>
    [SysRestOperationAttribute('ApprovalResponse', 'POST'),
 SysRestParameterAttribute('request', SysRestParameterType::RequestBody)]
    public str processApprovalResponse(str request)
    {
        Map                     requestData;
        PurchReqId              purchReqId;
        str                     approvalDecision;
        str                     approverComments;
        UserId                  approvedBy;
        PowerAutomateResponse   response = new PowerAutomateResponse();

        ttsbegin;
        try
        {
            // Parse JSON request from Power Automate
            requestData = this.parseJsonRequest(request);

            if (!requestData)
            {
                throw error('Invalid request format received from Power Automate');
            }

            purchReqId = requestData.lookup('PurchReqId');
            approvalDecision = requestData.lookup('Decision'); // 'Approved' or 'Rejected'
            approverComments = requestData.lookup('Comments');
            approvedBy = requestData.lookup('ApprovedBy');

            // Validate required fields
            if (!purchReqId || !approvalDecision)
            {
                throw error('Missing required fields: PurchReqId and Decision');
            }

            // Process the approval
            boolean success = this.updatePurchReqStatus(purchReqId, approvalDecision, approverComments, approvedBy);

            if (success)
            {
                response.setSuccess(true);
                response.setMessage(strFmt('Purchase requisition %1 %2 successfully', purchReqId, approvalDecision));
                ttscommit;
            }
            else
            {
                throw error(strFmt('Failed to update purchase requisition %1', purchReqId));
            }
        }
        catch (Exception::Error)
        {
            ttsabort;
            response.setSuccess(false);
            response.setMessage(strFmt('Error processing approval: %1', Exception::getLastError()));

            // Log error for troubleshooting
            EventLog::writeError(classStr(PowerAutomateWebhookService),
                               methodStr(PowerAutomateWebhookService, processApprovalResponse),
                               Exception::getLastError());
        }

        return response.toJson();
    }

    /// <summary>
    /// Parse incoming JSON request from Power Automate
    /// </summary>
    private Map parseJsonRequest(str _jsonString)
    {
        Map         result;
        JsonParser  parser = new JsonParser();

        try
        {
            result = parser.parse(_jsonString);
        }
        catch (Exception::Error)
        {
            result = null;
        }

        return result;
    }

    /// <summary>
    /// Update purchase requisition based on approval decision
    /// </summary>
    private boolean updatePurchReqStatus(PurchReqId _purchReqId, str _decision, str _comments, UserId _approvedBy)
    {
        PurchReqTable           purchReqTable;
        PurchReqApprovalJournal approvalJournal;
        boolean                 success = false;

        select forupdate purchReqTable
            where purchReqTable.PurchReqId == _purchReqId;

        if (purchReqTable)
        {
            if (_decision == 'Approved')
            {
                purchReqTable.PurchReqStatus = PurchReqStatus::Approved;
                // Trigger further processing (PO creation, etc.)
                this.triggerPostApprovalProcessing(_purchReqId);
            }
            else
            {
                purchReqTable.PurchReqStatus = PurchReqStatus::Rejected;
            }

            purchReqTable.update();

            // Create approval journal entry
            approvalJournal.clear();
            approvalJournal.PurchReqId = _purchReqId;
            approvalJournal.ApprovalDecision = _decision;
            approvalJournal.Comments = _comments;
            approvalJournal.ApprovedBy = _approvedBy;
            approvalJournal.ApprovalDate = today();
            approvalJournal.ApprovalTime = timeNow();
            approvalJournal.insert();

            success = true;

            info(strFmt('Purchase requisition %1 %2 by %3', _purchReqId, _decision, _approvedBy));
        }

        return success;
    }

    /// <summary>
    /// Trigger post-approval business processes
    /// </summary>
    private void triggerPostApprovalProcessing(PurchReqId _purchReqId)
    {
        // Could trigger another Power Automate flow for PO creation
        PurchReqApprovedBusinessEvent::newFromPurchReq(_purchReqId).send();
    }
}

