/// <summary>
/// Custom data entity for virtual table consumption
/// Optimizes query performance and implements field-level security
/// </summary>
[DataEntity,
 DataEntityPublic(true),
 DataEntityCategory('Master')]
public final class CustomVirtualCustomerEntity extends common
{
    // Primary key field - required for virtual tables
    [DataEntityKey, DataField('AccountNum')]
    public CustAccount AccountNum;

    [DataField('Name')]
    public Name Name;

    [DataField('CurrencyCode')]
    public CurrencyCode CurrencyCode;

    [DataField('CreditLimit')]
    public AmountMST CreditLimit;

    // Computed field for virtual table consumers
    [DataField('IsBlocked')]
    public NoYes IsBlocked;

    /// <summary>
    /// Optimized select method for virtual table queries
    /// Implements explicit joins and field selection
    /// </summary>
    public void select()
    {
        CustTable custTable;
        DirPartyTable partyTable;

        // Use explicit joins for better query plan
        select AccountNum, CurrencyCode, CreditMax, Blocked from custTable
            join Name from partyTable
            where partyTable.RecId == custTable.Party
                && custTable.DataAreaId == curext()
                && this.validateAccess(custTable);

        if (custTable.RecId)
        {
            this.AccountNum = custTable.AccountNum;
            this.Name = partyTable.Name;
            this.CurrencyCode = custTable.Currency;
            this.CreditLimit = custTable.CreditMax;
            this.IsBlocked = custTable.Blocked;
        }
    }

    /// <summary>
    /// Security validation for field-level access
    /// </summary>
    private boolean validateAccess(CustTable _custTable)
    {
        SecurityRights rights;

        // Check table-level security
        rights = SecurityPolicy::checkAccess(
            tableNum(CustTable),
            _custTable.RecId,
            SecurityAction::Read);

        // Additional business logic security
        if (rights == SecurityRights::NoAccess)
        {
            return false;
        }

        // Implement custom security rules
        return this.validateCustomerAccess(_custTable.AccountNum);
    }

    /// <summary>
    /// Custom business security validation
    /// </summary>
    private boolean validateCustomerAccess(CustAccount _accountNum)
    {
        UserInfo userInfo = UserInfo::find();

        // Example: Restrict access based on user's sales territory
        if (userInfo.salesTerritoryId)
        {
            CustTable custTable = CustTable::find(_accountNum);
            return (custTable.salesTerritoryId == userInfo.salesTerritoryId);
        }

        return true;
    }

    /// <summary>
    /// Override validateWrite to prevent updates via virtual table
    /// Virtual tables should typically be read-only
    /// </summary>
    public boolean validateWrite()
    {
        throw error("@SYS103832"); // Updates not allowed through virtual table
    }

    /// <summary>
    /// Implement paging support for large datasets
    /// </summary>
    public QueryRun buildQuery()
    {
        QueryRun queryRun;
        Query query = new Query();
        QueryBuildDataSource qbds;

        qbds = query.dataSourceTable(tableNum(CustTable));
        qbds.addRange(fieldNum(CustTable, DataAreaId)).value(curext());

        // Add performance hints
        qbds.orderBy(fieldNum(CustTable, AccountNum));
        qbds.indexHint(CustTableIdx);

        queryRun = new QueryRun(query);
        return queryRun;
    }
}

/// <summary>
/// Performance monitoring for virtual table queries
/// Tracks query patterns and provides optimization recommendations
/// </summary>
final class VirtualTablePerformanceMonitor
{
    private Map queryStatsMap;
    private int maxQueryTime;
    private boolean enableDetailedLogging;

    public void new()
    {
        queryStatsMap = new Map(Types::String, Types::Container);
        maxQueryTime = 5000; // 5 seconds threshold
        enableDetailedLogging = SysGlobalConfiguration::isFeatureEnabled(
            'VirtualTableDetailedLogging');
    }

    /// <summary>
    /// Monitor OData query execution
    /// Called from DataEntityController.get() method via CoC
    /// </summary>
    public void monitorQuery(str _entityName, str _odataQuery)
    {
        utcdatetime startTime = DateTimeUtil::utcNow();
        str queryHash = this.generateQueryHash(_entityName, _odataQuery);

        try
        {
            // Execute the actual query (placeholder for CoC integration)
            this.executeQuery(_entityName, _odataQuery);
        }
        catch (Exception::Error)
        {
            // Log query failures
            this.logQueryFailure(_entityName, _odataQuery, infolog.text());
            throw;
        }
        finally
        {
            int executionTime = DateTimeUtil::getDifference(
                DateTimeUtil::utcNow(), startTime);

            this.recordQueryStats(queryHash, _entityName, 
                _odataQuery, executionTime);

            if (executionTime > maxQueryTime)
            {
                this.flagSlowQuery(_entityName, _odataQuery, executionTime);
            }
        }
    }

    /// <summary>
    /// Generate unique hash for query pattern analysis
    /// </summary>
    private str generateQueryHash(str _entityName, str _odataQuery)
    {
        str normalizedQuery = this.normalizeQuery(_odataQuery);
        return System.Security.Cryptography.SHA1::computeHash(
            _entityName + '|' + normalizedQuery);
    }

    /// <summary>
    /// Normalize OData query for pattern matching
    /// </summary>
    private str normalizeQuery(str _query)
    {
        str normalized = _query;

        // Remove specific values, keep structure
        normalized = strReplace(normalized, 
            @"'([^']*)'" /* regex pattern */, "'<VALUE>'");
        normalized = strReplace(normalized, 
            @"\d+" /* numeric values */, "<NUM>");

        return strLwr(normalized);
    }

    /// <summary>
    /// Record query execution statistics
    /// </summary>
    private void recordQueryStats(str _queryHash, str _entityName, 
        str _query, int _executionTime)
    {
        container stats;
        int count, totalTime, avgTime;

        if (queryStatsMap.exists(_queryHash))
        {
            stats = queryStatsMap.lookup(_queryHash);
            count = conPeek(stats, 1) + 1;
            totalTime = conPeek(stats, 2) + _executionTime;
        }
        else
        {
            count = 1;
            totalTime = _executionTime;
        }

        avgTime = totalTime / count;

        stats = [count, totalTime, avgTime, _entityName, _query];
        queryStatsMap.insert(_queryHash, stats);

        if (enableDetailedLogging)
        {
            info(strFmt("Virtual table query: %1, Time: %2ms, Avg: %3ms",
                _entityName, _executionTime, avgTime));
        }
    }

    /// <summary>
    /// Flag slow queries for optimization
    /// </summary>
    private void flagSlowQuery(str _entityName, str _query, int _time)
    {
        VirtualTableSlowQueryLog log;

        ttsbegin;
        try
        {
            log.clear();
            log.EntityName = _entityName;
            log.QueryText = _query;
            log.ExecutionTime = _time;
            log.CreatedDateTime = DateTimeUtil::utcNow();
            log.UserId = curUserId();
            log.insert();

            warning(strFmt("Slow virtual table query detected: %1 (%2ms)",
                _entityName, _time));

            ttscommit;
        }
        catch (Exception::Error)
        {
            ttsabort;
            error("Failed to log slow query");
        }
    }

    /// <summary>
    /// Generate performance report
    /// </summary>
    public void generatePerformanceReport()
    {
        MapEnumerator enumerator = queryStatsMap.getEnumerator();
        container stats;
        str report = "Virtual Table Performance Report:\n";

        while (enumerator.moveNext())
        {
            stats = enumerator.currentValue();
            report += strFmt("Entity: %1, Count: %2, Avg Time: %3ms\n",
                conPeek(stats, 4), // EntityName
                conPeek(stats, 1), // Count
                conPeek(stats, 3)  // AvgTime
            );
        }

        info(report);
    }

    /// <summary>
    /// Placeholder for actual query execution
    /// In reality, this would be integrated via CoC
    /// </summary>
    private void executeQuery(str _entityName, str _query)
    {
        // This method would be implemented as a Chain of Command
        // on the appropriate DataEntityController method
    }

    /// <summary>
    /// Log query failures for troubleshooting
    /// </summary>
    private void logQueryFailure(str _entityName, str _query, str _error)
    {
        System.Diagnostics.EventLog::writeEntry(
            "VirtualTableMonitor",
            strFmt("Query failed - Entity: %1, Error: %2", 
                _entityName, _error),
            System.Diagnostics.EventLogEntryType::Error);
    }
}

/// <summary>
/// Custom job for exporting customer data to Azure Data Lake
/// Extends DMFEntityExportToDataLakeJob for production scenarios
/// </summary>
class CustomCustDataLakeExportJob extends DMFEntityExportToDataLakeJob
{
    private DMFDataLakeExportContract exportContract;
    private DMFDataLakeExportLog exportLog;

    protected void new()
    {
        super();
    }

    public static void main(Args _args)
    {
        CustomCustDataLakeExportJob job = new CustomCustDataLakeExportJob();
        job.run();
    }

    protected void initializeExportParameters()
    {
        DMFDataLakeExportParameters parameters;

        ttsbegin;

        select firstonly parameters
            where parameters.EntityName == 'CustTableEntity'
               && parameters.IsActive == NoYes::Yes;

        if (!parameters)
        {
            throw error("Data Lake export parameters not configured for CustTableEntity");
        }

        // Initialize contract with validated parameters
        exportContract = new DMFDataLakeExportContract();
        exportContract.parmEntityName('CustTableEntity');
        exportContract.parmContainerName(parameters.ContainerName);
        exportContract.parmStorageAccountName(parameters.StorageAccountName);
        exportContract.parmIncrementalExport(parameters.EnableIncremental);
        exportContract.parmPartitionByModifiedDate(true);

        // Set up incremental export from last successful run
        if (parameters.EnableIncremental)
        {
            DMFDataLakeExportLog lastSuccessfulExport;
            select firstonly lastSuccessfulExport
                order by CreatedDateTime desc
                where lastSuccessfulExport.EntityName == 'CustTableEntity'
                   && lastSuccessfulExport.Status == DMFDataLakeExportStatus::Completed;

            if (lastSuccessfulExport)
            {
                exportContract.parmFromDateTime(lastSuccessfulExport.CreatedDateTime);
                info(strFmt("Incremental export from: %1", lastSuccessfulExport.CreatedDateTime));
            }
        }

        ttscommit;
    }

    protected void executeExport()
    {
        DMFDataLakeExportService exportService;
        DMFEntityExportToDataLakeJobArgs jobArgs;

        try
        {
            ttsbegin;

            // Create export log entry
            exportLog.EntityName = exportContract.parmEntityName();
            exportLog.Status = DMFDataLakeExportStatus::InProgress;
            exportLog.CreatedDateTime = DateTimeUtil::getSystemDateTime();
            exportLog.RecordCount = 0;
            exportLog.insert();

            ttscommit;

            // Initialize export service
            exportService = new DMFDataLakeExportService();
            jobArgs = DMFEntityExportToDataLakeJobArgs::construct();
            jobArgs.parmContract(exportContract);
            jobArgs.parmExportLogRecId(exportLog.RecId);

            // Execute with retry logic
            int retryCount = 0;
            boolean success = false;

            while (retryCount < 3 && !success)
            {
                try
                {
                    exportService.exportEntityToDataLake(jobArgs);
                    success = true;

                    ttsbegin;
                    select forupdate exportLog where exportLog.RecId == exportLog.RecId;
                    exportLog.Status = DMFDataLakeExportStatus::Completed;
                    exportLog.CompletedDateTime = DateTimeUtil::getSystemDateTime();
                    exportLog.update();
                    ttscommit;

                    info(strFmt("Successfully exported %1 records to Data Lake", exportLog.RecordCount));
                }
                catch (Exception::Error)
                {
                    retryCount++;
                    if (retryCount >= 3)
                    {
                        throw;
                    }
                    info(strFmt("Export attempt %1 failed, retrying...", retryCount));
                    sleep(retryCount * 1000); // Exponential backoff
                }
            }
        }
        catch (Exception::Error)
        {
            ttsbegin;
            select forupdate exportLog where exportLog.RecId == exportLog.RecId;
            exportLog.Status = DMFDataLakeExportStatus::Failed;
            exportLog.ErrorMessage = infolog.text();
            exportLog.CompletedDateTime = DateTimeUtil::getSystemDateTime();
            exportLog.update();
            ttscommit;

            error(strFmt("Data Lake export failed: %1", infolog.text()));
            throw;
        }
    }

    public void run()
    {
        this.initializeExportParameters();
        this.executeExport();
    }
}

/// <summary>
/// Monitoring service for Data Lake exports with partition management
/// Handles incremental export coordination and export health monitoring
/// </summary>
class DMFDataLakeExportMonitorService extends SysOperationServiceBase
{
    private DMFDataLakeExportMonitorContract contract;

    protected void new()
    {
        super();
    }

    public void monitorExports(DMFDataLakeExportMonitorContract _contract)
    {
        contract = _contract;
        this.validateExportHealth();
        this.managePartitions();
        this.triggerIncrementalExports();
    }

    private void validateExportHealth()
    {
        DMFDataLakeExportLog exportLog;
        List failedExports = new List(Types::String);

        // Check for stuck exports (running > 2 hours)
        while select exportLog
            where exportLog.Status == DMFDataLakeExportStatus::InProgress
               && DateTimeUtil::getDifference(exportLog.CreatedDateTime, DateTimeUtil::getSystemDateTime()) > 7200
        {
            ttsbegin;
            exportLog.Status = DMFDataLakeExportStatus::Failed;
            exportLog.ErrorMessage = "Export timed out - exceeded 2 hour limit";
            exportLog.CompletedDateTime = DateTimeUtil::getSystemDateTime();
            exportLog.update();
            ttscommit;

            failedExports.addEnd(exportLog.EntityName);
        }

        // Check for failed exports in last 24 hours
        while select count(RecId) from exportLog
            where exportLog.Status == DMFDataLakeExportStatus::Failed
               && DateTimeUtil::getDifference(exportLog.CreatedDateTime, DateTimeUtil::getSystemDateTime()) < 86400
            group by EntityName
        {
            if (exportLog.RecId > contract.parmMaxFailureThreshold())
            {
                this.alertOnExportFailures(exportLog.EntityName, exportLog.RecId);
            }
        }

        if (failedExports.elements() > 0)
        {
            info(strFmt("Cleaned up %1 stuck export jobs", failedExports.elements()));
        }
    }

    private void managePartitions()
    {
        DMFDataLakePartitionLog partitionLog;
        date partitionDate = today();

        // Create daily partitions for active entities
        DMFDataLakeExportParameters parameters;
        while select parameters
            where parameters.IsActive == NoYes::Yes
               && parameters.PartitionStrategy == DMFDataLakePartitionStrategy::Daily
        {
            // Check if partition already exists
            select firstonly partitionLog
                where partitionLog.EntityName == parameters.EntityName
                   && partitionLog.PartitionDate == partitionDate;

            if (!partitionLog)
            {
                ttsbegin;
                partitionLog.clear();
                partitionLog.EntityName = parameters.EntityName;
                partitionLog.PartitionDate = partitionDate;
                partitionLog.PartitionPath = this.buildPartitionPath(parameters.EntityName, partitionDate);
                partitionLog.Status = DMFDataLakePartitionStatus::Created;
                partitionLog.CreatedDateTime = DateTimeUtil::getSystemDateTime();
                partitionLog.insert();
                ttscommit;

                info(strFmt("Created partition %1 for entity %2", partitionLog.PartitionPath, parameters.EntityName));
            }
        }
    }

    private str buildPartitionPath(str _entityName, date _partitionDate)
    {
        return strFmt("%1/year=%2/month=%3/day=%4",
            _entityName,
            year(_partitionDate),
            mthOfYr(_partitionDate),
            dayOfMth(_partitionDate));
    }

    private void triggerIncrementalExports()
    {
        DMFDataLakeExportParameters parameters;
        DMFDataLakeExportLog lastExport;

        while select parameters
            where parameters.IsActive == NoYes::Yes
               && parameters.EnableIncremental == NoYes::Yes
        {
            // Check last export time
            select firstonly lastExport
                order by CreatedDateTime desc
                where lastExport.EntityName == parameters.EntityName
                   && lastExport.Status == DMFDataLakeExportStatus::Completed;

            int minutesSinceLastExport = DateTimeUtil::getDifference(
                lastExport.CreatedDateTime,
                DateTimeUtil::getSystemDateTime()) / 60;

            if (minutesSinceLastExport >= parameters.IncrementalIntervalMinutes)
            {
                this.queueIncrementalExport(parameters.EntityName);
            }
        }
    }

    private void queueIncrementalExport(str _entityName)
    {
        BatchHeader batchHeader;
        BatchInfo batchInfo;

        ttsbegin;

        batchInfo = new BatchInfo();
        batchInfo.parmBatchExecutionType(BatchExecutionType::Server);
        batchInfo.parmCaption(strFmt("Incremental Data Lake Export - %1", _entityName));
        batchInfo.parmGroupId('DataLakeExport');

        CustomCustDataLakeExportJob job = new CustomCustDataLakeExportJob();
        batchInfo.parmObject(job);

        batchHeader = BatchHeader::construct();
        batchHeader.addTask(batchInfo);
        batchHeader.parmCaption(batchInfo.parmCaption());
        batchHeader.save();

        ttscommit;

        info(strFmt("Queued incremental export for entity: %1", _entityName));
    }

    private void alertOnExportFailures(str _entityName, int64 _failureCount)
    {
        // Integration point for alerting system
        EventInbox eventInbox;

        ttsbegin;
        eventInbox.AlertRule = 'DataLakeExportFailure';
        eventInbox.AlertTitle = strFmt("Data Lake Export Failures: %1", _entityName);
        eventInbox.AlertMessage = strFmt("%1 export failures detected for entity %2 in last 24 hours",
            _failureCount, _entityName);
        eventInbox.UserId = curUserId();
        eventInbox.InboxId = EventInboxId::Alert;
        eventInbox.Subject = eventInbox.AlertTitle;
        eventInbox.Message = eventInbox.AlertMessage;
        eventInbox.insert();
        ttscommit;

        warning(strFmt("High failure rate detected for %1: %2 failures", _entityName, _failureCount));
    }
}

