/// <summary>
/// Utility class for publishing customer-related business events
/// </summary>
public final class CustomerBusinessEventsHelper
{
    /// <summary>
    /// Publishes customer master changed event
    /// </summary>
    /// <param name="_custTable">Customer table record</param>
    /// <param name="_changeType">Type of change (Created, Updated, Deleted)</param>
    public static void publishCustomerMasterChanged(CustTable _custTable, str _changeType)
    {
        CustomerMasterChangedEventContract contract;
        DirPartyTable dirParty;
        LogisticsPostalAddress postalAddress;

        if (!_custTable.AccountNum)
        {
            throw error("@SYS325695"); // Invalid customer account
        }

        try
        {
            ttsbegin;

            // Initialize the contract
            contract = new CustomerMasterChangedEventContract();
            contract.initialize();

            // Populate basic customer data
            contract.parmCustAccount(_custTable.AccountNum);
            contract.parmCustGroup(_custTable.CustGroup);
            contract.parmChangeType(_changeType);

            // Get customer name from party
            select firstonly Name from dirParty
                where dirParty.RecId == _custTable.Party;

            contract.parmCustomerName(dirParty.Name);

            // Get primary address country
            select firstonly CountryRegionId from postalAddress
                where postalAddress.Location == DirParty::primaryPostalAddress(_custTable.Party)
                   && postalAddress.ValidFrom <= DateTimeUtil::utcNow()
                   && postalAddress.ValidTo >= DateTimeUtil::utcNow();

            contract.parmCountryRegion(postalAddress.CountryRegionId);

            // Publish the event
            BusinessEventsPublisher::publishBusinessEvent(contract);

            ttscommit;

            info(strFmt("Business event published for customer %1", _custTable.AccountNum));
        }
        catch (Exception::Error)
        {
            ttsabort;
            error(strFmt("Failed to publish business event for customer %1: %2", 
                        _custTable.AccountNum, infolog.text()));
            throw;
        }
    }

    /// <summary>
    /// Batch publishes multiple customer events for performance
    /// </summary>
    /// <param name="_custAccounts">Container of customer accounts</param>
    /// <param name="_changeType">Type of change</param>
    public static void publishCustomerMasterChangedBatch(container _custAccounts, str _changeType)
    {
        CustTable custTable;
        int i;
        int batchSize = 100;
        int processedCount = 0;

        for (i = 1; i <= conLen(_custAccounts); i++)
        {
            select firstonly custTable
                where custTable.AccountNum == conPeek(_custAccounts, i);

            if (custTable.RecId)
            {
                CustomerBusinessEventsHelper::publishCustomerMasterChanged(custTable, _changeType);
                processedCount++;

                // Commit in batches for performance
                if (processedCount % batchSize == 0)
                {
                    info(strFmt("Processed %1 customer events", processedCount));
                }
            }
        }

        info(strFmt("Completed publishing %1 customer business events", processedCount));
    }
}

/// <summary>
/// Chain of command extension for CustTable to auto-publish business events
/// </summary>
[ExtensionOf(tableStr(CustTable))]
public final class CustTable_BusinessEvents_Extension
{
    public void insert()
    {
        next insert();

        // Only publish if the insert was successful
        if (this.RecId)
        {
            try
            {
                CustomerBusinessEventsHelper::publishCustomerMasterChanged(this, 'Created');
            }
            catch (Exception::Error)
            {
                // Log error but don't fail the transaction
                warning(strFmt("Failed to publish business event for customer creation %1", this.AccountNum));
            }
        }
    }

    public void update()
    {
        CustTable originalRecord;
        boolean significantChange = false;

        // Capture original values before update
        select forupdate originalRecord
            where originalRecord.RecId == this.RecId;

        // Check for significant changes that warrant event publishing
        if (originalRecord.Name != this.Name ||
            originalRecord.CustGroup != this.CustGroup ||
            originalRecord.Blocked != this.Blocked ||
            originalRecord.CreditMax != this.CreditMax)
        {
            significantChange = true;
        }

        next update();

        if (significantChange)
        {
            try
            {
                CustomerBusinessEventsHelper::publishCustomerMasterChanged(this, 'Updated');
            }
            catch (Exception::Error)
            {
                warning(strFmt("Failed to publish business event for customer update %1", this.AccountNum));
            }
        }
    }

    public void delete()
    {
        CustAccount deletedAccount = this.AccountNum;

        next delete();

        // Publish after successful deletion
        try
        {
            // Create a temporary record for the event since original is deleted
            CustTable tempRecord;
            tempRecord.AccountNum = deletedAccount;
            CustomerBusinessEventsHelper::publishCustomerMasterChanged(tempRecord, 'Deleted');
        }
        catch (Exception::Error)
        {
            warning(strFmt("Failed to publish business event for customer deletion %1", deletedAccount));
        }
    }
}

