    /// </summary>
    public static void monitorWebhookDelivery()
    {
        BusinessEventsEndpoint endpoint;
        BusinessEventsDeliveryHistory deliveryHistory;
        int successCount = 0;
        int failureCount = 0;
        int retryCount = 0;

        while select endpoint
            where endpoint.Type == BusinessEventsEndpointType::HTTPSWebhook
               && endpoint.IsActive == NoYes::Yes
        {
            info(strFmt("\nEndpoint: %1", endpoint.Name));

            while select deliveryHistory
                order by CreatedDateTime desc
                where deliveryHistory.EndpointId == endpoint.RecId
                   && deliveryHistory.CreatedDateTime >= DateTimeUtil::addDays(DateTimeUtil::utcNow(), -1)
            {
                switch (deliveryHistory.Status)
                {
                    case BusinessEventsDeliveryStatus::Succeeded:
                        successCount++;
                        break;
                    case BusinessEventsDeliveryStatus::Failed:
                        failureCount++;
                        info(strFmt("  Failed delivery at %1: %2", 
                                   deliveryHistory.CreatedDateTime, 
                                   deliveryHistory.ErrorMessage));
                        break;
                    case BusinessEventsDeliveryStatus::Retrying:
                        retryCount++;
                        break;
                }
            }

            info(strFmt("  Last 24h: %1 success, %2 failed, %3 retrying", 
                       successCount, failureCount, retryCount));

            successCount = 0;
            failureCount = 0;
            retryCount = 0;
        }
    }
}

public class CustomOAuth2Service
{
    private str clientId;
    private str clientSecret;
    private str tenantId;
    private str scope;
    private str tokenEndpoint;
    private OAuth2Token cachedToken;

    public void new(str _clientId, str _clientSecret, str _tenantId, str _scope)
    {
        clientId = _clientId;
        clientSecret = _clientSecret;
        tenantId = _tenantId;
        scope = _scope;
        tokenEndpoint = strFmt('https://login.microsoftonline.com/%1/oauth2/v2.0/token', tenantId);
    }

    public str getAccessToken()
    {
        if (this.isTokenValid())
        {
            return cachedToken.AccessToken;
        }

        return this.acquireNewToken();
    }

    private boolean isTokenValid()
    {
        if (!cachedToken)
        {
            return false;
        }

        // Check if token expires within next 5 minutes
        utcDateTime expiryTime = cachedToken.ExpiresOn;
        utcDateTime currentTime = DateTimeUtil::utcNow();
        utcDateTime bufferTime = DateTimeUtil::addSeconds(currentTime, 300);

        return (expiryTime > bufferTime);
    }

    private str acquireNewToken()
    {
        System.Net.Http.HttpClient httpClient;
        System.Net.Http.HttpRequestMessage request;
        System.Net.Http.HttpResponseMessage response;
        System.Text.StringBuilder postData;
        str responseContent;

        try
        {
            httpClient = new System.Net.Http.HttpClient();
            request = new System.Net.Http.HttpRequestMessage(
                System.Net.Http.HttpMethod::Post, 
                tokenEndpoint
            );

            // Build form-encoded content
            postData = new System.Text.StringBuilder();
            postData.Append('grant_type=client_credentials');
            postData.Append(strFmt('&client_id=%1', System.Web.HttpUtility::UrlEncode(clientId)));
            postData.Append(strFmt('&client_secret=%1', System.Web.HttpUtility::UrlEncode(clientSecret)));
            postData.Append(strFmt('&scope=%1', System.Web.HttpUtility::UrlEncode(scope)));

            request.Content = new System.Net.Http.StringContent(
                postData.ToString(),
                System.Text.Encoding::UTF8,
                'application/x-www-form-urlencoded'
            );

            response = httpClient.SendAsync(request).Result;
            responseContent = response.Content.ReadAsStringAsync().Result;

            if (response.IsSuccessStatusCode)
            {
                this.parseTokenResponse(responseContent);
                info(strFmt('OAuth token acquired successfully. Expires: %1', cachedToken.ExpiresOn));
                return cachedToken.AccessToken;
            }
            else
            {
                error(strFmt('OAuth token acquisition failed. Status: %1, Response: %2', 
                    response.StatusCode, responseContent));
            }
        }
        catch (Exception::CLRError)
        {
            error(strFmt('CLR error during OAuth token acquisition: %1', CLRInterop::getLastException().ToString()));
        }
        catch
        {
            error('Unexpected error during OAuth token acquisition');
        }
        finally
        {
            if (httpClient)
            {
                httpClient.Dispose();
            }
        }

        return '';
    }

    private void parseTokenResponse(str jsonResponse)
    {
        System.Web.Script.Serialization.JavaScriptSerializer serializer;
        System.Collections.Generic.Dictionary<str, System.Object> tokenData;

        serializer = new System.Web.Script.Serialization.JavaScriptSerializer();
        tokenData = serializer.DeserializeObject(jsonResponse);

        cachedToken = new OAuth2Token();
        cachedToken.AccessToken = tokenData.get_Item('access_token');
        cachedToken.TokenType = tokenData.get_Item('token_type');

        // Calculate expiry time
        int expiresIn = tokenData.get_Item('expires_in');
        cachedToken.ExpiresOn = DateTimeUtil::addSeconds(DateTimeUtil::utcNow(), expiresIn);
    }
}

public class SecureApiClient
{
    private CustomOAuth2Service oauthService;
    private str baseApiUrl;
    private int maxRetries;

    public void new(str _baseApiUrl, CustomOAuth2Service _oauthService)
    {
        baseApiUrl = _baseApiUrl;
        oauthService = _oauthService;
        maxRetries = 3;
    }

    public str callSecureApi(str endpoint, str httpMethod = 'GET', str requestBody = '')
    {
        System.Net.Http.HttpClient httpClient;
        System.Net.Http.HttpRequestMessage request;
        System.Net.Http.HttpResponseMessage response;
        str accessToken;
        str fullUrl;
        str responseContent;
        int retryCount = 0;

        fullUrl = baseApiUrl + endpoint;

        while (retryCount <= maxRetries)
        {
            try
            {
                accessToken = oauthService.getAccessToken();

                if (!accessToken)
                {
                    error('Failed to obtain OAuth access token');
                    return '';
                }

                httpClient = new System.Net.Http.HttpClient();
                httpClient.DefaultRequestHeaders.Add('Authorization', strFmt('Bearer %1', accessToken));
                httpClient.DefaultRequestHeaders.Add('Accept', 'application/json');

                // Create request based on HTTP method
                switch (httpMethod.ToUpper())
                {
                    case 'GET':
                        request = new System.Net.Http.HttpRequestMessage(
                            System.Net.Http.HttpMethod::Get, fullUrl);
                        break;

                    case 'POST':
                        request = new System.Net.Http.HttpRequestMessage(
                            System.Net.Http.HttpMethod::Post, fullUrl);
                        if (requestBody)
                        {
                            request.Content = new System.Net.Http.StringContent(
                                requestBody,
                                System.Text.Encoding::UTF8,
                                'application/json'
                            );
                        }
                        break;

                    case 'PUT':
                        request = new System.Net.Http.HttpRequestMessage(
                            System.Net.Http.HttpMethod::Put, fullUrl);
                        if (requestBody)
                        {
                            request.Content = new System.Net.Http.StringContent(
                                requestBody,
                                System.Text.Encoding::UTF8,
                                'application/json'
                            );
                        }
                        break;

                    default:
                        error(strFmt('Unsupported HTTP method: %1', httpMethod));
                        return '';
                }

                response = httpClient.SendAsync(request).Result;
                responseContent = response.Content.ReadAsStringAsync().Result;

                if (response.IsSuccessStatusCode)
                {
                    info(strFmt('API call successful: %1 %2', httpMethod, endpoint));
                    return responseContent;
                }
                else if (response.StatusCode == System.Net.HttpStatusCode::Unauthorized && retryCount < maxRetries)
                {
                    // Token might be expired, clear cache and retry
                    warning(strFmt('Unauthorized response, clearing token cache and retrying. Attempt %1', retryCount + 1));
                    oauthService.clearTokenCache();
                    retryCount++;
                    continue;
                }
                else
                {
                    error(strFmt('API call failed: %1 %2. Status: %3, Response: %4', 
                        httpMethod, endpoint, response.StatusCode, responseContent));
                    return '';
                }
            }
            catch (Exception::CLRError)
            {
                error(strFmt('CLR error during API call: %1', CLRInterop::getLastException().ToString()));
                if (retryCount < maxRetries)
                {
                    retryCount++;
                    System.Threading.Thread::Sleep(1000 * retryCount); // Exponential backoff
                    continue;
                }
            }
            catch
            {
                error(strFmt('Unexpected error during API call to %1', endpoint));
            }
            finally
            {
                if (httpClient)
                {
                    httpClient.Dispose();
                }
            }

            break;
        }

        return '';
    }

    public boolean testConnection()
    {
        str testResponse = this.callSecureApi('/health', 'GET');
        return (testResponse != '');
    }
}

