/// <summary>
/// Advanced query optimization with execution plan analysis
/// Handles complex inventory transaction joins with proper hint usage
/// </summary>
class InventTransQueryOptimizer
{
    public static void analyzeInventoryMovements(ItemId _itemId)
    {
        Query                   query;
        QueryRun               queryRun;
        QueryBuildDataSource   qbdsInventTrans, qbdsInventDim, qbdsInventSum;
        QueryBuildLink         qblInventDim, qblInventSum;
        InventTrans            inventTrans;
        InventDim              inventDim;
        InventSum              inventSum;

        try
        {
            // Enable trace for execution plan analysis
            if (isTraceEnabled())
            {
                startTrace('InventTransOptimization');
            }

            query = new Query();

            // Primary data source - use clustered index on RecId
            qbdsInventTrans = query.addDataSource(tableNum(InventTrans));
            qbdsInventTrans.addRange(fieldNum(InventTrans, ItemId)).value(_itemId);
            qbdsInventTrans.addRange(fieldNum(InventTrans, StatusIssue)).value(
                strFmt('(%1,%2)', 
                    enum2int(StatusIssue::Sold),
                    enum2int(StatusIssue::Deducted)));

            // Optimize join order - smaller table first
            qbdsInventDim = qbdsInventTrans.addDataSource(tableNum(InventDim));
            qblInventDim = qbdsInventDim.addLink(fieldNum(InventTrans, InventDimId),
                                               fieldNum(InventDim, inventDimId));
            qblInventDim.joinMode(JoinMode::InnerJoin);

            // Use EXISTS instead of JOIN for existence checks
            qbdsInventSum = qbdsInventTrans.addDataSource(tableNum(InventSum));
            qblInventSum = qbdsInventSum.addLink(fieldNum(InventTrans, ItemId),
                                               fieldNum(InventSum, ItemId));
            qblInventSum.joinMode(JoinMode::ExistsJoin); // More efficient than InnerJoin

            // Apply advanced query hints
            qbdsInventTrans.queryHint(AOSQueryHint::ForceNestedLoop, '1');
            qbdsInventTrans.queryHint(AOSQueryHint::MaxDop, '4'); // Limit parallelism

            // Order by RecId for optimal read-ahead
            qbdsInventTrans.addOrderByField(fieldNum(InventTrans, RecId));

            queryRun = new QueryRun(query);

            int recordCount = 0;
            utcdatetime startTime = DateTimeUtil::utcNow();

            while (queryRun.next())
            {
                inventTrans = queryRun.get(tableNum(InventTrans));
                inventDim = queryRun.get(tableNum(InventDim));

                // Process with minimal overhead
                recordCount++;

                if (recordCount % 1000 == 0)
                {
                    // Checkpoint every 1000 records
                    info(strFmt('Processed %1 records', recordCount));
                }
            }

            utcdatetime endTime = DateTimeUtil::utcNow();
            int64 duration = DateTimeUtil::getDifference(endTime, startTime);

            info(strFmt('Query completed: %1 records in %2 seconds', 
                recordCount, 
                duration / 1000));

            if (isTraceEnabled())
            {
                stopTrace();
                analyzeTraceResults();
            }
        }
        catch (Exception::Error)
        {
            error('Inventory query optimization failed');
            throw Exception::Error;
        }
    }

    private static boolean isTraceEnabled()
    {
        // Check if SQL trace is enabled for performance analysis
        return (runningOnServer() && 
                SysGlobalConfiguration::getValue(#TraceEnabled) == '1');
    }

    private static void startTrace(str _traceName)
    {
        // Implementation would integrate with Trace Parser or SQL Profiler
        info(strFmt('Starting trace: %1', _traceName));
    }

    private static void stopTrace()
    {
        info('Trace stopped - analyze results in Trace Parser');
    }

    private static void analyzeTraceResults()
    {
        // Parse execution plans and identify bottlenecks
        info('Analyze execution plan for:');
        info('- Index seek vs scan operations');
        info('- Join algorithms (nested loop, hash, merge)');
        info('- Key lookups and RID lookups');
        info('- Parallelism and memory grants');
    }
}

/// <summary>
/// ANTI-PATTERN: Row-based inventory update - processes each record individually
/// This will perform terribly with large datasets (>1000 records)
/// </summary>
static void RowBasedInventoryUpdate()
{
    InventTable         inventTable;
    InventItemLocation  inventItemLocation;
    Counter             recordCount = 0;
    utcdatetime         startTime = DateTimeUtil::utcNow();

    try
    {
        ttsbegin;

        // Row-based approach: fetch each inventory item individually
        while select forupdate inventTable
            where inventTable.ItemType == ItemType::Item
               && inventTable.ItemGroupId == 'Audio'
        {
            // For each item, make separate query for location data
            select firstonly inventItemLocation
                where inventItemLocation.ItemId == inventTable.ItemId
                   && inventItemLocation.InventLocationId == '11';

            if (inventItemLocation.RecId)
            {
                // Individual update per record - expensive!
                inventTable.ModifiedDateTime = DateTimeUtil::utcNow();
                inventTable.update();
                recordCount++;

                // Artificial business logic to simulate processing
                if (recordCount % 100 == 0)
                {
                    info(strFmt("Processed %1 records (row-based)", recordCount));
                }
            }
        }

        ttscommit;

        info(strFmt("Row-based update completed: %1 records in %2 ms", 
             recordCount, 
             DateTimeUtil::getDifference(DateTimeUtil::utcNow(), startTime)));
    }
    catch (Exception::Error)
    {
        ttsabort;
        error("Row-based update failed: " + infolog.text());
        throw Exception::Error;
    }
}

/// <summary>
/// OPTIMIZED: Set-based inventory update using SQL joins and update_recordset
/// Processes thousands of records in single SQL statement
/// </summary>
static void SetBasedInventoryUpdate()
{
    InventTable         inventTable;
    InventItemLocation  inventItemLocation;
    utcdatetime         startTime = DateTimeUtil::utcNow();
    int64               recordsAffected;

    try
    {
        ttsbegin;

        // Set-based approach: single SQL statement with JOIN
        update_recordset inventTable
            setting ModifiedDateTime = DateTimeUtil::utcNow()
            exists join inventItemLocation
                where inventItemLocation.ItemId == inventTable.ItemId
                   && inventItemLocation.InventLocationId == '11'
            where inventTable.ItemType == ItemType::Item
               && inventTable.ItemGroupId == 'Audio';

        // Get affected row count for reporting
        recordsAffected = inventTable.RowCount();

        ttscommit;

        info(strFmt("Set-based update completed: %1 records in %2 ms", 
             recordsAffected, 
             DateTimeUtil::getDifference(DateTimeUtil::utcNow(), startTime)));
    }
    catch (Exception::Error)
    {
        ttsabort;
        error("Set-based update failed: " + infolog.text());
        throw Exception::Error;
    }
}

