        query = new Query();

        // Primary data source with index hint
        qbdsInventTable = query.addDataSource(tableNum(InventTable));
        qbdsInventTable.addRange(fieldNum(InventTable, ItemType)).value('0'); // ItemType::Item
        qbdsInventTable.orderBy(fieldNum(InventTable, ItemId));
        qbdsInventTable.addSelectionField(fieldNum(InventTable, ItemId));
        qbdsInventTable.addSelectionField(fieldNum(InventTable, ItemGroupId));

        // Optimized join - use exists join for better performance
        qbdsInventItemLocation = qbdsInventTable.addDataSource(tableNum(InventItemLocation));
        qbdsInventItemLocation.relations(true);
        qbdsInventItemLocation.joinMode(JoinMode::ExistsJoin);
        qbdsInventItemLocation.addRange(fieldNum(InventItemLocation, InventLocationId)).value('11');

        // Additional exists join for inventory dimensions if needed
        qbdsInventDim = qbdsInventItemLocation.addDataSource(tableNum(InventDim));
        qbdsInventDim.relations(true);
        qbdsInventDim.joinMode(JoinMode::ExistsJoin);

        // Range with IN operator for better SQL generation
        qbrItemGroup = qbdsInventTable.addRange(fieldNum(InventTable, ItemGroupId));
        qbrItemGroup.value('Audio,Parts,Service');

        // Execute with query plan caching
        queryRun = new QueryRun(query);
        queryRun.setCursor(); // Enable cursor for large result sets

        info("Generated SQL: " + queryRun.query().dataSourceTable(tableNum(InventTable)).toString());

        // Process results efficiently
        while (queryRun.next())
        {
            inventTable = queryRun.get(tableNum(InventTable));
            recordCount++;

            // Process record (read-only operations)
            if (recordCount % 1000 == 0)
            {
                info(strFmt("Processed %1 records", recordCount));
            }
