// Custom parameter table with EntireTable caching
// AOT: Tables/MyModuleParameters
public class MyModuleParametersTable extends common
{
    // CacheLookup = EntireTable in AOT properties
    // PrimaryIndex = ModuleId (typically single record per module)

    /// <summary>
    /// Retrieves parameters for a specific module with caching
    /// </summary>
    /// <param name="_moduleId">The module identifier</param>
    /// <returns>Parameter record or empty buffer</returns>
    public static MyModuleParameters find(ModuleId _moduleId, boolean _forUpdate = false)
    {
        MyModuleParameters parameters;

        if (_forUpdate)
        {
            // Bypass cache for updates to ensure data consistency
            select forupdate parameters
                where parameters.ModuleId == _moduleId;
        }
        else
        {
            // Utilize EntireTable cache - entire table loaded on first access
            select firstonly parameters
                where parameters.ModuleId == _moduleId;
        }

        return parameters;
    }

    /// <summary>
    /// Demonstrates cache impact measurement
    /// </summary>
    public static void measureCachePerformance()
    {
        int64 startTime, endTime;
        MyModuleParameters params;

        // First access - triggers full table load into cache
        startTime = WinAPIServer::getTickCount();
        params = MyModuleParameters::find('INVENTORY');
        endTime = WinAPIServer::getTickCount();
        info(strFmt('First access (cache load): %1 ms', endTime - startTime));

        // Subsequent accesses - served from cache
        startTime = WinAPIServer::getTickCount();
        params = MyModuleParameters::find('SALES');
        endTime = WinAPIServer::getTickCount();
        info(strFmt('Cached access: %1 ms', endTime - startTime));

        // Display cache statistics
        info(strFmt('Cache entries: %1', 
            Global::getCacheStatistics(tableNum(MyModuleParameters))));
    }

    /// <summary>
    /// Forces cache invalidation when parameters change
    /// </summary>
    public void update()
    {
        ttsbegin;

        super();

        // Explicit cache flush for immediate consistency across sessions
        SysTableCacheScope::clearCache(tableNum(MyModuleParameters));

        ttscommit;

        info('Parameter cache invalidated - changes effective immediately');
    }
}

