    {
        ProductCategoryHierarchy hierarchy;

        // Found cache: only this specific record gets cached
        if (_forUpdate)
        {
            select forupdate hierarchy
                where hierarchy.CategoryId == _categoryId
                   && hierarchy.HierarchyLevel == _hierarchyLevel;
        }
        else
        {
            select firstonly hierarchy
                where hierarchy.CategoryId == _categoryId
                   && hierarchy.HierarchyLevel == _hierarchyLevel;
        }

