    {
        ListIterator iterator = new ListIterator(_categoryIds);
        ProductCategoryHierarchy hierarchy;
        CategoryId categoryId;
        int cacheHits = 0, dbQueries = 0;

        info('Processing category hierarchy with Found caching...');

        while (iterator.more())
