/// <summary>
/// Utility class for cache strategy analysis and optimization
/// </summary>
public final class CacheStrategyAnalyzer
{
    /// <summary>
    /// Analyzes table characteristics to recommend optimal caching strategy
    /// </summary>
    /// <param name="_tableId">Table ID to analyze</param>
    /// <returns>Recommended cache strategy with rationale</returns>
    public static container analyzeCacheStrategy(TableId _tableId)
    {
        DictTable dictTable = new DictTable(_tableId);
        Common tableBuffer = dictTable.makeRecord();
        SqlStatementExecutePermission perm;
        Statement stmt;
        ResultSet rs;
        int64 recordCount = 0;
        real avgRecordSize = 0;
        str recommendation, rationale;

        try
        {
            // Get table statistics
            perm = new SqlStatementExecutePermission(
                strFmt('SELECT COUNT(*), AVG(DATALENGTH(*)) FROM %1', 
                       dictTable.name(DbBackend::Sql)));
            perm.assert();

            stmt = new Statement();
            stmt.parmSqlStatement(perm.getSqlStatement());
            rs = stmt.executeQuery();

            if (rs.next())
            {
                recordCount = rs.getInteger(1);
                avgRecordSize = rs.getReal(2);
            }

            // Analysis logic based on table characteristics
            real estimatedTableSize = recordCount * avgRecordSize;

            if (recordCount <= 1000 && estimatedTableSize <= 1024 * 1024) // 1MB
            {
                recommendation = 'EntireTable';
                rationale = strFmt(
                    'Small table (%1 records, %2 KB) - EntireTable provides optimal performance',
                    recordCount, estimatedTableSize / 1024);
            }
            else if (recordCount > 100000 || estimatedTableSize > 10 * 1024 * 1024) // 10MB
            {
                recommendation = 'Found';
                rationale = strFmt(
                    'Large table (%1 records, %2 MB) - Found caching prevents memory exhaustion',
                    recordCount, estimatedTableSize / (1024 * 1024));
            }
            else
            {
                // Medium size - analyze access patterns
                if (CacheStrategyAnalyzer::hasFrequentRangeQueries(_tableId))
                {
                    recommendation = 'EntireTable';
                    rationale = 'Medium table with range query patterns benefits from EntireTable';
                }
                else
                {
                    recommendation = 'Found';
                    rationale = 'Medium table with point lookups - Found caching recommended';
                }
            }
        }
        catch (Exception::Error)
        {
            recommendation = 'NotInTTS';
            rationale = 'Analysis failed - consider NotInTTS for transaction safety';
        }
        finally
        {
            CodeAccessPermission::revertAssert();
        }

        return [recommendation, rationale, recordCount, estimatedTableSize];
    }

    /// <summary>
    /// Detects if table has indexes suggesting frequent range queries
    /// </summary>
    private static boolean hasFrequentRangeQueries(TableId _tableId)
    {
        DictTable dictTable = new DictTable(_tableId);
        DictIndex dictIndex;
        int indexCount = dictTable.indexCnt();
        int nonUniqueIndexes = 0;

        for (int i = 1; i <= indexCount; i++)
        {
            dictIndex = new DictIndex(_tableId, dictTable.indexCnt2Id(i));

            if (!dictIndex.isUnique())
            {
                nonUniqueIndexes++;
            }
        }

        // Heuristic: multiple non-unique indexes suggest range query patterns
        return nonUniqueIndexes >= 2;
    }

    /// <summary>
    /// Benchmarks cache performance for a specific table
    /// </summary>
    /// <param name="_tableId">Table to benchmark</param>
    /// <param name="_iterations">Number of test iterations</param>
    public static void benchmarkCachePerformance(TableId _tableId, int _iterations = 1000)
    {
        DictTable dictTable = new DictTable(_tableId);
        Common tableBuffer;
        int64 startTime, endTime, totalTime = 0;
        int successCount = 0;

        info(strFmt('Benchmarking cache performance for table: %1', dictTable.name()));

        for (int i = 1; i <= _iterations; i++)
        {
            tableBuffer = dictTable.makeRecord();

            startTime = WinAPIServer::getTickCount();

            // Simulate random record access
            select firstonly tableBuffer;

            endTime = WinAPIServer::getTickCount();

            if (tableBuffer.RecId)
            {
                totalTime += (endTime - startTime);
                successCount++;
            }
        }

        if (successCount > 0)
        {
            real avgTime = totalTime / successCount;
            info(strFmt('Average query time: %1 ms (%2 successful queries)', 
                avgTime, successCount));

            // Performance classification
            if (avgTime < 1)
            {
                info('Performance: EXCELLENT (likely cached)');
            }
            else if (avgTime < 5)
            {
                info('Performance: GOOD');
            }
            else
            {
                info('Performance: NEEDS OPTIMIZATION');
            }
        }
    }
}

using System.Threading.Tasks;
using System.Net.Http;

class AsyncServiceHelper
{
    public static async Task<str> callExternalServiceAsync(str endpoint, str jsonData)
    {
        System.Net.Http.HttpClient httpClient;
        System.Net.Http.StringContent content;
        System.Net.Http.HttpResponseMessage response;
        str result;

        try
        {
            httpClient = new System.Net.Http.HttpClient();
            content = new System.Net.Http.StringContent(jsonData);
            content.Headers.Add('Content-Type', 'application/json');

            response = await httpClient.PostAsync(endpoint, content);

            if (response.IsSuccessStatusCode)
            {
                result = await response.Content.ReadAsStringAsync();
                info(strFmt("Service call successful: %1", result));
            }
            else
            {
                error(strFmt("Service call failed with status: %1", response.StatusCode));
                result = '';
            }
        }
        catch (System.Exception ex)
        {
            error(strFmt("Exception in async service call: %1", ex.Message));
            result = '';
        }
        finally
        {
            if (httpClient)
                httpClient.Dispose();
        }

        return result;
    }

    public static void runMultipleServiceCallsAsync()
    {
        List endpoints = new List(Types::String);
        System.Threading.Tasks.Task[] tasks;
        int i;

        endpoints.addEnd('https://api.service1.com/data');
        endpoints.addEnd('https://api.service2.com/data');
        endpoints.addEnd('https://api.service3.com/data');

        tasks = new System.Threading.Tasks.Task[endpoints.elements()]();

        for (i = 1; i <= endpoints.elements(); i++)
        {
            tasks[i-1] = AsyncServiceHelper::callExternalServiceAsync(endpoints.value(i), '{}');
        }

        System.Threading.Tasks.Task::WaitAll(tasks);
        info("All service calls completed");
    }
}

class ParallelBatchProcessor extends RunBaseBatch
{
    private int batchSize = 1000;
    private int maxDegreeOfParallelism = 4;

    protected void run()
    {
        CustTable custTable;
        System.Collections.Generic.List<System.Object> customerBatches;
        System.Threading.Tasks.ParallelOptions parallelOptions;
        System.Threading.CancellationTokenSource cancellationTokenSource;
        int totalRecords;
        Counter processedRecords;

        try
        {
            // Count total records for progress tracking
            select count(RecId) from custTable;
            totalRecords = custTable.RecId;

            if (totalRecords == 0)
            {
                info("No customer records to process");
                return;
            }

            customerBatches = this.createCustomerBatches();
            cancellationTokenSource = new System.Threading.CancellationTokenSource();

            parallelOptions = new System.Threading.Tasks.ParallelOptions();
            parallelOptions.MaxDegreeOfParallelism = maxDegreeOfParallelism;
            parallelOptions.CancellationToken = cancellationTokenSource.Token;

            System.Threading.Tasks.Parallel::ForEach(
                customerBatches,
                parallelOptions,
                new System.Action<System.Object>(this, staticDelegateMethodStr(ParallelBatchProcessor, processBatchDelegate))
            );

            info(strFmt("Parallel processing completed for %1 customers", totalRecords));
        }
        catch (System.OperationCanceledException ex)
        {
            warning("Batch processing was cancelled");
        }
        catch (System.AggregateException ex)
        {
            error(strFmt("Multiple errors occurred during parallel processing: %1", ex.Message));
            // Log individual exceptions
            var innerExceptions = ex.InnerExceptions.GetEnumerator();
            while (innerExceptions.MoveNext())
            {
                error(strFmt("Inner exception: %1", innerExceptions.Current.Message));
            }
        }
        catch (Exception ex)
        {
            error(strFmt("Unexpected error in parallel batch processing: %1", ex.Message));
        }
    }

    private System.Collections.Generic.List<System.Object> createCustomerBatches()
    {
        CustTable custTable;
        System.Collections.Generic.List<System.Object> batches;
        System.Collections.Generic.List<System.String> currentBatch;
        Counter batchCount;

        batches = new System.Collections.Generic.List<System.Object>();
        currentBatch = new System.Collections.Generic.List<System.String>();

        while select AccountNum from custTable
        {
            currentBatch.Add(custTable.AccountNum);
            batchCount++;

            if (batchCount >= batchSize)
            {
                batches.Add(currentBatch);
                currentBatch = new System.Collections.Generic.List<System.String>();
                batchCount = 0;
            }
        }

        // Add remaining records
        if (currentBatch.Count > 0)
        {
            batches.Add(currentBatch);
        }

        return batches;
    }

    public static void processBatchDelegate(System.Object batch)
    {
        System.Collections.Generic.List<System.String> customerBatch;
        CustTable custTable;
        str accountNum;

        customerBatch = batch as System.Collections.Generic.List<System.String>;

        if (!customerBatch)
            return;

        try
        {
            ttsbegin;

            var enumerator = customerBatch.GetEnumerator();
            while (enumerator.MoveNext())
            {
                accountNum = enumerator.Current;

                select forUpdate custTable
                    where custTable.AccountNum == accountNum;

                if (custTable)
                {
                    // Simulate complex processing
                    custTable.LastProcessedDateTime = DateTimeUtil::utcNow();
                    custTable.update();
                }
            }

            ttscommit;
            info(strFmt("Processed batch of %1 customers in thread %2", 
                       customerBatch.Count, 
                       System.Threading.Thread::CurrentThread.ManagedThreadId));
        }
        catch (Exception ex)
        {
            ttsabort;
            error(strFmt("Error processing customer batch: %1", ex.Message));
            throw ex;
        }
    }

    public static void main(Args _args)
    {
        ParallelBatchProcessor processor = new ParallelBatchProcessor();

        if (processor.prompt())
        {
            processor.run();
        }
    }
}

using System.Collections.Concurrent;
using System.Threading.Tasks;
using System.Threading;

class AsyncQueueProcessor
{
    private System.Collections.Concurrent.ConcurrentQueue<System.Object> workQueue;
    private System.Threading.CancellationTokenSource cancellationTokenSource;
    private System.Threading.Tasks.Task[] consumerTasks;
    private boolean isProcessing;

    public void new()
    {
        workQueue = new System.Collections.Concurrent.ConcurrentQueue<System.Object>();
        cancellationTokenSource = new System.Threading.CancellationTokenSource();
        isProcessing = false;
    }

    public void startProcessing(int consumerCount = 3)
    {
        if (isProcessing)
        {
            warning("Processing is already running");
            return;
        }

        isProcessing = true;
        consumerTasks = new System.Threading.Tasks.Task[consumerCount]();

        for (int i = 0; i < consumerCount; i++)
        {
            consumerTasks[i] = System.Threading.Tasks.Task::Run(
                new System.Action(this, methodStr(AsyncQueueProcessor, consumerWorker))
            );
        }

        info(strFmt("Started %1 consumer tasks", consumerCount));
    }

    public void enqueueWork(System.Object workItem)
    {
        if (!isProcessing)
        {
            error("Cannot enqueue work - processing not started");
            return;
        }

        workQueue.Enqueue(workItem);
    }

    public async Task stopProcessingAsync()
    {
        if (!isProcessing)
            return;

        cancellationTokenSource.Cancel();

        try
        {
            await System.Threading.Tasks.Task::WhenAll(consumerTasks);
        }
        catch (System.OperationCanceledException)
        {
            // Expected when cancellation is requested
        }

        isProcessing = false;
        info("All consumer tasks completed");
    }

    private void consumerWorker()
    {
        System.Object workItem;
        boolean hasItem;
        int threadId = System.Threading.Thread::CurrentThread.ManagedThreadId;

        info(strFmt("Consumer thread %1 started", threadId));

        while (!cancellationTokenSource.Token.IsCancellationRequested)
        {
            try
            {
                hasItem = workQueue.TryDequeue(workItem);

                if (hasItem && workItem)
                {
                    this.processWorkItem(workItem, threadId);
                }
                else
                {
                    // No work available, wait briefly before checking again
                    System.Threading.Thread::Sleep(100);
                }
            }
            catch (Exception ex)
            {
                error(strFmt("Error in consumer thread %1: %2", threadId, ex.Message));
            }
        }

        info(strFmt("Consumer thread %1 shutting down", threadId));
    }

    private void processWorkItem(System.Object workItem, int threadId)
    {
        // Simulate work processing
        VendTable vendTable;
        str vendAccount = workItem as System.String;

        if (!vendAccount)
            return;

        try
        {
            ttsbegin;

            select forUpdate vendTable
                where vendTable.AccountNum == vendAccount;

            if (vendTable)
            {
                vendTable.LastProcessedDateTime = DateTimeUtil::utcNow();
                vendTable.ProcessedByThread = threadId;
                vendTable.update();

                info(strFmt("Processed vendor %1 in thread %2", vendAccount, threadId));
            }

            ttscommit;
        }
        catch (Exception ex)
        {
            ttsabort;
            error(strFmt("Failed to process vendor %1 in thread %2: %3", 
                        vendAccount, threadId, ex.Message));
        }
    }

    public static void demonstrateProducerConsumer()
    {
        AsyncQueueProcessor processor = new AsyncQueueProcessor();
        VendTable vendTable;
        List vendorAccounts = new List(Types::String);

        // Collect vendor accounts to process
        while select AccountNum from vendTable
        {
            vendorAccounts.addEnd(vendTable.AccountNum);

            if (vendorAccounts.elements() >= 100) // Limit for demo
                break;
        }

        processor.startProcessing(4); // 4 consumer threads

        // Produce work items
        for (int i = 1; i <= vendorAccounts.elements(); i++)
        {
            processor.enqueueWork(vendorAccounts.value(i));
        }

        info(strFmt("Enqueued %1 vendor accounts for processing", vendorAccounts.elements()));

        // Let processing run for a while, then stop
        System.Threading.Thread::Sleep(5000);

        processor.stopProcessingAsync();
    }
}

