/// <summary>
/// ISV Configuration Manager for tenant-specific settings
/// </summary>
public final class ContosoWHConfigurationManager
{
    private ContosoWHParameters parameters;
    private str tenantId;

    protected void new(str _tenantId = '')
    {
        tenantId = _tenantId ? _tenantId : this.getCurrentTenantId();
        this.loadParameters();
    }

    public static ContosoWHConfigurationManager construct(str _tenantId = '')
    {
        return new ContosoWHConfigurationManager(_tenantId);
    }

    public boolean isFeatureEnabled(ContosoWHFeature _feature)
    {
        ContosoWHFeatureConfig featureConfig;
        boolean isEnabled = false;

        try
        {
            select firstonly featureConfig
                where featureConfig.TenantId == tenantId
                   && featureConfig.FeatureId == _feature
                   && featureConfig.IsEnabled == NoYes::Yes;

            isEnabled = featureConfig.RecId != 0;

            // Log feature usage for analytics
            this.logFeatureUsage(_feature, isEnabled);
        }
        catch (Exception::Error)
        {
            warning(strFmt("Failed to check feature status: %1", _feature));
        }

        return isEnabled;
    }

    public void updateConfiguration(Map _configUpdates)
    {
        ContosoWHFeatureConfig featureConfig;
        MapEnumerator enumerator = _configUpdates.getEnumerator();

        try
        {
            ttsbegin;

            while (enumerator.moveNext())
            {
                ContosoWHFeature feature = enumerator.currentKey();
                boolean enabled = enumerator.currentValue();

                select forupdate featureConfig
                    where featureConfig.TenantId == tenantId
                       && featureConfig.FeatureId == feature;

                if (!featureConfig.RecId)
                {
                    featureConfig.clear();
                    featureConfig.TenantId = tenantId;
                    featureConfig.FeatureId = feature;
                }

                featureConfig.IsEnabled = enabled ? NoYes::Yes : NoYes::No;
                featureConfig.LastModifiedBy = curUserId();
                featureConfig.LastModifiedDateTime = DateTimeUtil::getSystemDateTime();
                featureConfig.write();
            }

            ttscommit;
            info("Configuration updated successfully");
        }
        catch (Exception::Error)
        {
            error("Failed to update configuration");
            throw Exception::Error;
        }
    }

    private void loadParameters()
    {
        select firstonly parameters
            where parameters.TenantId == tenantId;

        if (!parameters.RecId)
        {
            this.createDefaultParameters();
        }
    }

    private void createDefaultParameters()
    {
        try
        {
            ttsbegin;

            parameters.clear();
            parameters.TenantId = tenantId;
            parameters.DefaultWarehouse = '24';
            parameters.EnableAdvancedPicking = NoYes::Yes;
            parameters.AutoCreateWork = NoYes::No;
            parameters.CreatedDateTime = DateTimeUtil::getSystemDateTime();
            parameters.write();

            ttscommit;
        }
        catch (Exception::Error)
        {
            error("Failed to create default parameters");
            throw Exception::Error;
        }
    }

    private str getCurrentTenantId()
    {
        return SysAppLifecycle::getTenantId();
    }

    private void logFeatureUsage(ContosoWHFeature _feature, boolean _enabled)
    {
        Map telemetryData = new Map(Types::String, Types::String);
        telemetryData.insert('Feature', enum2Str(_feature));
        telemetryData.insert('Enabled', _enabled ? 'true' : 'false');
        telemetryData.insert('TenantId', tenantId);

        SysTelemetryProvider::construct().logEvent('FeatureCheck', telemetryData);
    }
}

/// <summary>
/// Service class for validating deployable packages in ALM pipeline
/// </summary>
class ALMPackageValidationService extends SysOperationServiceBase
{
    /// <summary>
    /// Validates package integrity and dependencies
    /// </summary>
    /// <param name="_packagePath">Path to deployable package</param>
    /// <returns>ValidationResult contract</returns>
    public ALMValidationResultContract validatePackage(str _packagePath)
    {
        ALMValidationResultContract result = new ALMValidationResultContract();
        List errors = new List(Types::String);

        try
        {
            // Validate package structure
            if (!System.IO.Directory::Exists(_packagePath))
            {
                errors.addEnd("Package directory not found: " + _packagePath);
                result.parmIsValid(false);
                result.parmErrors(List::create(errors));
                return result;
            }

            // Check for required metadata files
            str metadataPath = _packagePath + "\\AOSService\\PackagesLocalDirectory";
            if (!System.IO.Directory::Exists(metadataPath))
            {
                errors.addEnd("Metadata directory missing in package");
            }

            // Validate model dependencies using ModelUtil integration
            this.validateModelDependencies(_packagePath, errors);

            // Check for circular references in custom models
            this.validateCircularReferences(_packagePath, errors);

            // Validate CIL assemblies exist
            this.validateCILAssemblies(_packagePath, errors);

            result.parmIsValid(errors.elements() == 0);
            result.parmErrors(List::create(errors));

            info(strFmt("Package validation completed: %1 errors found", errors.elements()));
        }
        catch (Exception::Error)
        {
            errors.addEnd("Fatal error during package validation: " + infolog.text());
            result.parmIsValid(false);
            result.parmErrors(List::create(errors));
        }

        return result;
    }

    private void validateModelDependencies(str _packagePath, List _errors)
    {
        // Integration with ModelUtil.exe for dependency validation
        System.Diagnostics.Process process = new System.Diagnostics.Process();
        System.Diagnostics.ProcessStartInfo startInfo = new System.Diagnostics.ProcessStartInfo();

        str modelUtilPath = "C:\\AOSService\\PackagesLocalDirectory\\Bin\\ModelUtil.exe";
        str arguments = strFmt("-list -metadatastorepath=\"%1\"", _packagePath + "\\AOSService\\PackagesLocalDirectory");

        startInfo.set_FileName(modelUtilPath);
        startInfo.set_Arguments(arguments);
        startInfo.set_UseShellExecute(false);
        startInfo.set_RedirectStandardOutput(true);

        process.set_StartInfo(startInfo);

        try
        {
            process.Start();
            str output = process.get_StandardOutput().ReadToEnd();
            process.WaitForExit();

            if (process.get_ExitCode() != 0)
            {
                _errors.addEnd("ModelUtil validation failed: " + output);
            }
        }
        catch (Exception::CLRError)
        {
            _errors.addEnd("Failed to execute ModelUtil.exe: " + CLRInterop::getLastException().ToString());
        }
        finally
        {
            if (process != null)
            {
                process.Dispose();
            }
        }
    }

    private void validateCircularReferences(str _packagePath, List _errors)
    {
        // Custom logic to detect circular model references
        Map modelMap = new Map(Types::String, Types::Container);

        // Scan all model manifest files for dependencies
        System.IO.DirectoryInfo packageDir = new System.IO.DirectoryInfo(_packagePath + "\\AOSService\\PackagesLocalDirectory");
        var directories = packageDir.GetDirectories();

        System.Collections.IEnumerator dirEnum = directories.GetEnumerator();
        while (dirEnum.MoveNext())
        {
            System.IO.DirectoryInfo modelDir = dirEnum.get_Current() as System.IO.DirectoryInfo;
            str manifestPath = modelDir.get_FullName() + "\\Descriptor\\" + modelDir.get_Name() + ".xml";

            if (System.IO.File::Exists(manifestPath))
            {
                // Parse XML to extract dependencies (simplified)
                container dependencies = this.parseModelDependencies(manifestPath);
                modelMap.insert(modelDir.get_Name(), dependencies);
            }
        }

        // Check for circular references using depth-first search
        MapEnumerator enumerator = modelMap.getEnumerator();
        while (enumerator.moveNext())
        {
            if (this.hasCircularReference(enumerator.currentKey(), modelMap, new Set(Types::String)))
            {
                _errors.addEnd(strFmt("Circular reference detected in model: %1", enumerator.currentKey()));
            }
        }
    }

    private container parseModelDependencies(str _manifestPath)
    {
        // Simplified XML parsing for model dependencies
        container dependencies = conNull();

        try
        {
            System.Xml.XmlDocument doc = new System.Xml.XmlDocument();
            doc.Load(_manifestPath);

            System.Xml.XmlNodeList dependencyNodes = doc.SelectNodes("//ModuleReference");
            System.Collections.IEnumerator nodeEnum = dependencyNodes.GetEnumerator();

            while (nodeEnum.MoveNext())
            {
                System.Xml.XmlNode node = nodeEnum.get_Current() as System.Xml.XmlNode;
                System.Xml.XmlAttribute nameAttr = node.get_Attributes().get_Item("name") as System.Xml.XmlAttribute;

                if (nameAttr != null)
                {
                    dependencies = conIns(dependencies, 1, nameAttr.get_Value());
                }
            }
        }
        catch (Exception::CLRError)
        {
            // Log error but continue validation
            warning(strFmt("Failed to parse model manifest: %1", _manifestPath));
        }

        return dependencies;
    }

    private boolean hasCircularReference(str _modelName, Map _modelMap, Set _visitedModels)
    {
        if (_visitedModels.in(_modelName))
        {
            return true; // Circular reference found
        }

        _visitedModels.add(_modelName);

        container dependencies = _modelMap.lookup(_modelName);
        int i;

        for (i = 1; i <= conLen(dependencies); i++)
        {
            str dependentModel = conPeek(dependencies, i);
            if (this.hasCircularReference(dependentModel, _modelMap, _visitedModels))
            {
                return true;
            }
        }

        _visitedModels.remove(_modelName);
        return false;
    }

    private void validateCILAssemblies(str _packagePath, List _errors)
    {
        // Validate that CIL assemblies are present and valid
        str cilPath = _packagePath + "\\AOSService\\PackagesLocalDirectory\\bin";

        if (!System.IO.Directory::Exists(cilPath))
        {
            _errors.addEnd("CIL assembly directory missing");
            return;
        }

        // Check for essential CIL files
        List requiredAssemblies = List::create(
            "Microsoft.Dynamics.AX.Xpp.Support.dll",
            "Microsoft.Dynamics.ApplicationPlatform.dll",
            "Microsoft.Dynamics.ApplicationFoundation.dll"
        );

        ListEnumerator assemblyEnum = requiredAssemblies.getEnumerator();
        while (assemblyEnum.moveNext())
        {
            str assemblyPath = cilPath + "\\" + assemblyEnum.current();
            if (!System.IO.File::Exists(assemblyPath))
            {
                _errors.addEnd(strFmt("Required CIL assembly missing: %1", assemblyEnum.current()));
            }
        }
    }
}

/// <summary>
/// Batch job for tracking D365 F&O deployment status in Azure DevOps ALM pipeline
/// </summary>
class ALMDeploymentTrackingBatch extends RunBaseBatch
{
    str azureDevOpsOrganization;
    str azureDevOpsProject;
    str personalAccessToken;
    int deploymentId;

    DialogField dlgAzureDevOpsOrg;
    DialogField dlgAzureDevOpsProject;
    DialogField dlgPAT;
    DialogField dlgDeploymentId;

    #define.CurrentVersion(1)
    #localmacro.CurrentList
        azureDevOpsOrganization,
        azureDevOpsProject,
        personalAccessToken,
        deploymentId
    #endmacro

    public container pack()
    {
        return [#CurrentVersion, #CurrentList];
    }

    public boolean unpack(container _packedClass)
    {
        Version version = RunBase::getVersion(_packedClass);

        switch (version)
        {
            case #CurrentVersion:
                [version, #CurrentList] = _packedClass;
                break;

            default:
                return false;
        }

        return true;
    }

    public void run()
    {
        ttsbegin;

        try
        {
            this.updateDeploymentStatus();
            this.createWorkItemsForErrors();
            this.notifyStakeholders();

            ttscommit;
            info("Deployment tracking completed successfully");
        }
        catch (Exception::Error)
        {
            ttsabort;
            error(strFmt("Deployment tracking failed: %1", infolog.text()));
        }
    }

    private void updateDeploymentStatus()
    {
        // Check LCS deployment status via API
        str lcsApiUrl = "https://lcs.dynamics.com/api/v2/DeploymentStatus/" + int2Str(deploymentId);

        System.Net.WebClient webClient = new System.Net.WebClient();
        System.Text.Encoding encoding = System.Text.Encoding::get_UTF8();

        try
        {
            // Add authentication headers
            webClient.get_Headers().Add("Authorization", "Bearer " + this.getLCSAccessToken());
            webClient.get_Headers().Add("Content-Type", "application/json");

            str response = webClient.DownloadString(lcsApiUrl);

            // Parse JSON response (simplified)
            container statusInfo = this.parseDeploymentStatus(response);
            str status = conPeek(statusInfo, 1);
            str errorMessage = conPeek(statusInfo, 2);

            // Update Azure DevOps work item
            this.updateAzureDevOpsWorkItem(status, errorMessage);

            // Log deployment status to custom table
            this.logDeploymentStatus(status, errorMessage);
        }
        catch (Exception::CLRError)
        {
            error(strFmt("Failed to retrieve deployment status: %1", CLRInterop::getLastException().ToString()));
        }
        finally
        {
            if (webClient != null)
            {
                webClient.Dispose();
            }
        }
    }

    private void updateAzureDevOpsWorkItem(str _status, str _errorMessage)
    {
        // Update work item via Azure DevOps REST API
        str workItemUrl = strFmt("https://dev.azure.com/%1/%2/_apis/wit/workitems/%3?api-version=6.0",
                                azureDevOpsOrganization, azureDevOpsProject, int2Str(deploymentId));

        System.Net.WebClient webClient = new System.Net.WebClient();
        System.Text.StringBuilder jsonBody = new System.Text.StringBuilder();

        try
        {
            // Construct JSON patch document
            jsonBody.Append("[");
            jsonBody.Append("{");
            jsonBody.Append("\"op\": \"add\",");
            jsonBody.Append("\"path\": \"/fields/System.State\",");
            jsonBody.Append(strFmt("\"value\": \"%1\"", _status));
            jsonBody.Append("},");

            if (_errorMessage)
            {
                jsonBody.Append("{");
                jsonBody.Append("\"op\": \"add\",");
                jsonBody.Append("\"path\": \"/fields/System.Description\",");
                jsonBody.Append(strFmt("\"value\": \"Deployment Error: %1\"", _errorMessage));
                jsonBody.Append("}");
            }
            else
            {
                // Remove last comma
                str jsonString = jsonBody.ToString();
                jsonString = subStr(jsonString, 1, strLen(jsonString) - 1);
                jsonBody = new System.Text.StringBuilder(jsonString);
            }

            jsonBody.Append("]");

            // Set headers
            str encodedCredentials = System.Convert::ToBase64String(
                System.Text.Encoding::get_ASCII().GetBytes(":" + personalAccessToken));

            webClient.get_Headers().Add("Authorization", "Basic " + encodedCredentials);
            webClient.get_Headers().Add("Content-Type", "application/json-patch+json");

            // Send PATCH request
            System.Text.Encoding encoding = System.Text.Encoding::get_UTF8();
            byte[] data = encoding.GetBytes(jsonBody.ToString());

            byte[] responseBytes = webClient.UploadData(workItemUrl, "PATCH", data);
            str response = encoding.GetString(responseBytes);

            info(strFmt("Work item %1 updated successfully", deploymentId));
        }
        catch (Exception::CLRError)
        {
            warning(strFmt("Failed to update Azure DevOps work item: %1", CLRInterop::getLastException().ToString()));
        }
        finally
        {
            if (webClient != null)
            {
                webClient.Dispose();
            }
        }
    }

    private void logDeploymentStatus(str _status, str _errorMessage)
    {
        // Log to custom deployment tracking table
        ALMDeploymentLog deploymentLog;

        deploymentLog.clear();
        deploymentLog.DeploymentId = deploymentId;
        deploymentLog.Environment = curExt();
        deploymentLog.Status = _status;
        deploymentLog.ErrorMessage = _errorMessage;
        deploymentLog.Timestamp = DateTimeUtil::utcNow();
        deploymentLog.CreatedBy = curuserid();

        deploymentLog.insert();
    }

    private void createWorkItemsForErrors()
    {
        // Create Azure DevOps bugs for deployment errors
        if (this.hasDeploymentErrors())
        {
            str bugUrl = strFmt("https://dev.azure.com/%1/%2/_apis/wit/workitems/$Bug?api-version=6.0",
                               azureDevOpsOrganization, azureDevOpsProject);

            System.Net.WebClient webClient = new System.Net.WebClient();

            try
            {
                str jsonBody = this.constructBugWorkItem();

                str encodedCredentials = System.Convert::ToBase64String(
                    System.Text.Encoding::get_ASCII().GetBytes(":" + personalAccessToken));

                webClient.get_Headers().Add("Authorization", "Basic " + encodedCredentials);
                webClient.get_Headers().Add("Content-Type", "application/json-patch+json");

                System.Text.Encoding encoding = System.Text.Encoding::get_UTF8();
                byte[] data = encoding.GetBytes(jsonBody);

                byte[] responseBytes = webClient.UploadData(bugUrl, "POST", data);
                str response = encoding.GetString(responseBytes);

                info("Bug work item created for deployment errors");
            }
            catch (Exception::CLRError)
            {
                warning(strFmt("Failed to create bug work item: %1", CLRInterop::getLastException().ToString()));
            }
            finally
            {
                if (webClient != null)
                {
                    webClient.Dispose();
                }
            }
        }
    }

    private str constructBugWorkItem()
    {
        System.Text.StringBuilder jsonBody = new System.Text.StringBuilder();

        jsonBody.Append("[");
        jsonBody.Append("{");
        jsonBody.Append("\"op\": \"add\",");
        jsonBody.Append("\"path\": \"/fields/System.Title\",");
        jsonBody.Append(strFmt("\"value\": \"D365 F&O Deployment %1 Failed\"", deploymentId));
        jsonBody.Append("},");
        jsonBody.Append("{");
        jsonBody.Append("\"op\": \"add\",");
        jsonBody.Append("\"path\": \"/fields/System.Description\",");
        jsonBody.Append("\"value\": \"Automatic bug created for deployment failure. Check deployment logs.\"");
        jsonBody.Append("},");
        jsonBody.Append("{");
        jsonBody.Append("\"op\": \"add\",");
        jsonBody.Append("\"path\": \"/fields/System.Tags\",");
        jsonBody.Append("\"value\": \"D365;Deployment;ALM\"");
        jsonBody.Append("}")
        jsonBody.Append("]");

        return jsonBody.ToString();
    }

    protected Object dialog()
    {
        DialogRunbase dialog = super();

        dlgAzureDevOpsOrg = dialog.addFieldValue(extendedTypeStr(Description), azureDevOpsOrganization, "Azure DevOps Organization");
        dlgAzureDevOpsProject = dialog.addFieldValue(extendedTypeStr(Name), azureDevOpsProject, "Azure DevOps Project");
        dlgPAT = dialog.addFieldValue(extendedTypeStr(Description), personalAccessToken, "Personal Access Token");
        dlgDeploymentId = dialog.addFieldValue(extendedTypeStr(Integer), deploymentId, "Deployment ID");

        return dialog;
    }

    public boolean getFromDialog()
    {
        azureDevOpsOrganization = dlgAzureDevOpsOrg.value();
        azureDevOpsProject = dlgAzureDevOpsProject.value();
        personalAccessToken = dlgPAT.value();
        deploymentId = dlgDeploymentId.value();

        return super();
    }

    public static void main(Args _args)
    {
        ALMDeploymentTrackingBatch batch = new ALMDeploymentTrackingBatch();

        if (batch.prompt())
        {
            batch.run();
        }
    }
}

/// <summary>
/// Environment-aware configuration manager for multi-tier deployments
/// </summary>
final class EnvironmentConfigurationManager
{
    private Map configurationCache;
    private EnvironmentType currentEnvironment;

    public void new()
    {
        configurationCache = new Map(Types::String, Types::Container);
        currentEnvironment = this.detectEnvironment();
    }

    /// <summary>
    /// Detects current environment based on AOS configuration
    /// </summary>
    private EnvironmentType detectEnvironment()
    {
        str environmentName = xGlobal::getEnvironmentName();
        CompanyInfo companyInfo = CompanyInfo::find();

        // Check for production indicators
        if (strContains(environmentName, 'PROD') || 
            strContains(companyInfo.Name, 'Production'))
        {
            return EnvironmentType::Production;
        }

        // Check for UAT indicators  
        if (strContains(environmentName, 'UAT') ||
            strContains(environmentName, 'TEST'))
        {
            return EnvironmentType::UserAcceptanceTesting;
        }

        return EnvironmentType::Development;
    }

    /// <summary>
    /// Retrieves environment-specific configuration value
    /// </summary>
    public str getConfigurationValue(str _configKey, str _defaultValue = '')
    {
        str cacheKey = strFmt('%1_%2', currentEnvironment, _configKey);

        if (configurationCache.exists(cacheKey))
        {
            return configurationCache.lookup(cacheKey);
        }

        SysConfiguration sysConfig;
        str configValue = _defaultValue;

        try
        {
            ttsbegin;

            select firstonly Value from sysConfig
                where sysConfig.ConfigurationKey == _configKey &&
                      sysConfig.Environment == int2Enum(EnvironmentType, currentEnvironment);

            if (sysConfig)
            {
                configValue = sysConfig.Value;
            }

            ttscommit;

            // Cache the result
            configurationCache.insert(cacheKey, configValue);
        }
        catch (Exception::Error)
        {
            warning(strFmt('Failed to retrieve configuration for key %1', _configKey));
        }

        return configValue;
    }

    /// <summary>
    /// Gets environment-specific service endpoint
    /// </summary>
    public str getServiceEndpoint(str _serviceName)
    {
        str endpointKey = strFmt('%1_ENDPOINT', _serviceName);
        str defaultEndpoint;

        // Set default endpoints based on environment
        switch (currentEnvironment)
        {
            case EnvironmentType::Development:
                defaultEndpoint = 'https://dev-api.contoso.com';
                break;

            case EnvironmentType::UserAcceptanceTesting:
                defaultEndpoint = 'https://uat-api.contoso.com';
                break;

            case EnvironmentType::Production:
                defaultEndpoint = 'https://api.contoso.com';
                break;
        }

        return this.getConfigurationValue(endpointKey, defaultEndpoint);
    }

    /// <summary>
    /// Static factory method for singleton access
    /// </summary>
    public static EnvironmentConfigurationManager instance()
    {
        return SysGlobalObjectCache::find(classStr(EnvironmentConfigurationManager),
                                        classStr(EnvironmentConfigurationManager));
    }
}

/// <summary>
/// Environment-aware service factory with DI container integration
/// </summary>
class ServiceFactory
{
    private SysContainerBuilder containerBuilder;
    private EnvironmentConfigurationManager configManager;

    public void new()
    {
        containerBuilder = new SysContainerBuilder();
        configManager = EnvironmentConfigurationManager::instance();
        this.registerServices();
    }

    /// <summary>
    /// Registers environment-specific service implementations
    /// </summary>
    private void registerServices()
    {
        EnvironmentType environment = configManager.getCurrentEnvironment();

        // Register payment service based on environment
        switch (environment)
        {
            case EnvironmentType::Development:
                containerBuilder.registerType(
                    classStr(IPaymentService),
                    classStr(MockPaymentService));
                break;

            case EnvironmentType::UserAcceptanceTesting:
                containerBuilder.registerType(
                    classStr(IPaymentService),
                    classStr(SandboxPaymentService));
                break;

            case EnvironmentType::Production:
                containerBuilder.registerType(
                    classStr(IPaymentService),
                    classStr(ProductionPaymentService));
                break;
        }

        // Register logging service with environment-specific configuration
        str logLevel = configManager.getConfigurationValue('LOG_LEVEL', 'Info');
        containerBuilder.registerInstance(
            classStr(ILoggingService),
            LoggingServiceFactory::createLogger(logLevel));

        // Register integration service with environment endpoints
        str integrationEndpoint = configManager.getServiceEndpoint('INTEGRATION');
        containerBuilder.registerFactory(
            classStr(IIntegrationService),
            () => new IntegrationService(integrationEndpoint));
    }

    /// <summary>
    /// Resolves service instance with environment-aware configuration
    /// </summary>
    public Object resolve(ClassId _serviceInterface)
    {
        try
        {
            Object serviceInstance = containerBuilder.resolve(_serviceInterface);

            // Apply environment-specific configuration if service supports it
            if (serviceInstance is IEnvironmentConfigurable)
            {
                IEnvironmentConfigurable configurableService = serviceInstance;
                configurableService.configureForEnvironment(configManager);
            }

            return serviceInstance;
        }
        catch (Exception::Error)
        {
            error(strFmt('Failed to resolve service %1: %2', 
                        className(class2Id(_serviceInterface)), 
                        Exception::getLastError()));
            throw Exception::Error;
        }
    }

    /// <summary>
    /// Creates environment-specific batch job configuration
    /// </summary>
    public BatchJobConfiguration createBatchConfiguration(str _jobName)
    {
        BatchJobConfiguration config = new BatchJobConfiguration();
        EnvironmentType environment = configManager.getCurrentEnvironment();

        // Set environment-specific batch parameters
        switch (environment)
        {
            case EnvironmentType::Development:
                config.parmMaxBatchTasks(1);
                config.parmRecurrenceData(SysRecurrence::defaultRecurrence());
                break;

            case EnvironmentType::UserAcceptanceTesting:
                config.parmMaxBatchTasks(2);
                config.parmRecurrenceData(SysRecurrence::hourly(2));
                break;

            case EnvironmentType::Production:
                int maxTasks = str2Int(configManager.getConfigurationValue(
                    strFmt('%1_MAX_TASKS', _jobName), '4'));
                config.parmMaxBatchTasks(maxTasks);

                str recurrencePattern = configManager.getConfigurationValue(
                    strFmt('%1_RECURRENCE', _jobName), 'DAILY');
                config.parmRecurrenceData(this.parseRecurrencePattern(recurrencePattern));
                break;
        }

        return config;
    }

    /// <summary>
    /// Validates service configuration across environments
    /// </summary>
    public boolean validateEnvironmentConfiguration()
    {
        boolean isValid = true;
        List<str> validationErrors = new List(Types::String);

        try
        {
            // Validate required configuration keys exist
            List<str> requiredKeys = this.getRequiredConfigurationKeys();
            ListEnumerator enumerator = requiredKeys.getEnumerator();

            while (enumerator.moveNext())
            {
                str configKey = enumerator.current();
                str configValue = configManager.getConfigurationValue(configKey);

                if (!configValue)
                {
                    validationErrors.addEnd(
                        strFmt('Missing configuration for key: %1', configKey));
                    isValid = false;
                }
            }

            // Validate service endpoints are accessible
            if (!this.validateServiceEndpoints())
            {
                validationErrors.addEnd('One or more service endpoints are not accessible');
                isValid = false;
            }

            if (!isValid)
            {
                this.logValidationErrors(validationErrors);
            }
        }
        catch (Exception::Error)
        {
            error('Environment validation failed with exception');
            isValid = false;
        }

        return isValid;
    }
