/// <summary>
/// Controller class for LangChain agent operations
/// Handles complex business logic that agents can invoke
/// </summary>
class AgentBusinessController
{
    /// <summary>
    /// Process customer order with intelligent routing
    /// </summary>
    [SysEntryPointAttribute(true)]
    public static container processCustomerOrder(str _salesId, str _agentContext)
    {
        container result = [false, ''];
        SalesTable salesTable;
        CustTable custTable;

        try
        {
            ttsbegin;

            // Retrieve order data
            salesTable = SalesTable::find(_salesId, true);
            if (!salesTable)
            {
                throw error(strFmt("Sales order %1 not found", _salesId));
            }

            custTable = CustTable::find(salesTable.CustAccount);

            // Agent-driven business logic
            boolean autoApprove = false;
            str processingNote = '';

            // Credit check logic for agent decision
            if (custTable.CreditMax > 0 && salesTable.SalesBalanceMST <= custTable.CreditMax)
            {
                autoApprove = true;
                processingNote = 'Auto-approved by agent - within credit limit';
            }
            else if (salesTable.SalesBalanceMST <= 1000.0) // Small orders
            {
                autoApprove = true;
                processingNote = 'Auto-approved by agent - small order amount';
            }
            else
            {
                processingNote = 'Flagged for manual review - exceeds approval thresholds';
            }

            // Update order status based on agent decision
            if (autoApprove)
            {
                salesTable.SalesStatus = SalesStatus::Backorder;

                // Create agent audit entry
                AgentBusinessController::logAgentAction(
                    _salesId, 
                    'ORDER_APPROVED', 
                    _agentContext, 
                    processingNote
                );
            }
            else
            {
                salesTable.SalesStatus = SalesStatus::OpenOrder;

                // Flag for human review
                AgentBusinessController::logAgentAction(
                    _salesId, 
                    'REVIEW_REQUIRED', 
                    _agentContext, 
                    processingNote
                );
            }

            salesTable.update();

            result = [true, processingNote];
            ttscommit;

            info(strFmt("Agent processed order %1: %2", _salesId, processingNote));
        }
        catch (Exception::Error)
        {
            ttsabort;
            error(strFmt("Agent processing failed for order %1", _salesId));
            result = [false, 'Processing failed'];
        }

        return result;
    }

    /// <summary>
    /// Log agent actions for audit and compliance
    /// </summary>
    private static void logAgentAction(str _salesId, str _action, str _context, str _notes)
    {
        // Custom audit table for agent operations
        // In production, this would be a proper audit framework
        info(strFmt("AGENT_LOG: Order=%1, Action=%2, Context=%3, Notes=%4", 
                   _salesId, _action, _context, _notes));
    }

    /// <summary>
    /// Retrieve order summary data for agent analysis
    /// </summary>
    [SysEntryPointAttribute(true)]
    public static container getOrderAnalysisData(str _dateRange)
    {
        container analysisData = [];
        Query query;
        QueryRun queryRun;
        QueryBuildDataSource qbds;
        SalesTable salesTable;

        try
        {
            query = new Query();
            qbds = query.addDataSource(tableNum(SalesTable));

            // Add date range filter based on agent parameters
            qbds.addRange(fieldNum(SalesTable, CreatedDateTime));

            queryRun = new QueryRun(query);

            while (queryRun.next())
            {
                salesTable = queryRun.get(tableNum(SalesTable));

                // Build analysis container for agent processing
                analysisData += [[
                    salesTable.SalesId,
                    salesTable.CustAccount,
