/// <summary>
/// Service for indexing X++ code artifacts for RAG pipeline
/// </summary>
class AICodeIndexerService
{
    private AIVectorStoreContract vectorStore;
    private str azureSearchEndpoint;
    private str openAIApiKey;

    public void new()
    {
        this.vectorStore = new AIVectorStoreContract();
        this.azureSearchEndpoint = SysParametersQuery::find().AIAzureSearchEndpoint;
        this.openAIApiKey = SysParametersQuery::find().AIOpenAIApiKey;
    }

    /// <summary>
    /// Index all X++ classes in specified model
    /// </summary>
    public boolean indexModel(str _modelName)
    {
        TreeNode rootNode;
        TreeNodeIterator iterator;
        TreeNode classNode;
        AICodeArtifactContract artifact;
        boolean success = true;

        try
        {
            rootNode = TreeNode::findNode('\\Classes');
            iterator = rootNode.AOTiterator();

            ttsbegin;

            while ((classNode = iterator.next()) != null)
            {
                // Filter by model
                if (classNode.AOTgetModel() != _modelName)
                    continue;

                artifact = this.extractClassArtifact(classNode);

                if (artifact && !this.indexArtifact(artifact))
                {
                    warning(strFmt('Failed to index class: %1', classNode.AOTname()));
                    success = false;
                }
            }

            ttscommit;

            info(strFmt('Successfully indexed model: %1', _modelName));
        }
        catch (Exception::Error)
        {
            error('Critical error during indexing process');
            success = false;
        }

        return success;
    }

    private AICodeArtifactContract extractClassArtifact(TreeNode _classNode)
    {
        AICodeArtifactContract artifact = new AICodeArtifactContract();
        TreeNodeIterator methodIterator;
        TreeNode methodNode;
        str classSource, methodSource;
        List businessContexts = new List(Types::String);

        try
        {
            artifact.parmArtifactType(AIArtifactType::XPPClass);
            artifact.parmName(_classNode.AOTname());
            artifact.parmModel(_classNode.AOTgetModel());
            artifact.parmLayer(_classNode.AOTgetCurrentLayer());

            // Extract class metadata
            classSource = _classNode.AOTgetSource();
            artifact.parmSourceCode(classSource);
            artifact.parmDocumentation(this.extractClassDocumentation(_classNode));

            // Identify business contexts from class attributes and inheritance
            if (this.isFinancialClass(_classNode.AOTname()))
                businessContexts.addEnd('Financial Management');
            if (this.isSupplyChainClass(_classNode.AOTname()))
                businessContexts.addEnd('Supply Chain');
            if (this.isBatchJobClass(_classNode))
                businessContexts.addEnd('Batch Processing');

            artifact.parmBusinessContexts(businessContexts);

            // Extract method signatures for semantic search
            methodIterator = _classNode.AOTiterator();
            List methodSignatures = new List(Types::String);

            while ((methodNode = methodIterator.next()) != null)
            {
                if (methodNode.AOTgetNodeType() == 'Method')
                {
                    methodSource = methodNode.AOTgetSource();
                    methodSignatures.addEnd(this.extractMethodSignature(methodSource));
                }
            }

            artifact.parmMethodSignatures(methodSignatures);
            artifact.parmVectorEmbedding(this.generateEmbedding(artifact.getSemanticText()));
        }
        catch (Exception::Error)
        {
            error(strFmt('Failed to extract artifact for class: %1', _classNode.AOTname()));
            artifact = null;
        }

        return artifact;
    }

    private boolean indexArtifact(AICodeArtifactContract _artifact)
    {
        AIAzureSearchClient searchClient = new AIAzureSearchClient(this.azureSearchEndpoint);
        boolean success;

        try
        {
            success = searchClient.indexDocument(_artifact.serialize());

            if (success)
            {
                // Store in local vector database for faster retrieval
                this.vectorStore.storeVector(
                    _artifact.parmName(),
                    _artifact.parmVectorEmbedding(),
                    _artifact.serialize()
                );
            }
        }
        catch (Exception::Error)
        {
            error(strFmt('Failed to index artifact: %1', _artifact.parmName()));
            success = false;
        }

        return success;
    }

    private boolean isFinancialClass(str _className)
    {
        return (strStartsWith(_className, 'Ledger') ||
                strStartsWith(_className, 'Cust') ||
                strStartsWith(_className, 'Vend') ||
                strContains(_className, 'Payment') ||
                strContains(_className, 'Invoice'));
    }

    private str generateEmbedding(str _text)
    {
        AIOpenAIClient openAIClient = new AIOpenAIClient(this.openAIApiKey);
        return openAIClient.generateEmbedding(_text, 'text-embedding-ada-002');
    }
}

/// <summary>
/// RAG-powered query engine for X++ code assistance
/// </summary>
class AICodeAssistantEngine
{
    private AIVectorStoreContract vectorStore;
    private AIOpenAIClient openAIClient;
    private int maxContextTokens;

    public void new()
    {
        this.vectorStore = new AIVectorStoreContract();
        this.openAIClient = new AIOpenAIClient(SysParametersQuery::find().AIOpenAIApiKey);
        this.maxContextTokens = 4000; // Leave room for response
    }

    /// <summary>
    /// Process natural language query and return code-aware response
    /// </summary>
    public AICodeAssistantResponse queryCode(str _query, str _currentContext = '')
    {
        AICodeAssistantResponse response = new AICodeAssistantResponse();
        List relevantArtifacts;
        str enhancedPrompt;
        str aiResponse;

        try
        {
            // Step 1: Retrieve relevant code artifacts
            relevantArtifacts = this.retrieveRelevantCode(_query, _currentContext);

            if (relevantArtifacts.elements() == 0)
            {
                response.parmSuccess(false);
                response.parmMessage('No relevant code artifacts found for your query.');
                return response;
            }

            // Step 2: Build context-aware prompt
            enhancedPrompt = this.buildEnhancedPrompt(_query, relevantArtifacts, _currentContext);

            // Step 3: Generate AI response
            aiResponse = this.openAIClient.generateCompletion(
                enhancedPrompt,
                'gpt-4',
                1500, // max tokens for response
                0.1   // low temperature for code-focused responses
            );

            // Step 4: Post-process response for D365 context
            response.parmSuccess(true);
            response.parmMessage(this.postProcessResponse(aiResponse));
            response.parmRelevantArtifacts(relevantArtifacts);
            response.parmConfidenceScore(this.calculateConfidenceScore(relevantArtifacts));

            info(strFmt('AI Code Assistant: Generated response with %1 relevant artifacts', relevantArtifacts.elements()));
        }
        catch (Exception::Error)
        {
            response.parmSuccess(false);
            response.parmMessage('An error occurred while processing your query. Please try again.');
            error('Failed to process AI code query');
        }

        return response;
    }

    private List retrieveRelevantCode(str _query, str _currentContext)
    {
        List relevantArtifacts = new List(Types::Class);
        str queryEmbedding;
        List searchResults;
        ListIterator iterator;
        AICodeArtifactContract artifact;
        real similarityThreshold = 0.75;

        try
        {
            // Generate embedding for the query
            queryEmbedding = this.openAIClient.generateEmbedding(_query, 'text-embedding-ada-002');

            // Hybrid search: vector similarity + keyword matching
            searchResults = this.vectorStore.hybridSearch(
                queryEmbedding,
                _query,
                10, // top 10 results
                similarityThreshold
            );

            // If we have current context (e.g., current class being worked on),
            // boost relevance of related artifacts
            if (_currentContext)
            {
                searchResults = this.boostContextualRelevance(searchResults, _currentContext);
            }

            // Convert search results to artifact contracts
            iterator = searchResults.listIterator();
            while (iterator.more())
            {
                AISearchResult result = iterator.value();
                artifact = AICodeArtifactContract::deserialize(result.parmDocument());

                if (artifact && this.isTokenLimitRespected(relevantArtifacts, artifact))
                {
                    relevantArtifacts.addEnd(artifact);
                }

                iterator.next();
            }
        }
        catch (Exception::Error)
        {
            warning('Failed to retrieve relevant code artifacts');
        }

        return relevantArtifacts;
    }

    private str buildEnhancedPrompt(str _query, List _relevantArtifacts, str _currentContext)
    {
        str prompt;
        ListIterator iterator;
        AICodeArtifactContract artifact;
        str contextSection = '';

        prompt = 'You are an expert D365 Finance & Operations (F&O) developer assistant. ';
        prompt += 'Provide accurate, production-ready guidance based on the following X++ code context.\n\n';

        prompt += 'QUERY: ' + _query + '\n\n';

        if (_currentContext)
        {
            prompt += 'CURRENT CONTEXT: ' + _currentContext + '\n\n';
        }

        prompt += 'RELEVANT CODE ARTIFACTS:\n';

        iterator = _relevantArtifacts.listIterator();
        int artifactCount = 1;

        while (iterator.more())
        {
            artifact = iterator.value();

            prompt += strFmt('--- ARTIFACT %1: %2 ---\n', artifactCount, artifact.parmName());
            prompt += strFmt('Model: %1, Layer: %2\n', artifact.parmModel(), artifact.parmLayer());
            prompt += strFmt('Type: %1\n', enum2Str(artifact.parmArtifactType()));

            if (artifact.parmDocumentation())
            {
                prompt += 'Documentation: ' + artifact.parmDocumentation() + '\n';
            }

            // Include relevant code snippets (truncated for token limits)
            prompt += this.truncateCodeForContext(artifact.parmSourceCode(), 500);
            prompt += '\n\n';

            iterator.next();
            artifactCount++;
        }

        prompt += 'INSTRUCTIONS:\n';
        prompt += '- Provide specific, actionable guidance for D365 F&O development\n';
        prompt += '- Reference appropriate AOT objects, classes, and frameworks\n';
        prompt += '- Include code examples using proper X++ syntax\n';
        prompt += '- Consider security, performance, and best practices\n';
        prompt += '- Mention any relevant Chain of Command or extension patterns\n';
        prompt += '- If the query involves customization, suggest the least invasive approach\n\n';

        return prompt;
    }

    private real calculateConfidenceScore(List _relevantArtifacts)
    {
        real confidence = 0.0;

        if (_relevantArtifacts.elements() >= 3)
            confidence += 0.4;
        else if (_relevantArtifacts.elements() >= 1)
            confidence += 0.2;

        // Additional confidence factors could include:
        // - Semantic similarity scores
        // - Artifact freshness
        // - Code complexity matches

        return confidence;
    }
}

