    }

    [DataMemberAttribute('CustomerName')]
    public CustName parmCustomerName(CustName _customerName = customerName)
    {
        customerName = _customerName;
        return customerName;
    }

    [DataMemberAttribute('SalesStatus')]
    public SalesStatus parmSalesStatus(SalesStatus _salesStatus = salesStatus)
    {
        salesStatus = _salesStatus;
        return salesStatus;
    }

    [DataMemberAttribute('TotalAmount')]
    public AmountCur parmTotalAmount(AmountCur _totalAmount = totalAmount)
    {
        totalAmount = _totalAmount;
        return totalAmount;
    }

    [DataMemberAttribute('OrderDate')]
    public TransDate parmOrderDate(TransDate _orderDate = orderDate)
    {
        orderDate = _orderDate;
        return orderDate;
    }

    [DataMemberAttribute('RiskLevel')]
    public str parmRiskLevel(str _riskLevel = riskLevel)
    {
        riskLevel = _riskLevel;
        return riskLevel;
    }

    public void mapEntityToDataSource(DataEntityRuntimeContext _entityCtx)
    {
        SalesTable salesTable;
        CustTable custTable;

        select firstonly salesTable
            join custTable
            where salesTable.CustAccount == custTable.AccountNum
               && salesTable.SalesId == this.parmSalesId();

        if (salesTable.RecId)
        {
            this.parmCustAccount(salesTable.CustAccount);
            this.parmCustomerName(custTable.Name);
            this.parmSalesStatus(salesTable.SalesStatus);
            this.parmTotalAmount(SalesTable::find(salesTable.SalesId).totalAmount());
            this.parmOrderDate(salesTable.CreatedDateTime);

            // Calculate risk level based on business logic
            this.parmRiskLevel(this.calculateRiskLevel(salesTable));
        }
    }

    private str calculateRiskLevel(SalesTable _salesTable)
    {
        AmountCur totalAmount = SalesTable::find(_salesTable.SalesId).totalAmount();
        CustTable custTable = CustTable::find(_salesTable.CustAccount);

        if (totalAmount > 100000 || custTable.CreditRating == CustCreditRating::Poor)
            return 'High';
        else if (totalAmount > 50000 || custTable.CreditRating == CustCreditRating::Average)
            return 'Medium';
        else
            return 'Low';
    }
}

[SysRestServiceAttribute('CopilotSalesActions', 'Copilot Sales Operations')]
