            if (!salesTable.RecId)
            {
                throw error(strFmt("Sales order %1 not found", _salesId));
            }

            if (salesTable.SalesStatus != SalesStatus::Backorder)
            {
                throw error(strFmt("Sales order %1 cannot be confirmed. Current status: %2", 
                    _salesId, enum2Str(salesTable.SalesStatus)));
            }

            // Perform confirmation
            salesFormLetter = SalesFormLetter::construct(DocumentStatus::Confirmation);
            salesFormLetter.update(salesTable, DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()));

            // Log the action with reason
            this.logCopilotAction(_salesId, 'Confirmation', _reason);

            ttscommit;

            result = strFmt("Sales order %1 confirmed successfully", _salesId);
            info(result);
        }
        catch (Exception::Error)
        {
            ttsabort;
            result = strFmt("Error confirming sales order %1: %2", _salesId, infolog.text());
            error(result);
        }

        return result;
    }

    [SysRestServiceOperationAttribute,
     SysEntryPointAttribute(true),
     SysODataActionAttribute('CreateSalesQuote', true)]
    public str createSalesQuote(str _custAccount, str _requestedBy, str _description)
    {
        SalesQuotationTable salesQuotationTable;
        NumberSeq numberSeq;
        CustTable custTable;
        str quotationId;
        str result;

        try
        {
            ttsbegin;

            // Validate customer
            custTable = CustTable::find(_custAccount);
            if (!custTable.RecId)
            {
                throw error(strFmt("Customer %1 not found", _custAccount));
            }

            if (custTable.Blocked != CustVendorBlocked::No)
            {
                throw error(strFmt("Customer %1 is blocked", _custAccount));
            }

            // Generate quotation number
            numberSeq = NumberSeq::newGetNum(SalesParameters::numRefSalesQuotationId());
            quotationId = numberSeq.num();

            // Create quotation header
            salesQuotationTable.clear();
            salesQuotationTable.QuotationId = quotationId;
            salesQuotationTable.CustAccount = _custAccount;
            salesQuotationTable.QuotationType = QuotationType::Sales;
            salesQuotationTable.QuotationStatus = SalesQuotationStatus::Created;
            salesQuotationTable.ContactPersonId = _requestedBy;
            salesQuotationTable.Txt = _description;
            salesQuotationTable.QuotationDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
            salesQuotationTable.ExpiryDate = salesQuotationTable.QuotationDate + 30; // 30 days validity

            // Set default values from customer
            salesQuotationTable.initFromCustTable();
            salesQuotationTable.insert();

            // Log the action
            this.logCopilotAction(quotationId, 'Creation', strFmt('Quote created for %1 by %2', _custAccount, _requestedBy));

            ttscommit;

            result = strFmt("Sales quotation %1 created successfully for customer %2", quotationId, _custAccount);
