        }
        catch (Exception::Error)
        {
            ttsabort;
            result = strFmt("Error creating sales quotation: %1", infolog.text());
            error(result);
        }

        return result;
    }

    [SysRestServiceOperationAttribute,
     SysEntryPointAttribute(true)]
    public container getSalesAnalytics(str _dateFrom, str _dateTo, str _custGroup = '')
    {
        container result;
        SalesLine salesLine;
        SalesTable salesTable;
        CustTable custTable;
        TransDate dateFrom, dateTo;
        AmountCur totalAmount;
        int orderCount;
        Query query;
        QueryBuildDataSource qbdsTable, qbdsLine, qbdsCust;
        QueryRun queryRun;

        try
        {
            dateFrom = str2Date(_dateFrom, 321);
            dateTo = str2Date(_dateTo, 321);

            if (!dateFrom || !dateTo)
            {
                throw error("Invalid date format. Use YYYY-MM-DD format");
            }

            // Build dynamic query
            query = new Query();
            qbdsTable = query.addDataSource(tableNum(SalesTable));
            qbdsLine = qbdsTable.addDataSource(tableNum(SalesLine));
            qbdsCust = qbdsTable.addDataSource(tableNum(CustTable));

            qbdsLine.addLink(fieldNum(SalesTable, SalesId), fieldNum(SalesLine, SalesId));
            qbdsCust.addLink(fieldNum(SalesTable, CustAccount), fieldNum(CustTable, AccountNum));

            qbdsTable.addRange(fieldNum(SalesTable, CreatedDateTime)).value(queryRange(dateFrom, dateTo));
            qbdsTable.addRange(fieldNum(SalesTable, SalesStatus)).value(queryNotValue(SalesStatus::Canceled));

            if (_custGroup)
            {
                qbdsCust.addRange(fieldNum(CustTable, CustGroup)).value(_custGroup);
            }

            queryRun = new QueryRun(query);

            while (queryRun.next())
            {
                salesTable = queryRun.get(tableNum(SalesTable));
                salesLine = queryRun.get(tableNum(SalesLine));

                totalAmount += salesLine.LineAmountMST;
                orderCount++;
            }

            result = [totalAmount, orderCount, totalAmount / max(orderCount, 1)];
        }
        catch (Exception::Error)
        {
            error(strFmt("Error retrieving sales analytics: %1", infolog.text()));
            result = [0.0, 0, 0.0];
        }

        return result;
    }

    private void logCopilotAction(str _referenceId, str _actionType, str _description)
    {
        // Custom logging for audit trail
        CopilotActionLog actionLog;

        actionLog.clear();
        actionLog.ReferenceId = _referenceId;
        actionLog.ActionType = _actionType;
        actionLog.Description = _description;
        actionLog.UserId = curUserId();
        actionLog.ActionDateTime = DateTimeUtil::utcNow();
        actionLog.CompanyId = curExt();
        actionLog.insert();
    }
}

/// <summary>
/// Base service class for Azure OpenAI API integration
/// Handles authentication, HTTP communication, and error management
/// </summary>
public class AzureOpenAIServiceBase
{
    protected str apiEndpoint;
    protected str apiKey;
    protected int timeoutSeconds;

    public void new(str _endpoint, str _apiKey, int _timeout = 30)
    {
        apiEndpoint = _endpoint;
        apiKey = _apiKey;
        timeoutSeconds = _timeout;
    }

    /// <summary>
    /// Execute HTTP request to OpenAI API with retry logic
    /// </summary>
    protected str executeHttpRequest(str _httpMethod, str _endpoint, str _jsonPayload = '')
    {
        System.Net.HttpWebRequest request;
        System.Net.HttpWebResponse response;
        System.IO.Stream requestStream;
        System.IO.StreamReader responseReader;
        str responseText = '';
        str fullUrl = apiEndpoint + _endpoint;
        int retryCount = 0;
        int maxRetries = 3;

        do
        {
            try
            {
                request = System.Net.WebRequest::Create(fullUrl);
                request.set_Method(_httpMethod);
                request.set_ContentType('application/json');
                request.set_Timeout(timeoutSeconds * 1000);

                // Add authentication header
                request.get_Headers().Add('Authorization', strFmt('Bearer %1', apiKey));
                request.get_Headers().Add('api-key', apiKey); // Azure OpenAI specific

                // Add request body for POST/PUT
                if (_httpMethod == 'POST' || _httpMethod == 'PUT')
                {
                    if (_jsonPayload)
                    {
                        System.Text.UTF8Encoding encoding = new System.Text.UTF8Encoding();
                        System.Byte[] bytes = encoding.GetBytes(_jsonPayload);
                        request.set_ContentLength(bytes.get_Length());

                        requestStream = request.GetRequestStream();
                        requestStream.Write(bytes, 0, bytes.get_Length());
                        requestStream.Close();
                    }
                }

                response = request.GetResponse();
                responseReader = new System.IO.StreamReader(response.GetResponseStream());
                responseText = responseReader.ReadToEnd();
                responseReader.Close();
                response.Close();

                break; // Success, exit retry loop
            }
            catch (Exception::CLRError)
            {
                System.Exception ex = CLRInterop::getLastException();

                if (ex is System.Net.WebException)
                {
                    System.Net.WebException webEx = ex;
                    System.Net.HttpWebResponse errorResponse = webEx.get_Response();

                    if (errorResponse)
                    {
                        int statusCode = errorResponse.get_StatusCode();

                        // Handle rate limiting (429) and server errors (5xx)
                        if (statusCode == 429 || (statusCode >= 500 && statusCode < 600))
                        {
                            retryCount++;
                            if (retryCount <= maxRetries)
                            {
                                // Exponential backoff
                                sleep(retryCount * retryCount * 1000);
                                continue;
                            }
                        }
                    }
                }

                error(strFmt('Azure OpenAI API error: %1', ex.get_Message()));
                throw ex;
            }
        }
        while (retryCount <= maxRetries);

        return responseText;
    }

    /// <summary>
    /// Parse JSON response and handle common error patterns
    /// </summary>
    protected container parseJsonResponse(str _jsonResponse)
    {
        System.Json.JsonObject jsonObj;
        container result;

        try
        {
            jsonObj = System.Json.JsonObject::Parse(_jsonResponse);

            // Check for OpenAI error structure
            if (jsonObj.ContainsKey('error'))
            {
                System.Json.JsonObject errorObj = jsonObj.GetValue('error');
                str errorMessage = errorObj.GetValue('message');
                str errorType = errorObj.GetValue('type');

                error(strFmt('OpenAI API Error [%1]: %2', errorType, errorMessage));
                return conNull();
            }

            result = [jsonObj];
        }
        catch (Exception::CLRError)
        {
            System.Exception ex = CLRInterop::getLastException();
            error(strFmt('JSON parsing error: %1', ex.get_Message()));
            return conNull();
        }

        return result;
    }
}

/// <summary>
/// GPT Chat Completion service for D365 business automation
/// Supports context injection from D365 data and structured responses
/// </summary>
public class AzureOpenAIGPTService extends AzureOpenAIServiceBase
{
    private str modelName;
    private real temperature;
    private int maxTokens;

    public void new(str _endpoint, str _apiKey, str _modelName = 'gpt-4', real _temperature = 0.7, int _maxTokens = 1000)
    {
        super(_endpoint, _apiKey);
        modelName = _modelName;
        temperature = _temperature;
        maxTokens = _maxTokens;
    }

    /// <summary>
    /// Generate chat completion with system and user context
    /// </summary>
    public str generateChatCompletion(str _systemPrompt, str _userPrompt, container _businessContext = conNull())
    {
        System.Json.JsonObject requestObj = new System.Json.JsonObject();
        System.Json.JsonArray messagesArray = new System.Json.JsonArray();
        System.Json.JsonObject systemMessage = new System.Json.JsonObject();
        System.Json.JsonObject userMessage = new System.Json.JsonObject();
        str enhancedUserPrompt = _userPrompt;
        str responseText, content;
        container parsedResponse;

        // Enhance user prompt with D365 business context
        if (_businessContext != conNull())
        {
            enhancedUserPrompt = this.injectBusinessContext(_userPrompt, _businessContext);
        }

        // Build system message
        systemMessage.Add('role', 'system');
        systemMessage.Add('content', _systemPrompt);
        messagesArray.Add(systemMessage);

        // Build user message
        userMessage.Add('role', 'user');
        userMessage.Add('content', enhancedUserPrompt);
        messagesArray.Add(userMessage);

        // Build request payload
        requestObj.Add('model', modelName);
        requestObj.Add('messages', messagesArray);
        requestObj.Add('temperature', temperature);
        requestObj.Add('max_tokens', maxTokens);

        str jsonPayload = requestObj.ToString();

        // Execute API call
        responseText = this.executeHttpRequest('POST', '/openai/deployments/' + modelName + '/chat/completions?api-version=2023-12-01-preview', jsonPayload);

        parsedResponse = this.parseJsonResponse(responseText);

        if (conLen(parsedResponse) > 0)
        {
            System.Json.JsonObject responseObj = conPeek(parsedResponse, 1);
            System.Json.JsonArray choices = responseObj.GetValue('choices');

            if (choices.get_Count() > 0)
            {
                System.Json.JsonObject firstChoice = choices.get_Item(0);
                System.Json.JsonObject message = firstChoice.GetValue('message');
                content = message.GetValue('content');

                // Log usage for cost tracking
                this.logTokenUsage(responseObj);

                return content;
            }
        }

        return '';
    }

    /// <summary>
    /// Inject D365 business context into user prompt
    /// </summary>
    private str injectBusinessContext(str _basePrompt, container _context)
    {
        str contextText = '';
        int i;

        // Extract context information
        // Expected format: [['Customer', custInfo], ['Invoice', invoiceInfo], ...]
        for (i = 1; i <= conLen(_context); i++)
        {
            container contextPair = conPeek(_context, i);
            str contextType = conPeek(contextPair, 1);
            str contextData = conPeek(contextPair, 2);

            contextText += strFmt('\n%1 Context:\n%2\n', contextType, contextData);
        }

        return strFmt('%1\n\nBusiness Context:%2', _basePrompt, contextText);
    }

    /// <summary>
    /// Log token usage for cost tracking and monitoring
    /// </summary>
    private void logTokenUsage(System.Json.JsonObject _responseObj)
    {
        System.Json.JsonObject usage;
        int promptTokens, completionTokens, totalTokens;

        if (_responseObj.ContainsKey('usage'))
        {
            usage = _responseObj.GetValue('usage');
            promptTokens = usage.GetValue('prompt_tokens');
            completionTokens = usage.GetValue('completion_tokens');
            totalTokens = usage.GetValue('total_tokens');

            info(strFmt('OpenAI Usage - Prompt: %1, Completion: %2, Total: %3 tokens', 
                       promptTokens, completionTokens, totalTokens));
        }
    }

    /// <summary>
    /// Analyze customer inquiry and route to appropriate department
    /// </summary>
    public str analyzeCustomerInquiry(str _customerMessage, CustAccount _custAccount)
    {
        CustTable custTable = CustTable::find(_custAccount);
        str systemPrompt = 'You are a D365 F&O customer service routing assistant. Analyze customer inquiries and categorize them into: BILLING, SHIPPING, RETURNS, TECHNICAL, or GENERAL. Provide routing recommendation with confidence level.';

        container businessContext = [
            ['Customer', strFmt('Account: %1, Name: %2, Group: %3, Currency: %4', 
                               custTable.AccountNum, custTable.name(), custTable.CustGroup, custTable.Currency)]
        ];

        str analysisPrompt = strFmt('Analyze this customer message and provide routing recommendation:\n"%1"', _customerMessage);

        return this.generateChatCompletion(systemPrompt, analysisPrompt, businessContext);
    }
}

/// <summary>
/// Batch job for bulk processing with Azure OpenAI
/// Handles rate limiting, error recovery, and progress tracking
/// </summary>
public class AzureOpenAIBulkProcessBatch extends RunBaseBatch
{
    private AzureOpenAIGPTService aiService;
    private RecId tableName;
    private FieldId textFieldId;
    private FieldId resultFieldId;
    private str processingType;
    private int batchSize;
    private int processedCount;
    private int errorCount;

    #define.CurrentVersion(1)
    #localmacro.CurrentList
        tableName,
        textFieldId,
        resultFieldId,
        processingType,
        batchSize
    #endmacro

    public container pack()
    {
        return [#CurrentVersion, #CurrentList];
    }

    public boolean unpack(container _packedClass)
    {
        Version version = RunBase::getVersion(_packedClass);

        switch (version)
        {
            case #CurrentVersion:
                [version, #CurrentList] = _packedClass;
                break;
            default:
                return false;
        }

        return true;
    }

    public void run()
    {
        Common record;
        QueryRun queryRun;
        Query query;
        QueryBuildDataSource qbds;
        DictTable dictTable;
        DictField textField, resultField;
        str textContent, aiResult;
        int currentBatch = 0;

        if (!this.validate())
            return;

        try
        {
            // Initialize AI service
            aiService = new AzureOpenAIGPTService(
                this.getParameterValue('OpenAIEndpoint'),
                this.getParameterValue('OpenAIApiKey')
            );

            // Build query for records to process
            query = new Query();
            dictTable = new DictTable(tableName);
            qbds = query.addDataSource(tableName);

            // Filter for unprocessed records
            qbds.addRange(resultFieldId).value(queryValue(''));

            queryRun = new QueryRun(query);

            ttsbegin;

            while (queryRun.next())
            {
                record = queryRun.get(tableName);
                textField = new DictField(tableName, textFieldId);
                resultField = new DictField(tableName, resultFieldId);

                textContent = textField.getValue(record);

                if (textContent)
                {
                    try
                    {
                        // Process with AI based on type
                        switch (processingType)
                        {
                            case 'SENTIMENT_ANALYSIS':
                                aiResult = this.analyzeSentiment(textContent);
                                break;
                            case 'TEXT_CLASSIFICATION':
                                aiResult = this.classifyText(textContent);
                                break;
                            case 'CONTENT_SUMMARY':
                                aiResult = this.summarizeContent(textContent);
                                break;
                            default:
                                aiResult = 'Unknown processing type';
                        }

                        // Update record with result
                        resultField.setValue(record, aiResult);
                        record.update();

                        processedCount++;
                    }
                    catch (Exception::Error)
                    {
                        errorCount++;
                        warning(strFmt('Error processing record %1: %2', record.RecId, infolog.text()));

                        // Mark as error for retry
                        resultField.setValue(record, 'ERROR_RETRY');
                        record.update();
                    }
                }

                currentBatch++;

                // Commit in batches and add delay for rate limiting
                if (currentBatch >= batchSize)
                {
                    ttscommit;

                    // Rate limiting delay (Azure OpenAI has limits)
                    sleep(2000); // 2 second delay

                    ttsbegin;
                    currentBatch = 0;

                    // Update progress
                    this.updateProgress();
                }
            }

            ttscommit;

            info(strFmt('Bulk AI processing completed. Processed: %1, Errors: %2', processedCount, errorCount));
        }
        catch (Exception::Error)
        {
            ttsabort;
            error('Bulk AI processing failed: ' + infolog.text());
        }
    }

    private str analyzeSentiment(str _text)
    {
        str systemPrompt = 'You are a sentiment analysis expert. Analyze the given text and return ONLY one word: POSITIVE, NEGATIVE, or NEUTRAL.';
        return aiService.generateChatCompletion(systemPrompt, _text);
    }

    private str classifyText(str _text)
    {
        str systemPrompt = 'You are a document classifier. Classify the given text into one of these categories: COMPLAINT, INQUIRY, COMPLIMENT, REQUEST, OTHER. Return ONLY the category.';
        return aiService.generateChatCompletion(systemPrompt, _text);
    }

    private str summarizeContent(str _text)
    {
        str systemPrompt = 'You are a content summarizer. Provide a concise 2-sentence summary of the given text.';
        return aiService.generateChatCompletion(systemPrompt, _text);
    }

    private boolean validate()
    {
        if (!tableName)
        {
            error('Table name is required');
            return false;
        }

        if (!textFieldId || !resultFieldId)
        {
            error('Text and result fields are required');
            return false;
        }

        return true;
    }

    private str getParameterValue(str _paramName)
    {
        // In production, retrieve from Parameters table or Azure Key Vault
        // This is a simplified example
        switch (_paramName)
        {
            case 'OpenAIEndpoint':
                return 'https://your-resource.openai.azure.com';
            case 'OpenAIApiKey':
                return 'your-api-key'; // Use secure storage in production
        }
        return '';
    }

    private void updateProgress()
    {
        // Update batch job progress for monitoring
        BatchJob::updateProgress(processedCount, processedCount + errorCount);
    }

    public static void main(Args _args)
    {
        AzureOpenAIBulkProcessBatch batch = new AzureOpenAIBulkProcessBatch();

        if (batch.prompt())
        {
            batch.runOperationNow();
        }
    }
}

public class VendorAIAnalysisService extends SysOperationServiceBase
{
    public str analyzeVendorPerformance(VendAccount _vendAccount, TransDate _fromDate, TransDate _toDate)
    {
        VendTable vendTable;
        PurchTable purchTable;
        VendInvoiceJour vendInvoiceJour;
        str contextPrompt, aiResponse;
        container performanceMetrics;

        ttsbegin;
        try
        {
            // Build ERP context for AI prompt
            select firstonly vendTable
                where vendTable.AccountNum == _vendAccount;

            if (!vendTable.RecId)
            {
                throw error(strFmt("Vendor %1 not found", _vendAccount));
            }

            // Gather performance metrics with business context
            performanceMetrics = this.buildPerformanceContext(_vendAccount, _fromDate, _toDate);

            // Craft business-aware prompt
            contextPrompt = strFmt(
                "Analyze vendor performance for %1 (%2) from %3 to %4. "
                + "Business Context: Legal Entity: %5, Vendor Group: %6, Payment Terms: %7. "
                + "Performance Data: %8. "
                + "Provide insights on: 1) Delivery reliability 2) Quality trends 3) Cost optimization opportunities 4) Risk factors. "
                + "Format response as actionable business recommendations with quantified impact where possible.",
                vendTable.AccountNum,
                vendTable.Name,
                date2Str(_fromDate, 321, DateDay::Digits2, DateSeparator::Slash, DateMonth::Digits2, DateYear::Digits4),
                date2Str(_toDate, 321, DateDay::Digits2, DateSeparator::Slash, DateMonth::Digits2, DateYear::Digits4),
                curext(),
                vendTable.VendGroup,
                vendTable.PaymTermId,
                con2Str(performanceMetrics, ';')
            );

            // Call AI service with structured prompt
            aiResponse = SysAIService::processPrompt(contextPrompt, AIModelType::BusinessAnalysis);

            // Log AI interaction for audit trail
            this.logAIInteraction(_vendAccount, contextPrompt, aiResponse);

            ttscommit;

            info(strFmt("AI analysis completed for vendor %1", _vendAccount));
            return aiResponse;
        }
        catch (Exception::Error)
        {
            ttsabort;
            error("Failed to generate vendor AI analysis");
            return "";
        }
    }

    private container buildPerformanceContext(VendAccount _vendAccount, TransDate _fromDate, TransDate _toDate)
    {
        container metrics = conNull();
        PurchLine purchLine;
        VendInvoiceJour vendInvoiceJour;
        InventTrans inventTrans;
        real avgLeadTime, onTimeDeliveryRate, qualityScore;
        int totalOrders, onTimeOrders;

        // Calculate delivery performance
        while select count(RecId) from purchLine
            join vendInvoiceJour
            where vendInvoiceJour.PurchId == purchLine.PurchId
                && vendInvoiceJour.InvoiceAccount == _vendAccount
                && vendInvoiceJour.InvoiceDate >= _fromDate
                && vendInvoiceJour.InvoiceDate <= _toDate
        {
            totalOrders++;
            if (purchLine.DeliveryDate <= purchLine.RequestedReceiptDate)
            {
                onTimeOrders++;
            }
        }

        onTimeDeliveryRate = totalOrders > 0 ? (onTimeOrders * 100.0 / totalOrders) : 0.0;

        metrics = conIns(metrics, 1, strFmt("Total Orders: %1", totalOrders));
        metrics = conIns(metrics, 2, strFmt("On-Time Delivery Rate: %1%", num2Str(onTimeDeliveryRate, 2, 2, 1, 1)));
        metrics = conIns(metrics, 3, strFmt("Vendor Group Classification: %1", this.getVendorGroupDescription(_vendAccount)));

        return metrics;
    }
}

public class PurchReqAIApprovalService
{
    public PurchReqApprovalDecision generateApprovalRecommendation(PurchReqId _purchReqId)
    {
        PurchReqTable purchReqTable;
        PurchReqLine purchReqLine;
        HcmWorker requester;
        DirPartyTable requesterParty;
        str approvalPrompt, aiRecommendation;
        PurchReqApprovalDecision decision;

        select firstonly purchReqTable
            where purchReqTable.PurchReqId == _purchReqId;

        if (!purchReqTable.RecId)
        {
            throw error(strFmt("Purchase requisition %1 not found", _purchReqId));
        }

        // Get requester context
        select firstonly requester
            join requesterParty
            where requester.RecId == purchReqTable.Requester
                && requesterParty.RecId == requester.Person;

        // Build comprehensive business context prompt
        approvalPrompt = this.buildApprovalContextPrompt(
            purchReqTable,
            requester,
            requesterParty
        );

        try
        {
            // Get AI recommendation with business rule constraints
            aiRecommendation = SysAIService::processPrompt(
                approvalPrompt,
                AIModelType::BusinessDecisionSupport
            );

            // Parse AI response into structured decision
            decision = this.parseAIApprovalDecision(aiRecommendation, purchReqTable);

            // Validate decision against hard business rules
            decision = this.validateAgainstBusinessRules(decision, purchReqTable);

            // Create audit trail for AI-assisted decision
            this.createApprovalAuditTrail(_purchReqId, approvalPrompt, aiRecommendation, decision);

            return decision;
        }
        catch (Exception::Error)
        {
            // Fallback to standard approval workflow
            warning("AI approval analysis failed, reverting to standard workflow");
            return this.getStandardApprovalDecision(purchReqTable);
        }
    }

    private str buildApprovalContextPrompt(PurchReqTable _purchReqTable, HcmWorker _requester, DirPartyTable _requesterParty)
    {
        PurchReqLine purchReqLine;
        str lineItemsContext = "";
        real totalAmount = 0.0;
        int lineCount = 0;

        // Aggregate line item context
        while select purchReqLine
            where purchReqLine.PurchReqId == _purchReqTable.PurchReqId
        {
            lineCount++;
            totalAmount += purchReqLine.LineAmount;
            lineItemsContext += strFmt(
                "Item: %1, Category: %2, Quantity: %3, Unit Price: %4, Vendor: %5; ",
                purchReqLine.ItemId,
                purchReqLine.ProcurementCategory,
                num2Str(purchReqLine.PurchQty, 0, 2, 1, 1),
                num2Str(purchReqLine.PurchPrice, 0, 2, 1, 1),
                purchReqLine.VendAccount
            );
        }

        return strFmt(
            "Evaluate purchase requisition for approval. "
            + "Requisition Details: ID=%1, Purpose=%2, Total Amount=%3 %4, Line Items=%5. "
            + "Requester Profile: %6 (%7), Department=%8, Position=%9. "
            + "Business Context: Legal Entity=%10, Site=%11, Request Date=%12. "
            + "Line Items: %13 "
            + "Approval Criteria: Consider budget compliance, vendor relationships, procurement policies, spend patterns, and business justification. "
            + "Provide recommendation (APPROVE/REJECT/CONDITIONAL) with specific reasoning and risk assessment. "
            + "If conditional approval, specify required conditions.",
            _purchReqTable.PurchReqId,
            _purchReqTable.PurchReqName,
            num2Str(totalAmount, 0, 2, 1, 1),
            _purchReqTable.CurrencyCode,
            lineCount,
            _requesterParty.Name,
            _requester.PersonnelNumber,
            this.getWorkerDepartment(_requester.RecId),
            this.getWorkerPosition(_requester.RecId),
            _purchReqTable.dataAreaId,
            this.getDefaultInventSite(_purchReqTable.Requester),
            date2Str(_purchReqTable.RequestDate, 321, DateDay::Digits2, DateSeparator::Slash, DateMonth::Digits2, DateYear::Digits4),
            lineItemsContext
        );
    }
}

/// <summary>
/// MCP-optimized data entity for customer insights queries
/// Implements caching and security for Teams bot integration
/// </summary>
[DataEntityViewAttribute('Customer Insights for MCP'),
 DataEntityPublicAttribute(true),
 DataEntityCacheHintAttribute(ViewCacheHint::NotCached)]
public class CustomerInsightsMCPEntity extends DataEntityView
{
    // Primary fields for bot queries
    [DataEntityViewMethodAttribute(true)]
    public CustAccount AccountNum;

    [DataEntityViewMethodAttribute(true)]
    public CustName Name;

    [DataEntityViewMethodAttribute(true)]
    public AmountCur OutstandingBalance;

    [DataEntityViewMethodAttribute(true)]
    public CustCreditMax CreditLimit;

    [DataEntityViewMethodAttribute(true)]
    public str PaymentTerms;

    [DataEntityViewMethodAttribute(true)]
    public TransDate LastPaymentDate;

    /// <summary>
    /// Computed field for risk assessment
    /// </summary>
    [DataEntityViewMethodAttribute(true)]
    public str RiskLevel
    {
        return this.calculateRiskLevel();
    }

    /// <summary>
    /// Override for performance optimization
    /// </summary>
    public Query buildEntityDataSourceQuery(QueryBuildDataSource _rootQueryBuildDataSource)
    {
        Query query = super(_rootQueryBuildDataSource);
        QueryBuildDataSource custTable = _rootQueryBuildDataSource;
        QueryBuildDataSource custTrans;

        // Join with customer transactions for balance calculation
        custTrans = custTable.addDataSource(tableNum(CustTrans));
        custTrans.relations(true);
        custTrans.joinMode(JoinMode::OuterJoin);

        // Add performance hints
        custTable.addSelectionField(fieldNum(CustTable, AccountNum), SelectionField::Database);
        custTable.addSelectionField(fieldNum(CustTable, CreditMax), SelectionField::Database);

        return query;
    }

    /// <summary>
    /// Calculate risk level based on balance and credit limit
    /// </summary>
    private str calculateRiskLevel()
    {
        real utilizationRatio;

        if (this.CreditLimit == 0)
        {
            return 'Unknown';
        }

        utilizationRatio = (this.OutstandingBalance / this.CreditLimit) * 100;

        if (utilizationRatio > 90)
        {
            return 'High';
        }
        else if (utilizationRatio > 70)
        {
            return 'Medium';
        }
        else
        {
            return 'Low';
        }
    }

    /// <summary>
    /// Security method - restrict data based on user permissions
    /// </summary>
    public void mapToCommon(Common _common)
    {
        CustTable custTable = _common as CustTable;

        // Verify user has access to this customer
        if (!SecurityRights::hasMenuItemAccess(menuItemActionStr(CustTableListPage), MenuItemType::Action))
        {
            throw Exception::Error;
        }

        super(_common);
    }
}

/// <summary>
/// MCP Service Controller for Teams Bot Integration
/// Handles authentication, query parsing, and response formatting
/// </summary>
[RoutePrefix('api/mcp/v1'),
 ApiController]
class MCPTeamsBotController extends ApiController
{
    private const str CacheKeyPrefix = 'MCPBot_';
    private const int CacheTimeoutMinutes = 15;

    /// <summary>
    /// Process natural language query and return D365 data
    /// </summary>
    [HttpPost,
 Route('query'),
 Authorization('Bearer')]
    public str processQuery(str _queryText, str _userContext)
    {
        MCPQueryResult result = new MCPQueryResult();

        try
        {
            // Validate authentication token
            if (!this.validateBearerToken())
            {
                result.setError('Authentication failed');
                return result.toJson();
            }

            // Parse natural language query
            MCPQueryParser parser = new MCPQueryParser();
            MCPQueryIntent intent = parser.parseQuery(_queryText, _userContext);

            // Check cache first
            str cacheKey = CacheKeyPrefix + intent.getCacheKey();
            str cachedResult = SysGlobalCache::get(cacheKey);

            if (cachedResult)
            {
                info(strFmt('Returning cached result for query: %1', _queryText));
                return cachedResult;
            }

            // Execute query based on intent
            switch (intent.getEntityType())
            {
                case MCPEntityType::Customer:
                    result = this.queryCustomerInsights(intent);
                    break;

                case MCPEntityType::SalesOrder:
                    result = this.querySalesOrders(intent);
                    break;

                case MCPEntityType::Invoice:
                    result = this.queryInvoices(intent);
                    break;

                default:
                    result.setError('Unsupported query type');
            }

            // Cache successful results
            if (result.isSuccess())
            {
                SysGlobalCache::set(cacheKey, result.toJson(), CacheTimeoutMinutes * 60);
            }
        }
        catch (Exception::Error)
        {
            result.setError(strFmt('Query processing failed: %1', Exception::getLastError()));
            EventLog::writeError('MCPBot', Exception::getLastError());
        }

        return result.toJson();
    }

    /// <summary>
    /// Query customer insights with security filtering
    /// </summary>
    private MCPQueryResult queryCustomerInsights(MCPQueryIntent _intent)
    {
        MCPQueryResult result = new MCPQueryResult();
        CustomerInsightsMCPEntity customerEntity;
        QueryRun queryRun;
        Query query = new Query();
        QueryBuildDataSource qbds;

        try
        {
            // Build query with user security context
            qbds = query.addDataSource(tableNum(CustomerInsightsMCPEntity));

            // Apply intent filters
            if (_intent.hasAccountFilter())
            {
                qbds.addRange(fieldNum(CustomerInsightsMCPEntity, AccountNum))
                    .value(_intent.getAccountNumber());
            }

            if (_intent.hasRiskFilter())
            {
                qbds.addRange(fieldNum(CustomerInsightsMCPEntity, RiskLevel))
                    .value(_intent.getRiskLevel());
            }

            // Limit results for performance
            qbds.firstOnly(false);
            query.topRows(50);

            queryRun = new QueryRun(query);

            while (queryRun.next())
            {
                customerEntity = queryRun.get(tableNum(CustomerInsightsMCPEntity));

                MCPCustomerData customerData = new MCPCustomerData();
                customerData.setAccountNum(customerEntity.AccountNum);
                customerData.setName(customerEntity.Name);
                customerData.setBalance(customerEntity.OutstandingBalance);
                customerData.setCreditLimit(customerEntity.CreditLimit);
                customerData.setRiskLevel(customerEntity.RiskLevel);

                result.addCustomerData(customerData);
            }

            result.setSuccess(true);
            info(strFmt('Retrieved %1 customer records for MCP query', result.getRecordCount()));
        }
        catch (Exception::Error)
        {
            result.setError(strFmt('Customer query failed: %1', Exception::getLastError()));
        }

        return result;
    }

    /// <summary>
    /// Validate Bearer token from Teams bot authentication
    /// </summary>
    private boolean validateBearerToken()
    {
        str authHeader = this.Request().getHeader('Authorization');
        str token;

        if (!authHeader || !strStartsWith(authHeader, 'Bearer '))
        {
            return false;
        }

        token = subStr(authHeader, 8); // Remove 'Bearer ' prefix

        try
        {
            // Validate token with Azure AD
            MCPTokenValidator validator = new MCPTokenValidator();
            return validator.validateToken(token);
        }
        catch
        {
            return false;
        }
    }
}

/// <summary>
/// MCP Query Parser - converts natural language to D365 queries
/// Handles intent recognition and parameter extraction
/// </summary>
class MCPQueryParser
{
    private Map intentPatterns;
    private Map entityMappings;

    /// <summary>
    /// Initialize parser with pre-defined patterns
    /// </summary>
    public void new()
    {
        super();
        this.initializePatterns();
        this.initializeEntityMappings();
    }

    /// <summary>
    /// Parse natural language query into structured intent
    /// </summary>
    public MCPQueryIntent parseQuery(str _queryText, str _userContext)
    {
        MCPQueryIntent intent = new MCPQueryIntent();
        str normalizedQuery = strLwr(_queryText);

        try
        {
            // Detect entity type
            intent.setEntityType(this.detectEntityType(normalizedQuery));

            // Extract parameters based on entity type
            switch (intent.getEntityType())
            {
                case MCPEntityType::Customer:
                    this.extractCustomerParameters(normalizedQuery, intent);
                    break;

                case MCPEntityType::SalesOrder:
                    this.extractSalesOrderParameters(normalizedQuery, intent);
                    break;

                default:
                    throw Exception::Error;
            }

            // Apply user context security
            this.applySecurityContext(intent, _userContext);

            info(strFmt('Parsed MCP query: Entity=%1, Filters=%2', 
                enum2Str(intent.getEntityType()), 
                intent.getFilterSummary()));
        }
        catch (Exception::Error)
        {
            intent.setError(strFmt('Query parsing failed: %1', Exception::getLastError()));
        }

        return intent;
    }

    /// <summary>
    /// Initialize regex patterns for intent recognition
    /// </summary>
    private void initializePatterns()
    {
        intentPatterns = new Map(Types::String, Types::String);

        // Customer patterns
        intentPatterns.insert('customer_balance', '(customer|account).*(balance|outstanding|owe)');
        intentPatterns.insert('customer_risk', '(customer|account).*(risk|credit)');
        intentPatterns.insert('customer_info', '(customer|account).*(info|detail|summary)');

        // Sales order patterns
        intentPatterns.insert('sales_status', '(sales|order).*(status|state)');
        intentPatterns.insert('sales_amount', '(sales|order).*(amount|value|total)');

        // Time-based patterns
        intentPatterns.insert('time_today', '(today|current)');
        intentPatterns.insert('time_week', '(week|weekly)');
        intentPatterns.insert('time_month', '(month|monthly)');
    }

    /// <summary>
    /// Map query terms to D365 entities
    /// </summary>
    private void initializeEntityMappings()
    {
        entityMappings = new Map(Types::String, Types::Enum);

        entityMappings.insert('customer', MCPEntityType::Customer);
        entityMappings.insert('account', MCPEntityType::Customer);
        entityMappings.insert('client', MCPEntityType::Customer);

        entityMappings.insert('sales', MCPEntityType::SalesOrder);
        entityMappings.insert('order', MCPEntityType::SalesOrder);

        entityMappings.insert('invoice', MCPEntityType::Invoice);
        entityMappings.insert('bill', MCPEntityType::Invoice);
    }

    /// <summary>
    /// Detect primary entity type from query text
    /// </summary>
    private MCPEntityType detectEntityType(str _normalizedQuery)
    {
        MapEnumerator enumerator = entityMappings.getEnumerator();

        while (enumerator.moveNext())
        {
            str keyword = enumerator.currentKey();

            if (strScan(_normalizedQuery, keyword, 1, strLen(_normalizedQuery)) > 0)
            {
                return enumerator.currentValue();
            }
        }

        // Default to customer if no specific entity detected
        return MCPEntityType::Customer;
    }

    /// <summary>
    /// Extract customer-specific parameters from query
    /// </summary>
    private void extractCustomerParameters(str _normalizedQuery, MCPQueryIntent _intent)
    {
        // Extract account number if present
        str accountPattern = '([a-z0-9]{3,10})';
        int accountPos = strScan(_normalizedQuery, accountPattern, 1, strLen(_normalizedQuery));

        if (accountPos > 0)
        {
            str potentialAccount = subStr(_normalizedQuery, accountPos, 10);

            // Validate account exists
            if (this.validateCustomerAccount(potentialAccount))
            {
                _intent.setAccountNumber(potentialAccount);
            }
        }

        // Extract risk level keywords
        if (strScan(_normalizedQuery, 'high risk', 1, strLen(_normalizedQuery)) > 0)
        {
            _intent.setRiskLevel('High');
        }
        else if (strScan(_normalizedQuery, 'medium risk', 1, strLen(_normalizedQuery)) > 0)
        {
            _intent.setRiskLevel('Medium');
        }
        else if (strScan(_normalizedQuery, 'low risk', 1, strLen(_normalizedQuery)) > 0)
        {
            _intent.setRiskLevel('Low');
        }

        // Extract balance thresholds
        this.extractAmountThresholds(_normalizedQuery, _intent);
    }

    /// <summary>
    /// Validate customer account exists in D365
    /// </summary>
    private boolean validateCustomerAccount(str _accountNum)
    {
        CustTable custTable;

        select firstOnly custTable
            where custTable.AccountNum == _accountNum;

        return custTable.RecId != 0;
    }

    /// <summary>
    /// Extract amount thresholds from natural language
    /// </summary>
    private void extractAmountThresholds(str _query, MCPQueryIntent _intent)
    {
        // Pattern matching for amounts (simplified)
        if (strScan(_query, 'over', 1, strLen(_query)) > 0 ||
            strScan(_query, 'above', 1, strLen(_query)) > 0)
        {
            // Extract numeric value
            str amountText = this.extractNumericValue(_query);
            if (amountText)
            {
                _intent.setMinAmount(str2Num(amountText));
            }
        }
    }

    /// <summary>
    /// Extract numeric values from query text
    /// </summary>
    private str extractNumericValue(str _query)
    {
        // Simplified numeric extraction
        int pos = 1;
        str result = '';

        while (pos <= strLen(_query))
        {
            str char = subStr(_query, pos, 1);

            if (char >= '0' && char <= '9' || char == '.' || char == ',')
            {
                result += char;
            }
            else if (result)
            {
                break;
            }

            pos++;
        }

        return strRem(result, ','); // Remove commas
    }
}

/// <summary>
/// Assigns a security role to a user with validation
/// </summary>
static void assignSecurityRoleToUser()
{
    SecurityUserRole    securityUserRole;
    UserInfo            userInfo;
    SecurityRole        securityRole;
    str                 userId = 'ADMIN';
    str                 roleName = 'SystemAdministrator';

    try
    {
        ttsbegin;

        // Validate user exists
        select firstonly userInfo
            where userInfo.id == userId;

        if (!userInfo.RecId)
        {
            throw error(strFmt('User %1 not found', userId));
        }

        // Find security role
        select firstonly securityRole
            where securityRole.AotName == roleName;

        if (!securityRole.RecId)
        {
            throw error(strFmt('Security role %1 not found', roleName));
        }

        // Check if assignment already exists
        select firstonly securityUserRole
            where securityUserRole.User == userId
               && securityUserRole.SecurityRole == securityRole.RecId;

        if (securityUserRole.RecId)
        {
            info(strFmt('User %1 already has role %2', userId, roleName));
            return;
        }

        // Create new role assignment
        securityUserRole.clear();
        securityUserRole.User = userId;
        securityUserRole.SecurityRole = securityRole.RecId;
        securityUserRole.AssignmentStatus = RoleAssignmentStatus::Enabled;
        securityUserRole.insert();

        ttscommit;

        info(strFmt('Successfully assigned role %1 to user %2', roleName, userId));
    }
    catch (Exception::Error)
    {
        ttsabort;
        error('Failed to assign security role');
    }
}

/// <summary>
/// Validates user permissions for specific menu items and forms
/// </summary>
class CustomSecurityValidator
{
    /// <summary>
    /// Checks if current user has access to a specific menu item
    /// </summary>
    /// <param name="_menuItemName">AOT name of the menu item</param>
    /// <param name="_menuItemType">Type of menu item (Display, Output, Action)</param>
    /// <returns>True if user has access</returns>
    public static boolean hasMenuItemAccess(str _menuItemName, MenuItemType _menuItemType)
    {
        SecurityRights  rights;
        MenuFunction    menuFunction;

        try
        {
            menuFunction = new MenuFunction(_menuItemName, _menuItemType);

            if (!menuFunction)
            {
                return false;
            }

            // Get effective rights for current user
            rights = menuFunction.accessRight();

            return (rights > SecurityRights::NoAccess);
        }
        catch (Exception::Error)
        {
            error(strFmt('Failed to check access for menu item %1', _menuItemName));
            return false;
        }
    }

    /// <summary>
    /// Validates table-level permissions for current user
    /// </summary>
    /// <param name="_tableId">Table ID to check</param>
    /// <param name="_accessType">Required access level</param>
    /// <returns>True if user has sufficient access</returns>
    public static boolean hasTableAccess(TableId _tableId, AccessType _accessType)
    {
        SecurityRights  requiredRights;
        SecurityRights  userRights;
        Common          tableBuffer;

        // Convert AccessType to SecurityRights
        switch (_accessType)
        {
            case AccessType::View:
                requiredRights = SecurityRights::View;
                break;
            case AccessType::Edit:
                requiredRights = SecurityRights::Edit;
                break;
            case AccessType::Delete:
                requiredRights = SecurityRights::Delete;
                break;
            default:
                return false;
        }

        try
        {
            tableBuffer = new DictTable(_tableId).makeRecord();
            userRights = tableBuffer.accessRight();

            return (userRights >= requiredRights);
        }
        catch (Exception::Error)
        {
            warning(strFmt('Could not determine table access for table ID %1', _tableId));
            return false;
        }
    }

    /// <summary>
    /// Comprehensive permission check for custom business logic
    /// </summary>
    public static void validateSalesOrderAccess()
    {
        SalesTable      salesTable;
        boolean         hasCreateAccess;
        boolean         hasDeleteAccess;

        // Check menu item access
        if (!CustomSecurityValidator::hasMenuItemAccess('SalesTableListPage', MenuItemType::Display))
        {
            throw error('Insufficient privileges to access Sales Orders');
        }

        // Check table permissions
        hasCreateAccess = CustomSecurityValidator::hasTableAccess(tableNum(SalesTable), AccessType::Edit);
        hasDeleteAccess = CustomSecurityValidator::hasTableAccess(tableNum(SalesTable), AccessType::Delete);

        info(strFmt('Sales Order Access - Create: %1, Delete: %2', 
                   hasCreateAccess ? 'Yes' : 'No',
                   hasDeleteAccess ? 'Yes' : 'No'));
    }
}

/// <summary>
/// XDS Policy to restrict customer access by sales territory
/// Constrained table: CustTable
/// Context table: SalesRepTerritoryAssignment (custom table)
/// </summary>
public class XdsCustomerTerritoryPolicy extends SysSecurityPolicyBase
{
    public Query authorize()
    {
        Query                       policyQuery;
        QueryBuildDataSource        custTableDs;
        QueryBuildDataSource        territoryDs;
        QueryBuildRange             userRange;
        UserId                      currentUser;

        currentUser = curUserId();

        // Build the security constraint query
        policyQuery = new Query();

        // Add CustTable as primary datasource
        custTableDs = policyQuery.addDataSource(tableNum(CustTable));
        custTableDs.name('CustTable');

        // Join to territory assignment table
        territoryDs = custTableDs.addDataSource(tableNum(SalesRepTerritoryAssignment));
        territoryDs.name('TerritoryAssignment');
        territoryDs.joinMode(JoinMode::InnerJoin);
        territoryDs.relations(false);

        // Define join condition: customer territory = assigned territory
        territoryDs.addLink(fieldNum(CustTable, SalesTerritoryId),
                           fieldNum(SalesRepTerritoryAssignment, TerritoryId));

        // Add user constraint
        userRange = territoryDs.addRange(fieldNum(SalesRepTerritoryAssignment, UserId));
        userRange.value(queryValue(currentUser));

        // Add active territory constraint
        territoryDs.addRange(fieldNum(SalesRepTerritoryAssignment, IsActive))
                  .value(queryValue(NoYes::Yes));

        info(strFmt("XDS Policy applied for user %1", currentUser));

        return policyQuery;
    }

