    {
        return true;
    }
}

/// <summary>
/// Advanced XDS Policy for organizational hierarchy with dynamic context
/// Supports manager access to subordinate data with caching optimization
/// </summary>
public class XdsOrganizationalHierarchyPolicy extends SysSecurityPolicyBase
{
    private static Map              hierarchyCache;
    private static utcdatetime      cacheExpiry;
    private const int               CACHE_DURATION_MINUTES = 30;

    /// <summary>
    /// Build hierarchical security query with caching
    /// </summary>
    public Query authorize()
    {
        Query                       policyQuery;
        QueryBuildDataSource        empTableDs;
        QueryBuildDataSource        hierarchyDs;
        QueryBuildRange             hierarchyRange;
        Set                         authorizedEmployees;
        SetEnumerator              setEnum;
        str                        employeeList;

        try
        {
            // Get authorized employee list (with caching)
            authorizedEmployees = this.getAuthorizedEmployees();

            if (authorizedEmployees.elements() == 0)
            {
                // Return empty query if no access
                policyQuery = new Query();
                policyQuery.addDataSource(tableNum(HcmWorker));
                policyQuery.firstDataSource().addRange(fieldNum(HcmWorker, RecId))
                          .value('((RecId == 0))');
                return policyQuery;
            }

            // Build employee ID list for IN clause
            setEnum = authorizedEmployees.getEnumerator();
            employeeList = '';

            while (setEnum.moveNext())
            {
                if (employeeList != '')
                    employeeList += ',';
                employeeList += strFmt("'%1'", setEnum.current());
            }

            // Create optimized query using IN clause
            policyQuery = new Query();
            empTableDs = policyQuery.addDataSource(tableNum(HcmWorker));
            empTableDs.name('AuthorizedWorkers');

            hierarchyRange = empTableDs.addRange(fieldNum(HcmWorker, PersonnelNumber));
            hierarchyRange.value(strFmt('((%1.%2 IN (%3)))',
                                      empTableDs.name(),
                                      fieldStr(HcmWorker, PersonnelNumber),
                                      employeeList));

            info(strFmt("Hierarchical XDS: %1 employees authorized for %2", 
                       authorizedEmployees.elements(), curUserId()));
        }
        catch (Exception::Error)
        {
            error("XDS Policy authorization failed - access denied");
            throw Exception::Error;
        }

        return policyQuery;
    }

    /// <summary>
    /// Get authorized employees with hierarchical caching
    /// </summary>
    private Set getAuthorizedEmployees()
    {
        Set                         authorizedSet;
        HcmPositionHierarchy        hierarchyTable;
        HcmWorker                   workerTable;
        UserId                      currentUser;
        str                         cacheKey;
        utcdatetime                 now;

        currentUser = curUserId();
        cacheKey = strFmt("%1_hierarchy", currentUser);
        now = DateTimeUtil::utcNow();

        // Initialize cache if needed
        if (!hierarchyCache)
        {
            hierarchyCache = new Map(Types::String, Types::Class);
            cacheExpiry = now;
        }

        // Check cache validity
        if (cacheExpiry < now || !hierarchyCache.exists(cacheKey))
        {
            authorizedSet = new Set(Types::String);

            // Add current user's employee ID
            select PersonnelNumber from workerTable
                where workerTable.UserId == currentUser;

            if (workerTable.PersonnelNumber)
            {
                authorizedSet.add(workerTable.PersonnelNumber);
            }

            // Add subordinates recursively
            this.addSubordinates(authorizedSet, workerTable.PersonnelNumber, 0);

            // Cache the result
            hierarchyCache.insert(cacheKey, authorizedSet);
            cacheExpiry = DateTimeUtil::addMinutes(now, CACHE_DURATION_MINUTES);
        }
        else
        {
            // Use cached result
            authorizedSet = hierarchyCache.lookup(cacheKey);
        }

        return authorizedSet;
    }

    /// <summary>
    /// Recursively add subordinates to authorized set
    /// </summary>
    private void addSubordinates(Set _authorizedSet, HcmPersonnelNumberId _managerId, int _depth)
    {
        HcmPositionHierarchy        hierarchyTable;
        HcmWorker                   subordinateWorker;

        // Prevent infinite recursion
        if (_depth > 10)
            return;

        while select PersonnelNumber from subordinateWorker
            exists join hierarchyTable
            where hierarchyTable.SubordinatePersonnelNumber == subordinateWorker.PersonnelNumber
               && hierarchyTable.ManagerPersonnelNumber == _managerId
               && hierarchyTable.ValidFrom <= DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone())
               && hierarchyTable.ValidTo >= DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone())
        {
            if (!_authorizedSet.in(subordinateWorker.PersonnelNumber))
            {
                _authorizedSet.add(subordinateWorker.PersonnelNumber);
                // Recursively add subordinates of subordinates
                this.addSubordinates(_authorizedSet, subordinateWorker.PersonnelNumber, _depth + 1);
            }
        }
    }

    public boolean crossCompanyAutoQuery()
    {
        return false; // Hierarchy is company-specific
    }

    /// <summary>
    /// Clear cache when security context changes
    /// </summary>
    public static void clearHierarchyCache()
    {
        if (hierarchyCache)
        {
            hierarchyCache = null;
            cacheExpiry = DateTimeUtil::minValue();
        }
    }
}

