public class AuditTrailInquiry extends RunBase
{
    DialogField dialogFieldFromDate;
    DialogField dialogFieldToDate;
    DialogField dialogFieldUserId;
    DialogField dialogFieldTableId;

    FromDate fromDate;
    ToDate toDate;
    UserId userId;
    TableId auditTableId;

    public void generateAuditReport()
    {
        SysDatabaseLog sysDatabaseLog;
        SysDatabaseLogDetail sysDatabaseLogDetail;
        Query query;
        QueryBuildDataSource qbds;
        QueryRun queryRun;

        try
        {
            query = new Query();
            qbds = query.addDataSource(tableNum(SysDatabaseLog));
            qbds.addSelectionField(fieldNum(SysDatabaseLog, createdDateTime));
            qbds.addSelectionField(fieldNum(SysDatabaseLog, createdBy));
            qbds.addSelectionField(fieldNum(SysDatabaseLog, company));
            qbds.addSelectionField(fieldNum(SysDatabaseLog, table));
            qbds.addSelectionField(fieldNum(SysDatabaseLog, logType));

            // Add date range filter
            if (fromDate && toDate)
            {
                qbds.addRange(fieldNum(SysDatabaseLog, createdDateTime))
                    .value(queryRange(DateTimeUtil::newDateTime(fromDate, 0), 
                                     DateTimeUtil::newDateTime(toDate, 86399)));
            }

            // Add user filter
            if (userId)
            {
                qbds.addRange(fieldNum(SysDatabaseLog, createdBy)).value(userId);
            }

            // Add table filter
            if (auditTableId)
            {
                qbds.addRange(fieldNum(SysDatabaseLog, table)).value(int2Str(auditTableId));
            }

            // Join with detail table for field-level changes
            QueryBuildDataSource qbdsDetail = qbds.addDataSource(tableNum(SysDatabaseLogDetail));
            qbdsDetail.joinMode(JoinMode::ExistsJoin);
            qbdsDetail.relations(true);

            queryRun = new QueryRun(query);

            info("=== Audit Trail Report ===");

            while (queryRun.next())
            {
                sysDatabaseLog = queryRun.get(tableNum(SysDatabaseLog));

                info(strFmt("Date: %1 | User: %2 | Table: %3 | Action: %4 | Company: %5",
                    DateTimeUtil::toStr(sysDatabaseLog.createdDateTime),
                    sysDatabaseLog.createdBy,
                    tableId2name(sysDatabaseLog.table),
                    enum2Str(sysDatabaseLog.logType),
                    sysDatabaseLog.company));

                // Get detailed field changes
                this.printFieldChanges(sysDatabaseLog.RecId);
            }
        }
        catch (Exception::Error)
        {
            error("Error generating audit trail report");
        }
    }

    private void printFieldChanges(RecId _logRecId)
    {
        SysDatabaseLogDetail logDetail;

        while select logDetail
            where logDetail.databaseLog == _logRecId
        {
            info(strFmt("  Field: %1 | Old: %2 | New: %3",
                fieldId2name(logDetail.table, logDetail.field),
                logDetail.oldValue ? logDetail.oldValue : "<empty>",
                logDetail.newValue ? logDetail.newValue : "<empty>"));
        }
    }
}

[ExtensionOf(tableStr(CustTable))]
final class CustTableAuditExtension
{
    public void update()
    {
        CustTable originalRecord = this.orig();
        boolean creditMaxChanged = false;
        boolean custGroupChanged = false;

        // Capture significant business changes before update
        if (originalRecord.CreditMax != this.CreditMax)
        {
            creditMaxChanged = true;
        }

        if (originalRecord.CustGroup != this.CustGroup)
        {
            custGroupChanged = true;
        }

        // Call original update method
        next update();

        // Post-update audit logging for business-critical changes
        if (creditMaxChanged || custGroupChanged)
        {
            this.logCriticalCustomerChange(originalRecord, creditMaxChanged, custGroupChanged);
        }
    }

    private void logCriticalCustomerChange(CustTable _original, boolean _creditMaxChanged, boolean _custGroupChanged)
    {
        SysEventLog eventLog;
        str auditMessage;

        ttsbegin;
        try
        {
            auditMessage = strFmt("Critical customer change - Account: %1", this.AccountNum);

            if (_creditMaxChanged)
            {
                auditMessage += strFmt(" | Credit limit changed from %1 to %2",
                                     _original.CreditMax, this.CreditMax);
            }

            if (_custGroupChanged)
            {
                auditMessage += strFmt(" | Customer group changed from %1 to %2",
                                     _original.CustGroup, this.CustGroup);
            }

            // Log to system event log for immediate alerting
            eventLog.clear();
            eventLog.Module = ModuleAxapta::Ledger;
            eventLog.Type = SysEventLogType::Warning;
            eventLog.Function = classStr(CustTableAuditExtension);
            eventLog.Description = auditMessage;
            eventLog.Company = curext();
            eventLog.UserId = curuserid();
            eventLog.ComputerName = WinAPIServer::getComputerName();
            eventLog.insert();

            // Send alert to finance manager if credit limit increased significantly
            if (_creditMaxChanged && (this.CreditMax - _original.CreditMax) > 10000)
            {
                this.sendCreditLimitAlert(_original.CreditMax, this.CreditMax);
            }

            ttscommit;
        }
        catch (Exception::Error)
        {
            ttsabort;
            warning("Failed to log critical customer change audit event");
        }
    }

    private void sendCreditLimitAlert(AmountMST _oldLimit, AmountMST _newLimit)
    {
        SysMailerMessageBuilder messageBuilder;
        SysMailerFactory mailerFactory;

        messageBuilder = new SysMailerMessageBuilder();
        messageBuilder.setSubject(strFmt("Credit Limit Alert - Customer %1", this.AccountNum));
        messageBuilder.setBody(strFmt("Customer %1 (%2) credit limit increased from %3 to %4 by user %5",
                                    this.AccountNum, this.name(),
                                    _oldLimit, _newLimit, curuserid()));

        // Add finance manager as recipient (configuration should come from parameters)
        messageBuilder.addTo("finance.manager@contoso.com");

        mailerFactory = SysMailerFactory::getNonInteractiveMailer();
        mailerFactory.sendNonInteractive(messageBuilder.getMessage());
    }
}

