/// <summary>
/// Custom encryption service handling complex encryption scenarios
/// with automatic key rotation and performance optimization
/// </summary>
class CustomSensitiveDataService extends SysEncryptionServiceBase
{
    private SysEncryptionEngine encryptionEngine;
    private SysEncryptionCache encryptionCache;
    private boolean useCache;

    public void new()
    {
        super();
        this.encryptionEngine = new SysEncryptionEngine();
        this.encryptionCache = SysEncryptionCache::getInstance();
        this.useCache = true;
    }

    /// <summary>
    /// Encrypts sensitive data with automatic key validation
    /// </summary>
    public EncryptedFieldData encryptSensitiveData(str _plainText, 
                                                   FieldId _fieldId, 
                                                   TableId _tableId)
    {
        EncryptedFieldData encryptedData;
        SysEncryptionKey currentKey;
        str keyId;

        if (!_plainText)
        {
            return encryptedData;
        }

        try
        {
            // Get active encryption key for field
            keyId = this.getActiveKeyForField(_tableId, _fieldId);

            if (!keyId)
            {
                throw error(strFmt("@SYS_NoEncryptionKeyFound", fieldId2name(_tableId, _fieldId)));
            }

            // Check if key needs rotation
            if (this.isKeyRotationRequired(keyId))
            {
                this.rotateEncryptionKey(keyId, _tableId, _fieldId);
            }

            // Perform encryption with current key
            encryptedData = this.encryptionEngine.encrypt(_plainText, keyId);

            // Cache for performance if enabled
            if (this.useCache)
            {
                this.encryptionCache.cacheEncryptionMetadata(_tableId, _fieldId, keyId);
            }

            // Log encryption event for audit
            this.logEncryptionEvent(_tableId, _fieldId, curUserId(), 'Encrypt');

            return encryptedData;
        }
        catch (Exception::Error)
        {
            error(strFmt("@SYS_EncryptionFailed", fieldId2name(_tableId, _fieldId)));
            return encryptedData;
        }
    }

    /// <summary>
    /// Bulk encryption for data migration scenarios
    /// </summary>
    public void bulkEncryptTableData(TableId _tableId, FieldId _fieldId, int _batchSize = 1000)
    {
        Common sourceTable = new DictTable(_tableId).makeRecord();
        QueryBuild queryBuild;
        QueryRun queryRun;
        int processedRecords = 0;

        queryBuild = new QueryBuild();
        queryBuild.dataSourceTable(_tableId);
        queryRun = new QueryRun(queryBuild);

        ttsbegin;
        try
        {
            while (queryRun.next())
            {
                sourceTable = queryRun.get(_tableId);

                // Process field encryption
                this.processRecordEncryption(sourceTable, _fieldId);

                processedRecords++;

                // Commit in batches for performance
                if (processedRecords % _batchSize == 0)
                {
                    ttscommit;
                    ttsbegin;
                    info(strFmt("Processed %1 records", processedRecords));
                }
            }

            ttscommit;
            info(strFmt("Bulk encryption completed. Total records: %1", processedRecords));
        }
        catch (Exception::Error)
        {
            ttsabort;
            error("Bulk encryption failed");
        }
    }

    private void processRecordEncryption(Common _record, FieldId _fieldId)
    {
        DictField dictField = new DictField(_record.TableId, _fieldId);
        str plainTextValue = dictField.getValue(_record);
        EncryptedFieldData encryptedData;

        if (plainTextValue)
        {
            encryptedData = this.encryptSensitiveData(plainTextValue, 
                                                      _fieldId, 
                                                      _record.TableId);
            dictField.setValue(_record, encryptedData.EncryptedValue);
            _record.update();
        }
    }

    private str getActiveKeyForField(TableId _tableId, FieldId _fieldId)
    {
        EncryptionPolicy policy;

        select firstonly KeyId from policy
        where policy.TableId == _tableId
           && policy.FieldId == _fieldId
           && policy.IsEnabled == NoYes::Yes;

        return policy.KeyId;
    }
}

/// <summary>
/// Secure decryption service with integrated access control
/// </summary>
class SecureDecryptionService
{
    private SysDecryptionEngine decryptionEngine;
    private SecurityRights securityRights;

    public void new()
    {
        this.decryptionEngine = new SysDecryptionEngine();
        this.securityRights = new SecurityRights();
    }

    /// <summary>
    /// Decrypts field data with security validation
    /// </summary>
    public str decryptSensitiveField(Common _record, FieldId _fieldId)
    {
        str decryptedValue = '';
        DictField dictField;
        EncryptedFieldData encryptedData;

        try
        {
            // Validate user access to sensitive field
            if (!this.validateFieldAccess(_record.TableId, _fieldId, curUserId()))
            {
                throw error(strFmt("@SYS_InsufficientPermissions", 
                                  fieldId2name(_record.TableId, _fieldId)));
            }

            dictField = new DictField(_record.TableId, _fieldId);
            encryptedData = dictField.getValue(_record);

            if (!encryptedData.EncryptedValue)
            {
                return '';
            }

            // Perform decryption
            decryptedValue = this.decryptionEngine.decrypt(encryptedData);

            // Log access for audit trail
            this.logFieldAccess(_record.TableId, _fieldId, curUserId(), 'Decrypt');

            // Apply data masking if required
            if (this.requiresDataMasking(_record.TableId, _fieldId))
            {
                decryptedValue = this.maskSensitiveData(decryptedValue, _fieldId);
            }

            return decryptedValue;
        }
        catch (Exception::Error)
        {
            error(strFmt("@SYS_DecryptionFailed", fieldId2name(_record.TableId, _fieldId)));
            return '';
        }
    }

    private boolean validateFieldAccess(TableId _tableId, FieldId _fieldId, UserId _userId)
    {
        SecurityUserRole userRole;
        SecurityRole role;
        SecurityPermission permission;

        // Check if user has explicit permission for sensitive data
        select firstonly RecId from userRole
        join role
        where userRole.User == _userId
           && userRole.SecurityRole == role.RecId
           && role.Name == 'SensitiveDataAccess'

        join permission
        where permission.SecurityRole == role.RecId
           && permission.ObjectType == SecurableType::Table
           && permission.ObjectName == tableId2name(_tableId)
           && permission.AccessRight >= AccessRight::Read;

        return userRole.RecId != 0;
    }

    private str maskSensitiveData(str _value, FieldId _fieldId)
    {
        // Apply appropriate masking based on field type
        switch (_fieldId)
        {
            case fieldNum(CustTable, SocialSecurityNumber):
                return this.maskSSN(_value);

            case fieldNum(BankAccount, AccountNum):
                return this.maskBankAccount(_value);

            default:
                return this.maskGeneric(_value);
        }
    }

    private str maskSSN(str _ssn)
    {
        if (strlen(_ssn) >= 4)
        {
            return 'XXX-XX-' + substr(_ssn, strlen(_ssn) - 3, 4);
        }
        return 'XXX-XX-XXXX';
    }

    private void logFieldAccess(TableId _tableId, FieldId _fieldId, UserId _userId, str _operation)
    {
        SysEncryptionAudit auditLog;

        auditLog.clear();
        auditLog.TableId = _tableId;
        auditLog.FieldId = _fieldId;
        auditLog.UserId = _userId;
        auditLog.Operation = _operation;
        auditLog.AccessDateTime = DateTimeUtil::utcNow();
        auditLog.SessionId = sessionId();
        auditLog.insert();
    }
}

/// <summary>
/// Custom ER data provider for advanced customer analytics
/// </summary>
class ERCustomerAnalyticsDataProvider extends ERIModelMappingDataSourceView
{
    private CustTable custTable;
    private TransDate fromDate;
    private TransDate toDate;

    protected void new()
    {
        super();
    }

    /// <summary>
    /// Factory method for data provider instantiation
    /// </summary>
    public static ERCustomerAnalyticsDataProvider construct()
    {
        return new ERCustomerAnalyticsDataProvider();
    }

    /// <summary>
    /// Initialize provider with runtime parameters
    /// </summary>
    public void init(ERModelMappingRuntimeContext _runtimeContext)
    {
        super(_runtimeContext);

        // Extract parameters from ER runtime context
        ERDataContainerParameterized paramContainer = _runtimeContext.getParameters();
        if (paramContainer)
        {
            this.fromDate = paramContainer.getValueByName('FromDate');
            this.toDate = paramContainer.getValueByName('ToDate');
        }
    }

    /// <summary>
    /// Main data retrieval method called by ER runtime
    /// </summary>
    public Common getFirstRecord()
    {
        QueryRun queryRun;
        Query query = new Query();
        QueryBuildDataSource qbds;

        try
        {
            // Build dynamic query for customer analytics
            qbds = query.dataSourceTable(tableNum(CustTable));
            qbds.addRange(fieldNum(CustTable, Blocked)).value(CustVendorBlocked::No);

            if (this.fromDate && this.toDate)
            {
                QueryBuildDataSource qbdsTrans = qbds.addDataSource(tableNum(CustTrans));
                qbdsTrans.joinMode(JoinMode::InnerJoin);
                qbdsTrans.addLink(fieldNum(CustTable, AccountNum), fieldNum(CustTrans, AccountNum));
                qbdsTrans.addRange(fieldNum(CustTrans, TransDate)).value(
                    queryRange(this.fromDate, this.toDate));
            }

            queryRun = new QueryRun(query);

            if (queryRun.next())
            {
                this.custTable = queryRun.get(tableNum(CustTable));
                return this.custTable;
            }
        }
        catch (Exception::Error)
        {
            error("Error in ERCustomerAnalyticsDataProvider::getFirstRecord()");
        }

        return null;
    }

    /// <summary>
    /// Navigate to next record in result set
    /// </summary>
    public Common getNextRecord()
    {
        if (queryRun && queryRun.next())
        {
            this.custTable = queryRun.get(tableNum(CustTable));
            return this.custTable;
        }

        return null;
    }

    /// <summary>
    /// Custom calculated field for customer risk score
    /// </summary>
    [ERExpressionFunction('CustomerRiskScore')]
    public static real calculateRiskScore(str _accountNum)
    {
        CustTable custTable;
        CustTrans custTrans;
        real riskScore = 0.0;

        try
        {
            select custTable where custTable.AccountNum == _accountNum;

            if (!custTable)
                return 0.0;

            // Calculate based on payment history
            while select sum(AmountCur) from custTrans
                where custTrans.AccountNum == _accountNum
                   && custTrans.TransDate >= today() - 365
                   && custTrans.TransType == LedgerTransType::Payment
            {
                if (custTrans.AmountCur < 0)
                    riskScore += abs(custTrans.AmountCur) * 0.1;
            }

            // Apply customer group multiplier
            switch (custTable.CustGroup)
            {
                case '10': // High risk group
                    riskScore *= 1.5;
                    break;
                case '20': // Medium risk
                    riskScore *= 1.2;
                    break;
                default:
                    break;
            }
        }
        catch (Exception::Error)
        {
            warning(strFmt("Risk calculation failed for customer %1", _accountNum));
        }

        return riskScore;
    }
}

/// <summary>
/// Custom ER format executor with enhanced document processing
/// </summary>
class ERCustomFormatExecutor
{
    private ERFormatMappingId formatMappingId;
    private ERModelMappingId modelMappingId;
    private DocuRef docuRef;

    protected void new(ERFormatMappingId _formatMappingId, ERModelMappingId _modelMappingId)
    {
        this.formatMappingId = _formatMappingId;
        this.modelMappingId = _modelMappingId;
    }

    public static ERCustomFormatExecutor construct(ERFormatMappingId _formatMappingId, ERModelMappingId _modelMappingId)
    {
        return new ERCustomFormatExecutor(_formatMappingId, _modelMappingId);
    }

    /// <summary>
    /// Execute ER format with comprehensive error handling and logging
    /// </summary>
    public container executeFormat(Map _parameters = null)
    {
        ERFormatMappingRun formatRun;
        ERModelMappingDestinationRun destinationRun;
        ERDocuManagementParameters docuParams;
        System.IO.Stream outputStream;
        container result;

        try
        {
            ttsbegin;

            // Pre-processing: Validate configuration and parameters
            this.validateConfiguration();
            this.logExecutionStart();

            // Create ER runtime context with parameters
            ERModelMappingRuntimeContext runtimeContext = this.createRuntimeContext(_parameters);

            // Initialize format mapping run
            formatRun = ERFormatMappingRun::constructForFormatMappingId(this.formatMappingId);
            formatRun.init(runtimeContext);

            // Set up document management for generated output
            docuParams = this.setupDocumentManagement();
            formatRun.setDocuManagementParameters(docuParams);

            // Execute the format mapping
            destinationRun = formatRun.run();

            if (destinationRun)
            {
                // Post-processing: Handle generated document
                outputStream = destinationRun.getStream();
                this.docuRef = this.attachToDocumentManagement(outputStream);

                // Custom business logic after generation
                this.executePostProcessingActions();

                result = [true, this.docuRef.RecId, destinationRun.getFileName()];

                info(strFmt("ER format executed successfully. Document: %1", this.docuRef.RecId));
            }
            else
            {
                throw error("ER format execution failed - no output generated");
            }

            ttscommit;
        }
        catch (Exception::Error)
        {
            ttsabort;
            this.logExecutionError(infolog.text());
            result = [false, 0, ""];
        }
        finally
        {
            this.cleanupResources();
        }

        return result;
    }

    private ERModelMappingRuntimeContext createRuntimeContext(Map _parameters)
    {
        ERModelMappingRuntimeContext context;
        ERDataContainerParameterized paramContainer;
        MapEnumerator mapEnum;

        context = ERModelMappingRuntimeContext::construct();

        if (_parameters && _parameters.elements())
        {
            paramContainer = ERDataContainerParameterized::construct();
            mapEnum = _parameters.getEnumerator();

            while (mapEnum.moveNext())
            {
                paramContainer.setValueByName(mapEnum.currentKey(), mapEnum.currentValue());
            }

            context.setParameters(paramContainer);
        }

        // Set company context for cross-company scenarios
        context.setDefaultCompany(curext());

        return context;
    }

    private void validateConfiguration()
    {
        ERFormatMappingTable formatMapping;
        ERModelMappingTable modelMapping;

        // Validate format mapping exists and is active
        select firstonly formatMapping
            where formatMapping.MappingId == this.formatMappingId
               && formatMapping.Status == ERConfigurationStatus::Completed;

        if (!formatMapping)
        {
            throw error(strFmt("Format mapping %1 not found or inactive", this.formatMappingId));
        }

        // Validate model mapping compatibility
        select firstonly modelMapping
            where modelMapping.MappingId == this.modelMappingId
               && modelMapping.RootDefinitionId == formatMapping.RootDefinitionId;

        if (!modelMapping)
        {
            throw error(strFmt("Model mapping %1 incompatible with format %2", 
                this.modelMappingId, this.formatMappingId));
        }
    }

    private DocuRef attachToDocumentManagement(System.IO.Stream _outputStream)
    {
        DocuValue docuValue;
        DocuRef localDocuRef;

