/// <summary>
/// Custom builder for creating specialized financial dimension hierarchies
/// Used for complex organizational reporting structures
/// </summary>
class CustomFinancialHierarchyBuilder
{
    private DimensionHierarchy dimensionHierarchy;
    private DimensionAttribute dimensionAttribute;

    public void buildCustomHierarchy(Name _hierarchyName, DimensionAttribute _dimAttribute)
    {
        ttsbegin;

        try
        {
            // Create the dimension hierarchy
            dimensionHierarchy = DimensionHierarchy::construct();
            dimensionHierarchy.Name = _hierarchyName;
            dimensionHierarchy.DimensionAttribute = _dimAttribute.RecId;
            dimensionHierarchy.IsActive = NoYes::Yes;
            dimensionHierarchy.insert();

            // Build hierarchy nodes based on MainAccount structure
            this.buildHierarchyNodes();

            ttscommit;
            info(strFmt("Custom hierarchy '%1' created successfully", _hierarchyName));
        }
        catch (Exception::Error)
        {
            ttsabort;
            error("Failed to create custom financial hierarchy");
        }
    }

    private void buildHierarchyNodes()
    {
        MainAccount mainAccount;
        DimensionHierarchyNode hierarchyNode;
        DimensionAttributeValue dimAttrValue;

        while select mainAccount
            where mainAccount.MainAccountCategory == MainAccountCategory::Revenue
                || mainAccount.MainAccountCategory == MainAccountCategory::Expense
        {
            // Find corresponding dimension attribute value
            select firstonly dimAttrValue
                where dimAttrValue.DimensionAttribute == dimensionAttribute.RecId
                   && dimAttrValue.EntityInstance == mainAccount.RecId;

            if (dimAttrValue.RecId)
            {
                // Create hierarchy node
                hierarchyNode.clear();
                hierarchyNode.DimensionHierarchy = dimensionHierarchy.RecId;
                hierarchyNode.DimensionAttributeValue = dimAttrValue.RecId;
                hierarchyNode.ParentDimensionHierarchyNode = 0; // Root level
                hierarchyNode.Name = mainAccount.Name;
                hierarchyNode.insert();
            }
        }
    }

    /// <summary>
    /// Validates hierarchy structure for reporting consistency
    /// </summary>
    public boolean validateHierarchy()
    {
        DimensionHierarchyNode node;
        boolean isValid = true;

        select count(RecId) from node
            where node.DimensionHierarchy == dimensionHierarchy.RecId;

        if (node.RecId == 0)
        {
            warning("Hierarchy contains no nodes");
            isValid = false;
        }

        return isValid;
    }
}

/// <summary>
/// Service for automated financial report generation and distribution
/// Integrates with Management Reporter web service APIs
/// </summary>
class FinancialReportGenerationService extends SysOperationServiceBase
{
    /// <summary>
    /// Generates financial reports for specified period and distributes via email
    /// </summary>
    public void processMonthlyReports(FinancialReportGenerationContract _contract)
    {
        System.Collections.IEnumerator reportEnumerator;
        FinancialReportDefinition reportDef;
        str reportOutput, emailSubject;

        try
        {
            // Get active report definitions for monthly cycle
            reportEnumerator = this.getActiveReportDefinitions(_contract.parmReportingPeriod());

            while (reportEnumerator && reportEnumerator.moveNext())
            {
                reportDef = reportEnumerator.get_Current();

                // Generate report with specified parameters
                reportOutput = this.generateReport(reportDef, _contract);

                if (reportOutput)
                {
                    // Distribute report via configured channels
                    this.distributeReport(reportDef, reportOutput, _contract);

                    info(strFmt("Successfully generated report: %1", reportDef.Name));
                }
                else
                {
                    warning(strFmt("Failed to generate report: %1", reportDef.Name));
                }
            }
        }
        catch (Exception::CLRError)
        {
            error("CLR error occurred during report generation");
            throw Exception::CLRError;
        }
    }

    private str generateReport(FinancialReportDefinition _reportDef, FinancialReportGenerationContract _contract)
    {
        System.Collections.Specialized.NameValueCollection parameters;
        Microsoft.Dynamics.AX.Framework.Reporting.Reports.FinancialReportingService service;
        str reportGuid, outputPath;

        // Initialize reporting service connection
        service = new Microsoft.Dynamics.AX.Framework.Reporting.Reports.FinancialReportingService();

        // Set report parameters
        parameters = new System.Collections.Specialized.NameValueCollection();
        parameters.Add("ReportingPeriod", _contract.parmReportingPeriod());
        parameters.Add("CompanyFilter", _contract.parmCompanyFilter());
        parameters.Add("CurrencyCode", _contract.parmCurrencyCode());

        // Generate report asynchronously
        reportGuid = service.GenerateReport(_reportDef.ReportId, parameters);

        // Poll for completion
        outputPath = this.waitForReportCompletion(service, reportGuid, 300); // 5 minute timeout

        return outputPath;
    }

    private str waitForReportCompletion(Microsoft.Dynamics.AX.Framework.Reporting.Reports.FinancialReportingService _service, str _reportGuid, int _timeoutSeconds)
    {
        int elapsedSeconds = 0;
        str status, outputPath;

        while (elapsedSeconds < _timeoutSeconds)
        {
            status = _service.GetReportStatus(_reportGuid);

            if (status == "Completed")
            {
                outputPath = _service.GetReportOutput(_reportGuid);
                break;
            }
            else if (status == "Error")
            {
                error(strFmt("Report generation failed for GUID: %1", _reportGuid));
                break;
            }

            // Wait 10 seconds before checking again
            Thread::sleep(10000);
            elapsedSeconds += 10;
        }

        if (elapsedSeconds >= _timeoutSeconds)
        {
            warning(strFmt("Report generation timed out for GUID: %1", _reportGuid));
        }

        return outputPath;
    }

    private void distributeReport(FinancialReportDefinition _reportDef, str _reportOutput, FinancialReportGenerationContract _contract)
    {
        SysEmailDistributor emailDistributor;
        SysEmailMessage emailMessage;
        System.IO.FileInfo fileInfo;

        // Create email message
        emailMessage = new SysEmailMessage();
        emailMessage.parmSubject(strFmt("Monthly Financial Report: %1", _reportDef.Name));
        emailMessage.parmBody("Please find attached the monthly financial report.");

        // Add recipients from report definition
        emailMessage.parmTo(_reportDef.EmailRecipients);

        // Attach report file
        fileInfo = new System.IO.FileInfo(_reportOutput);
        if (fileInfo.Exists)
        {
            emailMessage.parmAttachments([_reportOutput]);
        }

        // Send email
        emailDistributor = new SysEmailDistributor();
        emailDistributor.sendMail(emailMessage);
    }
}

/// <summary>
/// Validates financial data integrity for Management Reporter consumption
/// Ensures accurate reporting by validating GL transactions and dimensions
/// </summary>
class FinancialDataValidator
{
    private Map validationResults;
    private int errorCount, warningCount;

    public void validateFinancialData(FromDate _fromDate, ToDate _toDate, DataAreaId _company = '')
    {
        validationResults = new Map(Types::String, Types::Container);
        errorCount = 0;
        warningCount = 0;

        changecompany(_company ? _company : curext())
        {
            info(strFmt("Starting financial data validation for period %1 to %2", _fromDate, _toDate));

            // Validate general ledger entries
            this.validateGeneralLedgerEntries(_fromDate, _toDate);

            // Validate financial dimension consistency
            this.validateFinancialDimensions(_fromDate, _toDate);

            // Validate account balances
            this.validateAccountBalances(_fromDate, _toDate);

            // Validate budget vs actual reconciliation
            this.validateBudgetReconciliation(_fromDate, _toDate);

            this.reportValidationResults();
        }
    }

    private void validateGeneralLedgerEntries(FromDate _fromDate, ToDate _toDate)
    {
        GeneralJournalEntry gjEntry;
        GeneralJournalAccountEntry gjAcctEntry;
        AmountMST totalDebits, totalCredits;
        int unbalancedEntries = 0;

        while select gjEntry
            join sum(AccountingCurrencyAmount) from gjAcctEntry
                group by PostingType
                where gjAcctEntry.GeneralJournalEntry == gjEntry.RecId
                   && gjEntry.AccountingDate >= _fromDate
                   && gjEntry.AccountingDate <= _toDate
        {
            // Check if journal entry is balanced
            select sum(AccountingCurrencyAmount) from gjAcctEntry
                where gjAcctEntry.GeneralJournalEntry == gjEntry.RecId
                   && gjAcctEntry.PostingType == LedgerPostingType::Debit;
            totalDebits = gjAcctEntry.AccountingCurrencyAmount;

            select sum(AccountingCurrencyAmount) from gjAcctEntry
                where gjAcctEntry.GeneralJournalEntry == gjEntry.RecId
                   && gjAcctEntry.PostingType == LedgerPostingType::Credit;
            totalCredits = gjAcctEntry.AccountingCurrencyAmount;

            if (abs(totalDebits - totalCredits) > 0.01) // Allow for rounding differences
            {
                unbalancedEntries++;
                this.addValidationResult("UnbalancedEntries", 
                    [gjEntry.SubledgerVoucher, totalDebits, totalCredits]);
            }
        }

        if (unbalancedEntries > 0)
        {
            error(strFmt("%1 unbalanced journal entries found", unbalancedEntries));
            errorCount += unbalancedEntries;
        }
    }

    private void validateFinancialDimensions(FromDate _fromDate, ToDate _toDate)
    {
        GeneralJournalAccountEntry gjAcctEntry;
        DimensionAttributeValueSet dimValueSet;
        DimensionAttributeValue dimValue;
        int orphanedDimensions = 0;

        while select gjAcctEntry
            where gjAcctEntry.AccountingDate >= _fromDate
               && gjAcctEntry.AccountingDate <= _toDate
               && gjAcctEntry.LedgerDimension != 0
        {
            // Validate dimension value set exists and is active
            select firstonly dimValueSet
                where dimValueSet.RecId == gjAcctEntry.LedgerDimension;

            if (!dimValueSet.RecId)
            {
                orphanedDimensions++;
                this.addValidationResult("OrphanedDimensions", 
                    [gjAcctEntry.GeneralJournalEntry, gjAcctEntry.LedgerDimension]);
                continue;
            }

            // Validate individual dimension values are active
            while select dimValue
                where dimValue.DimensionAttributeValueSet == dimValueSet.RecId
            {
                if (dimValue.IsDeleted || !dimValue.IsActive)
                {
                    this.addValidationResult("InactiveDimensionValues", 
                        [gjAcctEntry.GeneralJournalEntry, dimValue.DimensionAttributeValueId]);
                    warningCount++;
                }
            }
        }

        if (orphanedDimensions > 0)
        {
            error(strFmt("%1 entries with orphaned dimension references found", orphanedDimensions));
            errorCount += orphanedDimensions;
        }
    }

    private void validateAccountBalances(FromDate _fromDate, ToDate _toDate)
    {
        MainAccount mainAccount;
        GeneralJournalAccountEntry gjAcctEntry;
        AmountMST calculatedBalance, reportedBalance;

        while select mainAccount
            where mainAccount.MainAccountCategory != MainAccountCategory::None
        {
            // Calculate balance from journal entries
            select sum(AccountingCurrencyAmount) from gjAcctEntry
                where gjAcctEntry.MainAccount == mainAccount.RecId
                   && gjAcctEntry.AccountingDate <= _toDate;
            calculatedBalance = gjAcctEntry.AccountingCurrencyAmount;

            // Compare with reported balance from trial balance
            reportedBalance = this.getTrialBalanceAmount(mainAccount.RecId, _toDate);

            if (abs(calculatedBalance - reportedBalance) > 0.01)
            {
                this.addValidationResult("BalanceMismatch", 
                    [mainAccount.MainAccountId, calculatedBalance, reportedBalance]);
                warningCount++;
            }
        }
    }

    private AmountMST getTrialBalanceAmount(RefRecId _mainAccountRecId, ToDate _asOfDate)
    {
        // This would typically query the MRDV views used by Management Reporter
        // Simplified implementation for demonstration
        return 0;
    }

    private void validateBudgetReconciliation(FromDate _fromDate, ToDate _toDate)
    {
        // Implementation would validate budget entries against actual GL entries
        // Checking for budget vs actual variances and ensuring data consistency
    }

    private void addValidationResult(str _validationType, container _details)
    {
        if (validationResults.exists(_validationType))
        {
            validationResults.insert(_validationType, 
                concat(validationResults.lookup(_validationType), [_details]));
        }
        else
        {
            validationResults.insert(_validationType, [_details]);
        }
    }

    private void reportValidationResults()
    {
        MapEnumerator mapEnum;
        str validationType;
        container details;

        info(strFmt("Financial data validation completed. Errors: %1, Warnings: %2", 
            errorCount, warningCount));

        mapEnum = validationResults.getEnumerator();
        while (mapEnum.moveNext())
        {
            validationType = mapEnum.currentKey();
            details = mapEnum.currentValue();
            info(strFmt("%1: %2 issues found", validationType, conLen(details)));
        }
    }
}

