    public void run()
    {
        super();

        // Load initial Power BI report
        this.refreshPowerBIReport();
    }

    [DataSource]
    public class SalesTable
    {
        public void active()
        {
            super();

            // Refresh Power BI when record changes
            element.currentSalesOrder = this.cursor();
            element.refreshPowerBIReport();
        }
    }

    private void refreshPowerBIReport()
    {
        PowerBIReportHelper helper;
        str embedUrl;
        container filters;

        if (!powerBIReportPart || !currentSalesOrder.RecId)
        {
            return;
        }

        try
        {
            helper = PowerBIReportHelper::newFromConfiguration();

            // Build filters based on current sales order
            filters = this.buildReportFilters();

            // Generate filtered embed URL
            embedUrl = helper.getReportEmbedUrlWithFilters(
                powerBIReportPart.parmWorkspaceId(),
                powerBIReportPart.parmReportId(),
                filters
            );

            // Update the Power BI control
            powerBIReportPart.parmEmbedUrl(embedUrl);
            powerBIReportPart.refresh();

            info(strFmt('Power BI report refreshed for Sales Order: %1', currentSalesOrder.SalesId));
        }
        catch (Exception::Error)
        {
            error('Failed to refresh Power BI report.');
        }
    }

    private container buildReportFilters()
    {
        container filters = conNull();
        CustTable custTable;

        if (currentSalesOrder.RecId)
        {
            // Add sales order filter
            filters = conIns(filters, 1, [
                'SalesOrder',
                'SalesId',
                'eq',
                currentSalesOrder.SalesId
            ]);

            // Add customer filter
            filters = conIns(filters, 2, [
                'Customer',
                'AccountNum',
                'eq',
                currentSalesOrder.CustAccount
            ]);

            // Add date range filter (last 12 months)
            date fromDate = today() - 365;
            filters = conIns(filters, 3, [
                'OrderDate',
                'CreatedDateTime',
                'gte',
                DateTimeUtil::newDateTime(fromDate, 0)
            ]);

            // Add legal entity filter
            filters = conIns(filters, 4, [
                'LegalEntity',
                'DataAreaId',
                'eq',
                currentSalesOrder.dataAreaId
            ]);
        }

        return filters;
    }

