        {
            super();

            // Manual refresh with loading indicator
            element.setTimeOut('refreshPowerBIReport', 100, false);
        }
    }
}

/// <summary>
/// Data provider class for Customer Aging with Credit Limit analysis
/// </summary>
[SRSReportParameterAttribute(classStr(CustomerAgingContract))]
class CustomerAgingDP extends SRSReportDataProviderBase
{
    CustomerAgingTmp customerAgingTmp;
    CustomerAgingContract contract;

    [SRSReportDataSetAttribute(tableStr(CustomerAgingTmp))]
    public CustomerAgingTmp getCustomerAgingTmp()
    {
        select customerAgingTmp;
        return customerAgingTmp;
    }

    public void processReport()
    {
        QueryRun queryRun;
        CustTrans custTrans;
        CustTable custTable;
        DimensionAttributeValueSetStorage dimStorage;
        TransDate asOfDate;
        AmountCur aging30, aging60, aging90, aging120;

        contract = this.parmDataContract() as CustomerAgingContract;
        asOfDate = contract.parmAsOfDate();

        ttsbegin;
        try
        {
            // Clear any existing temp records for this user
            delete_from customerAgingTmp 
                where customerAgingTmp.SessionId == sessionId();

            queryRun = new QueryRun(contract.getQuery());

            while (queryRun.next())
            {
                custTable = queryRun.get(tableNum(CustTable));

                // Calculate aging buckets using CustAgingSnapshot
                this.calculateAgingBuckets(custTable.AccountNum, asOfDate, aging30, aging60, aging90, aging120);

                // Populate temp table with calculated values
                customerAgingTmp.clear();
                customerAgingTmp.SessionId = sessionId();
                customerAgingTmp.AccountNum = custTable.AccountNum;
                customerAgingTmp.Name = custTable.name();
                customerAgingTmp.CreditMax = custTable.CreditMax;
                customerAgingTmp.CurrencyCode = custTable.Currency;
                customerAgingTmp.Aging30 = aging30;
                customerAgingTmp.Aging60 = aging60;
                customerAgingTmp.Aging90 = aging90;
                customerAgingTmp.Aging120 = aging120;
                customerAgingTmp.TotalOutstanding = aging30 + aging60 + aging90 + aging120;
                customerAgingTmp.CreditUtilization = custTable.CreditMax ? 
                    (customerAgingTmp.TotalOutstanding / custTable.CreditMax) * 100 : 0;

                // Add dimension analysis if enabled
                if (contract.parmIncludeDimensions())
                {
                    dimStorage = DimensionAttributeValueSetStorage::find(custTable.DefaultDimension);
                    customerAgingTmp.Department = dimStorage.getDisplayValueByDimensionAttribute(
                        DimensionAttribute::findByName('Department').RecId);
                    customerAgingTmp.CostCenter = dimStorage.getDisplayValueByDimensionAttribute(
                        DimensionAttribute::findByName('CostCenter').RecId);
                }

                customerAgingTmp.insert();
            }

            ttscommit;
            info(strFmt("Customer aging report generated for %1 customers as of %2", 
                SysQuery::countTotal(customerAgingTmp), asOfDate));
        }
        catch (Exception::Error)
        {
            ttsabort;
            error("Failed to generate customer aging report: " + infolog.text());
            throw Exception::Error;
        }
    }

    private void calculateAgingBuckets(CustAccount _accountNum, TransDate _asOfDate, 
                                     AmountCur aging30, AmountCur aging60, AmountCur aging90, AmountCur aging120)
    {
        CustTrans custTrans;
        int daysDiff;

        aging30 = aging60 = aging90 = aging120 = 0;

        while select AmountCur, TransDate from custTrans
            where custTrans.AccountNum == _accountNum
               && custTrans.AmountCur != 0
        {
            daysDiff = _asOfDate - custTrans.TransDate;

            if (daysDiff <= 30)
                aging30 += custTrans.AmountCur;
            else if (daysDiff <= 60)
                aging60 += custTrans.AmountCur;
            else if (daysDiff <= 90)
                aging90 += custTrans.AmountCur;
            else
                aging120 += custTrans.AmountCur;
        }
    }
}

