// On CustTable table
display AmountMSTCur totalOutstandingBalance()
{
    AmountMSTCur        balance = 0.0;
    CustTransOpen       custTransOpen;

    try
    {
        // Calculate total open transactions for this customer
        select sum(AmountMST) from custTransOpen
            where custTransOpen.AccountNum == this.AccountNum
               && custTransOpen.AmountMST > 0;

        balance = custTransOpen.AmountMST;

        // Apply currency conversion if needed
        if (this.Currency != CompanyInfo::standardCurrencyCode())
        {
            balance = Currency::amount2MST(balance, this.Currency);
        }
    }
    catch (Exception::Error)
    {
        // Log error but don't break the form
        error("Error calculating outstanding balance for customer %1", this.AccountNum);
        balance = 0.0;
    }

    return balance;
}

// On CustTable table
edit CreditMax editCreditLimit(boolean _set = false, CreditMax _creditLimit = 0)
{
    CreditMax           newCreditLimit;
    CustTable           custTableUpdate;
    NumberSeq           numberSeq;
    CustCreditLimitLog  creditLog;

    if (_set)
    {
        try
        {
            // Validate the new credit limit
            if (_creditLimit < 0)
            {
                throw error("Credit limit cannot be negative");
            }

            // Check authorization for large increases
            if (_creditLimit > this.CreditMax * 1.5 && _creditLimit > 50000)
            {
                if (!this.checkCreditLimitAuthority(_creditLimit))
                {
                    throw error("Insufficient authority for credit limit increase");
                }
            }

            ttsbegin;

            // Update the record
            custTableUpdate = CustTable::find(this.AccountNum, true);
            custTableUpdate.CreditMax = _creditLimit;
            custTableUpdate.update();

            // Create audit log entry
            creditLog.clear();
            creditLog.AccountNum = this.AccountNum;
            creditLog.OldCreditLimit = this.CreditMax;
            creditLog.NewCreditLimit = _creditLimit;
            creditLog.ChangedBy = curuserid();
            creditLog.ChangedDateTime = DateTimeUtil::utcNow();

            numberSeq = NumberSeq::newGetNum(CustParameters::numRefCreditLimitLog());
            creditLog.LogId = numberSeq.num();
            creditLog.insert();

            ttscommit;

            // Refresh current record
            this.CreditMax = _creditLimit;

            info(strFmt("Credit limit updated to %1 for customer %2", 
                       _creditLimit, this.AccountNum));
        }
        catch (Exception::Error)
        {
            ttsabort;
            throw;
        }
    }

    return this.CreditMax;
}

// On VendTable table
display str vendorPerformanceRating()
{
    static Map              performanceCache;
    static utcdatetime      cacheExpiry;
    str                     rating = 'Unknown';
    VendInvoiceJour         vendInvoiceJour;
    PurchTable              purchTable;
    real                    avgDeliveryDays;
    real                    qualityScore;
    int                     totalOrders;

    // Initialize cache if needed
    if (!performanceCache)
    {
        performanceCache = new Map(Types::String, Types::Container);
        cacheExpiry = DateTimeUtil::addHours(DateTimeUtil::utcNow(), 4);
    }

    // Check cache validity
    if (DateTimeUtil::utcNow() > cacheExpiry)
    {
        performanceCache.clear();
        cacheExpiry = DateTimeUtil::addHours(DateTimeUtil::utcNow(), 4);
    }

    // Try to get from cache first
    if (performanceCache.exists(this.AccountNum))
    {
        container cachedData = performanceCache.lookup(this.AccountNum);
        return conpeek(cachedData, 1);
    }

    try
    {
        // Calculate performance metrics across all companies
        changecompany(CompanyInfo::standardCompany())
        {
            // Get delivery performance
            select count(RecId), avg(DeliveryDateDiff) from purchTable
                where purchTable.OrderAccount == this.AccountNum
                   && purchTable.PurchStatus == PurchStatus::Received
                   && purchTable.DeliveryDate >= today() - 365;

            totalOrders = purchTable.RecId;
            avgDeliveryDays = purchTable.DeliveryDateDiff;

            // Get quality metrics from invoice journals
            select avg(QualityScore) from vendInvoiceJour
                where vendInvoiceJour.OrderAccount == this.AccountNum
                   && vendInvoiceJour.InvoiceDate >= today() - 365
                   && vendInvoiceJour.QualityScore > 0;

            qualityScore = vendInvoiceJour.QualityScore;
        }

        // Calculate composite rating
        if (totalOrders > 0)
        {
            real performanceIndex = 0;

            // Delivery score (inverted - lower days is better)
            if (avgDeliveryDays > 0)
            {
                performanceIndex += (avgDeliveryDays <= 3 ? 40 : 
                                    avgDeliveryDays <= 7 ? 30 : 
                                    avgDeliveryDays <= 14 ? 20 : 10);
            }

            // Quality score
            performanceIndex += (qualityScore * 60 / 100);

            // Determine rating
            rating = performanceIndex >= 85 ? 'Excellent' :
                    performanceIndex >= 70 ? 'Good' :
                    performanceIndex >= 50 ? 'Average' : 'Poor';
        }

        // Cache the result
        performanceCache.insert(this.AccountNum, [rating, avgDeliveryDays, qualityScore]);
    }
    catch (Exception::Error)
    {
        warning(strFmt("Could not calculate performance rating for vendor %1", this.AccountNum));
        rating = 'Error';
    }

    return rating;
}

