// On VendTable table
[Display]
public display Real displayVendorRating()
{
    Real rating;
    str cacheKey = strFmt("%1-%2", curext(), this.AccountNum);
    Map cache = VendTableExtensions::getVendorRatingCache();

    // Check cache first
    if (cache.exists(cacheKey))
    {
        return cache.lookup(cacheKey);
    }

    try
    {
        // Complex cross-company calculation
        VendTrans vendTrans;
        PurchTable purchTable;
        int onTimeDeliveries, totalDeliveries;

        changecompany(this.dataAreaId)
        {
            while select count(RecId) from purchTable
            where purchTable.OrderAccount == this.AccountNum
               && purchTable.PurchStatus == PurchStatus::Received
            {
                totalDeliveries++;

                if (purchTable.DeliveryDate <= purchTable.RequestedDeliveryDate)
                {
                    onTimeDeliveries++;
                }
            }
        }

        rating = totalDeliveries > 0 ? 
                (real2int(onTimeDeliveries) / real2int(totalDeliveries)) * 100 : 0;

        // Cache the result for 1 hour (application domain lifetime)
        cache.insert(cacheKey, rating);
    }
    catch (Exception::Error)
    {
        rating = 0;
        error(strFmt("Error calculating vendor rating for %1", this.AccountNum));
    }

    return rating;
}

