class VendorAnalysis
{
    private Map companyTotalCache;

    public void new()
    {
        companyTotalCache = new Map(Types::String, Types::Real);
    }

    [Display]
    static display AmountMST vendorTotalAllCompanies(VendTable _vendTable)
    {
        VendTrans vendTrans;
        AmountMST totalAmount;
        container companies;
        int i;
        str currentCompany;
        VendorAnalysis analysis = new VendorAnalysis();

        if (!_vendTable.AccountNum)
            return 0;

        // Get list of companies where vendor exists
        companies = analysis.getVendorCompanies(_vendTable.AccountNum);

        for (i = 1; i <= conLen(companies); i++)
        {
            currentCompany = conPeek(companies, i);

            // Check cache first
            if (analysis.companyTotalCache.exists(currentCompany + _vendTable.AccountNum))
            {
                totalAmount += analysis.companyTotalCache.lookup(currentCompany + _vendTable.AccountNum);
                continue;
            }

            changecompany(currentCompany)
            {
                AmountMST companyTotal;

                select sum(AmountMST) from vendTrans
                    where vendTrans.AccountNum == _vendTable.AccountNum;

                companyTotal = vendTrans.AmountMST;
                totalAmount += companyTotal;

                // Cache the result
                analysis.companyTotalCache.insert(currentCompany + _vendTable.AccountNum, companyTotal);
            }
        }

        return totalAmount;
    }

    private container getVendorCompanies(VendAccount _vendAccount)
    {
        VendTable vendTable;
        container companies = connull();

        while select crosscompany : ["*"] DataAreaId from vendTable
            where vendTable.AccountNum == _vendAccount
        {
            companies = conIns(companies, conLen(companies) + 1, vendTable.DataAreaId);
        }

        return companies;
    }
}

