// On SalesLine table - edit method for discount percentage
public edit Percent lineDiscountPct(boolean _set = false, Percent _discountPct = 0)
{
    Percent currentDiscountPct;
    AmountCur newLineAmount;

    if (_set)
    {
        // Validation
        if (_discountPct < 0 || _discountPct > 100)
        {
            throw error("Discount percentage must be between 0 and 100");
        }

        if (_discountPct > 50 && !SalesParameters::find().AllowHighDiscount)
        {
            throw error("Discount exceeds maximum allowed percentage");
        }

        ttsbegin;
        try
        {
            // Calculate new amounts
            newLineAmount = this.SalesPrice * this.SalesQty * (1 - (_discountPct / 100));

            // Update related fields
            this.LinePercent = _discountPct;
            this.LineAmount = newLineAmount;
            this.modifiedField(fieldNum(SalesLine, LinePercent));
            this.modifiedField(fieldNum(SalesLine, LineAmount));

            // Trigger recalculation of totals
            this.salesTable().updateTotals();

            ttscommit;

            info(strFmt("Discount updated to %1%", _discountPct));
        }
        catch (Exception::Error)
        {
            ttsabort;
            throw;
        }
    }

    // Return current value
    currentDiscountPct = this.SalesPrice != 0 ? 
        ((this.SalesPrice - (this.LineAmount / this.SalesQty)) / this.SalesPrice) * 100 : 0;

    return currentDiscountPct;
}

