// VendTable table - display method with caching
private static Map vendorGlobalOrdersCache;

display Counter globalOrderCount()
{
    Counter orderCount = 0;
    PurchTable purchTable;
    str cacheKey;

    // Initialize static cache
    if (!VendTable::vendorGlobalOrdersCache)
    {
        VendTable::vendorGlobalOrdersCache = new Map(Types::String, Types::Integer);
    }

    cacheKey = this.AccountNum + "_" + date2Str(systemDateGet(), 321, 2, -1, 2, -1, 4);

    // Check cache first
    if (VendTable::vendorGlobalOrdersCache.exists(cacheKey))
    {
        return VendTable::vendorGlobalOrdersCache.lookup(cacheKey);
    }

    try
    {
        // Cross-company aggregation
        changecompany('USMF')
        {
            select count(RecId) from purchTable
                where purchTable.OrderAccount == this.AccountNum
                   && purchTable.PurchStatus != PurchStatus::Cancelled;
            orderCount += purchTable.RecId;
        }

        changecompany('DEMF')
        {
            select count(RecId) from purchTable
                where purchTable.OrderAccount == this.AccountNum
                   && purchTable.PurchStatus != PurchStatus::Cancelled;
            orderCount += purchTable.RecId;
        }

        // Cache the result for 1 hour
        VendTable::vendorGlobalOrdersCache.insert(cacheKey, orderCount);

        // Clean old cache entries (simple cleanup)
        if (VendTable::vendorGlobalOrdersCache.elements() > 1000)
        {
            VendTable::vendorGlobalOrdersCache = new Map(Types::String, Types::Integer);
        }
    }
    catch (Exception::Error)
    {
        warning("Unable to retrieve global order count for vendor: " + this.AccountNum);
    }

    return orderCount;
}

[SysClientCacheDataMethodAttribute(true)]
display CustCreditStatus creditStatusDisplay()
{
    CustCreditStatus creditStatus = CustCreditStatus::Good;
    CustTable custTable = this as CustTable;

    if (!custTable.AccountNum)
    {
        return CustCreditStatus::Unknown;
    }

    try
    {
        // Get credit limit and current balance
        AmountCur creditLimit = CustTable::find(custTable.AccountNum).CreditMax;
        AmountCur currentBalance = CustTrans::balance(custTable.AccountNum);

        if (creditLimit > 0)
        {
            real utilizationPercent = (currentBalance / creditLimit) * 100;

            if (utilizationPercent >= 100)
            {
                creditStatus = CustCreditStatus::Blocked;
            }
            else if (utilizationPercent >= 80)
            {
                creditStatus = CustCreditStatus::Warning;
            }
            else if (utilizationPercent >= 60)
            {
                creditStatus = CustCreditStatus::Caution;
            }
        }
        else if (currentBalance > 0)
        {
            creditStatus = CustCreditStatus::Warning;
        }
    }
    catch (Exception::Error)
    {
        creditStatus = CustCreditStatus::Unknown;
        warning("Unable to calculate credit status for customer " + custTable.AccountNum);
    }

    return creditStatus;
}

edit SalesPrice unitPriceEdit(boolean _set = false, SalesPrice _unitPrice = 0)
{
    SalesLine salesLine = this as SalesLine;

    if (_set)
    {
        ttsbegin;
        try
        {
            // Validate price is not negative
            if (_unitPrice < 0)
            {
                throw error("Unit price cannot be negative");
            }

            // Check if manual price override is allowed
            if (salesLine.PriceSource == PriceSource::Agreement && !this.allowPriceOverride())
            {
                throw error("Price override not allowed for trade agreement items");
            }

            // Store original values for rollback if needed
            SalesPrice originalPrice = salesLine.SalesPrice;
            LineAmount originalAmount = salesLine.LineAmount;

            // Set the new price
            salesLine.SalesPrice = _unitPrice;
            salesLine.PriceSource = PriceSource::Manual;

            // Recalculate line amount and discounts
            salesLine.calcLineAmount();
            this.calculateTradeDiscounts();

            // Validate total doesn't exceed order limits
            if (salesLine.LineAmount > salesLine.salesTable().MaxRetailOrderTotal && 
                salesLine.salesTable().MaxRetailOrderTotal > 0)
            {
                salesLine.SalesPrice = originalPrice;
                salesLine.LineAmount = originalAmount;
                throw error(strFmt("Line amount %1 exceeds maximum order total %2", 
                                   num2Str(salesLine.LineAmount, -1, 2, -1, -1),
                                   num2Str(salesLine.salesTable().MaxRetailOrderTotal, -1, 2, -1, -1)));
            }

            // Log price change for audit trail
            this.logPriceChange(originalPrice, _unitPrice, "Manual price override");

            ttscommit;

            // Refresh form to show updated calculations
            this.formRun().dataSource().research();
        }
        catch (Exception::Error)
        {
            ttsabort;
            throw;
        }
    }

