{
    SalesTable salesTable = this.cursor();
    FormRun formRun = this.formRun();
    str statusDisplay;

    if (!salesTable.RecId)
    {
        return "";
    }

    try
    {
        // Check user permissions for detailed status
        if (SecurityRights::hasMenuItemAccess(menuItemActionTypeAction, 
                                              menuItemActionStr(SalesOrderApprovalHistory)))
        {
            WorkflowInstanceTable workflowInstance;
            WorkflowTrackingStatusTable trackingStatus;

            // Get current workflow status
            select firstonly Status, ElementName from trackingStatus
                order by CreatedDateTime desc
                exists join workflowInstance
                where workflowInstance.RecId == trackingStatus.WorkflowInstanceRecId &&
                      workflowInstance.RefTableId == tableNum(SalesTable) &&
                      workflowInstance.RefRecId == salesTable.RecId;

            if (trackingStatus.Status)
            {
                switch (trackingStatus.Status)
                {
                    case WorkflowTrackingStatus::Pending:
                        statusDisplay = strFmt("Pending: %1", trackingStatus.ElementName);
                        break;
                    case WorkflowTrackingStatus::Approved:
                        statusDisplay = "Approved";
                        break;
                    case WorkflowTrackingStatus::Rejected:
                        statusDisplay = "Rejected";
                        break;
                    case WorkflowTrackingStatus::Cancelled:
                        statusDisplay = "Cancelled";
                        break;
                    default:
                        statusDisplay = enum2Str(trackingStatus.Status);
                }
            }
            else
            {
                statusDisplay = salesTable.DocumentStatus == VersioningDocumentStatus::Approved ? 
                               "Manual Approval" : "Not Submitted";
            }
        }
        else
        {
            // Limited view for users without detailed permissions
            statusDisplay = salesTable.DocumentStatus == VersioningDocumentStatus::Approved ? 
                           "Approved" : "Pending";
        }

        // Add visual indicators based on form mode
        if (formRun.isFormPartPreviewPane())
        {
            // Simplified display for preview pane
            statusDisplay = subStr(statusDisplay, 1, 15);
        }

        // Highlight urgent items in list view
        if (this.formRun().design().name() == formStr(SalesTableListPage) && 
            salesTable.DeliveryDate < DateTimeUtil::addDays(DateTimeUtil::utcNow(), 2))
        {
