    /// <summary>
    /// Edit method for calculated discount percentage
    /// </summary>
    [Edit]
    public real discountPercentageEdit(boolean _set = false, real _value = 0)
    {
        if (_set)
        {
            // Validation logic
            if (_value < 0 || _value > 100)
            {
                throw error("Discount percentage must be between 0 and 100");
            }

            // Check authorization for high discounts
            if (_value > 50 && !CustParameters::find().AllowHighDiscount)
            {
                throw error("Discount over 50% requires special authorization");
            }

            ttsbegin;
            try
            {
                // Store in a custom field or calculate line amount
                this.calculatedDiscountPct = _value;

                // Recalculate line amount based on new discount
                real baseAmount = this.QtyOrdered * this.SalesPrice;
                this.LineAmount = baseAmount * (1 - (_value / 100));

                // Update discount amount field
                this.LineDisc = baseAmount - this.LineAmount;

                // Mark for recalculation of totals
                this.SalesTable().modifiedField(fieldNum(SalesTable, SalesBalance));

                ttscommit;

                info(strFmt("Discount applied: %1%%. Line amount: %2", 
                           decRound(_value, 2), 
                           num2Str(this.LineAmount, -1, 2, 1, 1)));
            }
            catch (Exception::Error)
            {
                ttsabort;
                throw;
            }
        }
        else
        {
            // Calculate current discount percentage
            if (this.SalesPrice > 0 && this.QtyOrdered > 0)
            {
                real baseAmount = this.QtyOrdered * this.SalesPrice;
                if (baseAmount > 0)
                {
                    this.calculatedDiscountPct = ((baseAmount - this.LineAmount) / baseAmount) * 100;
                }
            }
        }

        return this.calculatedDiscountPct;
    }

