/// VendTable extension with optimized display methods
final class VendTableExtension
{
    // Static cache for expensive calculations
    private static Map vendorMetricsCache;
    private static utcdatetime cacheExpiry;

    /// <summary>
    /// Initialize cache if needed
    /// </summary>
    private static void initCache()
    {
        if (!VendTableExtension::vendorMetricsCache || 
            DateTimeUtil::utcNow() > VendTableExtension::cacheExpiry)
        {
            VendTableExtension::vendorMetricsCache = new Map(Types::String, Types::Container);
            // Cache expires after 5 minutes
            VendTableExtension::cacheExpiry = DateTimeUtil::addMinutes(DateTimeUtil::utcNow(), 5);
        }
    }

    /// <summary>
    /// Display vendor performance metrics with caching
    /// </summary>
    [Display]
    public str vendorPerformanceMetrics()
    {
        container       metrics;
        str             cacheKey;
        str             result;
        real            avgDeliveryDays;
        real            qualityScore;
        int             totalOrders;

        cacheKey = this.AccountNum;
        VendTableExtension::initCache();

        // Check cache first
        if (VendTableExtension::vendorMetricsCache.exists(cacheKey))
        {
            metrics = VendTableExtension::vendorMetricsCache.lookup(cacheKey);
            avgDeliveryDays = conPeek(metrics, 1);
            qualityScore = conPeek(metrics, 2);
            totalOrders = conPeek(metrics, 3);
        }
        else
        {
            // Expensive calculation - do once and cache
            try
            {
                PurchTable      purchTable;
                PurchLine       purchLine;
                InventQualityOrderTable qualityOrder;
                date            fromDate = DateTimeUtil::addMonths(today(), -12);

                // Calculate average delivery performance
                select count(RecId) from purchTable
                    where purchTable.OrderAccount == this.AccountNum &&
                          purchTable.PurchStatus == PurchStatus::Received &&
                          purchTable.DeliveryDate >= fromDate;

                totalOrders = purchTable.RecId;

                if (totalOrders > 0)
                {
                    real totalDeliveryDays = 0;

                    while select purchTable
                        where purchTable.OrderAccount == this.AccountNum &&
                              purchTable.PurchStatus == PurchStatus::Received &&
                              purchTable.DeliveryDate >= fromDate
                    {
                        if (purchTable.ConfirmedDlv && purchTable.DeliveryDate)
                        {
                            totalDeliveryDays += purchTable.DeliveryDate - purchTable.ConfirmedDlv;
                        }
                    }

                    avgDeliveryDays = totalDeliveryDays / totalOrders;
                }

                // Calculate quality score from quality orders
                int passedOrders = 0;
                int totalQualityOrders = 0;

                select count(RecId) from qualityOrder
                    where qualityOrder.RefTableId == tableNum(PurchLine) &&
                          qualityOrder.CreatedDateTime >= DateTimeUtil::newDateTime(fromDate, 0);

                totalQualityOrders = qualityOrder.RecId;

                if (totalQualityOrders > 0)
                {
                    select count(RecId) from qualityOrder
                        where qualityOrder.RefTableId == tableNum(PurchLine) &&
                              qualityOrder.TestResultValue >= 80 && // Assuming 80+ is pass
                              qualityOrder.CreatedDateTime >= DateTimeUtil::newDateTime(fromDate, 0);

                    passedOrders = qualityOrder.RecId;
                    qualityScore = (passedOrders * 100.0) / totalQualityOrders;
                }

                // Cache the results
                metrics = [avgDeliveryDays, qualityScore, totalOrders];
                VendTableExtension::vendorMetricsCache.insert(cacheKey, metrics);
            }
            catch (Exception::Error)
            {
                avgDeliveryDays = 0;
                qualityScore = 0;
                totalOrders = 0;
            }
        }

        // Format the display string
        if (totalOrders > 0)
        {
            result = strFmt("Orders: %1 | Avg Delivery: %2 days | Quality: %3%%",
                           totalOrders,
                           decRound(avgDeliveryDays, 1),
                           decRound(qualityScore, 1));
        }
        else
        {
            result = "No recent order history";
        }

        return result;
    }

    /// <summary>
    /// Clear cache when vendor data changes
    /// </summary>
    public void update()
    {
        super();

        // Invalidate cache for this vendor
        if (VendTableExtension::vendorMetricsCache)
        {
            VendTableExtension::vendorMetricsCache.remove(this.AccountNum);
        }
    }
}

