// On InventTable table
display AmountCur averageCostPrice()
{
    static Map              costCache;
    static utcdatetime      lastRefresh;
    static ItemId           lastItemId;

    InventTrans             inventTrans;
    AmountCur               totalCost, totalQty, avgCost;
    utcdatetime             currentDateTime = DateTimeUtil::utcNow();

    // Initialize cache if needed
    if (!costCache)
    {
        costCache = new Map(Types::String, Types::Real);
    }

    // Check if cache needs refresh (every 5 minutes or different item)
    if (!lastRefresh || 
        DateTimeUtil::getDifference(currentDateTime, lastRefresh) > 300 || // 5 minutes
        lastItemId != this.ItemId)
    {
        try
        {
            // Calculate average cost from transactions
            while select CostAmountPosted, Qty from inventTrans
                where inventTrans.ItemId == this.ItemId
                   && inventTrans.StatusIssue == StatusIssue::Sold
                   && inventTrans.DatePhysical >= datetobeginofyear(systemdateget())
            {
                totalCost += inventTrans.CostAmountPosted;
                totalQty += abs(inventTrans.Qty);
            }

            avgCost = totalQty != 0 ? totalCost / totalQty : 0;

            // Update cache
            costCache.insert(this.ItemId, avgCost);
            lastRefresh = currentDateTime;
            lastItemId = this.ItemId;
        }
        catch (Exception::Error)
        {
            avgCost = 0;
            warning(strFmt('Could not calculate average cost for item %1', this.ItemId));
        }
    }
    else
    {
        // Use cached value
        avgCost = costCache.lookup(this.ItemId);
    }

    return avgCost;
}

