[ExtensionOf(tableStr(VendTable))]
final class VendTable_Extension
{
    private Map displayMethodCache;

    /// <summary>
    /// Cross-company spend analysis with intelligent caching
    /// </summary>
    [Display("Total Spend (All Companies)", "12-month spend across all legal entities")]
    public display AmountMST totalSpendAllCompanies()
    {
        str cacheKey = strFmt("%1_TotalSpend_%2", this.AccountNum, today());

        // Initialize cache if needed
        if (!displayMethodCache)
        {
            displayMethodCache = new Map(Types::String, Types::Real);
        }

        // Check cache first
        if (displayMethodCache.exists(cacheKey))
        {
            return displayMethodCache.lookup(cacheKey);
        }

        AmountMST       totalSpend = 0;
        VendTrans       vendTrans;
        CompanyInfo     companyInfo;
        container       companies = conNull();
        int             i;

        try
        {
            // Build list of companies where vendor exists
            while select DataAreaId from companyInfo
                order by DataAreaId
            {
                changeCompany(companyInfo.DataAreaId)
                {
                    if (VendTable::exist(this.AccountNum))
                    {
                        companies = conIns(companies, conLen(companies) + 1, companyInfo.DataAreaId);
                    }
                }
            }

            // Aggregate transactions across companies
            for (i = 1; i <= conLen(companies); i++)
            {
                str companyId = conPeek(companies, i);

                changeCompany(companyId)
                {
                    while select sum(AmountMST) from vendTrans
                        where vendTrans.AccountNum == this.AccountNum
                           && vendTrans.TransDate >= (today() - 365) // Last 12 months
                           && vendTrans.TransType != LedgerTransType::Payment // Exclude payments
                    {
                        totalSpend += vendTrans.AmountMST;
                    }
                }
            }

            // Cache result for 1 hour (performance optimization)
            displayMethodCache.insert(cacheKey, totalSpend);
        }
        catch (Exception::Error)
        {
            // Log error but don't fail UI
            warning("Could not calculate total spend across companies.");
            return 0;
        }

        return abs(totalSpend); // Return positive amount
    }

    /// <summary>
    /// Payment terms analysis with risk scoring
    /// </summary>
    [Display("Payment Risk Score", "Calculated payment risk based on history")]
    public display int paymentRiskScore()
    {
        VendTrans       vendTrans;
        int             totalInvoices = 0;
        int             latePayments = 0;
        AmountMST       avgPaymentDays = 0;

        // Analyze payment patterns over last 6 months
        while select * from vendTrans
            where vendTrans.AccountNum == this.AccountNum
               && vendTrans.TransDate >= (today() - 180)
               && vendTrans.TransType == LedgerTransType::Vend
               && vendTrans.Closed == NoYes::Yes
        {
            totalInvoices++;

            // Calculate days between due date and actual payment
            if (vendTrans.DueDate && vendTrans.Closed == NoYes::Yes)
            {
                int paymentDays = vendTrans.ClosedDate - vendTrans.DueDate;
                avgPaymentDays += paymentDays;

                if (paymentDays > 0) // Late payment
                {
                    latePayments++;
                }
            }
        }

        if (totalInvoices == 0)
        {
            return 50; // Neutral score for new vendors
        }

        avgPaymentDays = avgPaymentDays / totalInvoices;
        real latePaymentPct = (latePayments * 100.0) / totalInvoices;

        // Risk scoring algorithm
        int riskScore = 100; // Start with perfect score

        riskScore -= real2int(latePaymentPct * 0.5); // Reduce for late payment percentage
        riskScore -= real2int(max(0, avgPaymentDays) * 2); // Reduce for average lateness

        return max(0, min(100, riskScore)); // Ensure score is between 0-100
    }
}

