            if (this.RecId && this.hasActiveTransactions())
            {
                if (!Box::yesNo("@SYS89543", DialogButton::No)) // "Item has active transactions. Continue?"
                {
                    return ret;
                }
            }

            // Update the actual field
            ttsbegin;
            try
            {
                this.selectForUpdate(true);
                this.UnitPrice = _unitPrice;
                this.update();

                // Trigger related updates
                this.updateSalesPrice(_unitPrice);

                ret = this.UnitPrice;
                ttscommit;

                info(strFmt("Unit price updated to %1 for item %2", 
                           this.UnitPrice, this.ItemId));
            }
            catch (Exception::Error)
            {
                ttsabort;
                throw;
            }
        }

        return ret;
    }

    // Supporting method for validation
    private boolean hasActiveTransactions()
    {
        InventTrans inventTrans;

        select firstonly RecId from inventTrans
            where inventTrans.ItemId == this.ItemId
            && inventTrans.StatusReceipt == StatusReceipt::Ordered
            || inventTrans.StatusIssue == StatusIssue::Ordered;

        return inventTrans.RecId != 0;
    }

    // Method to update related sales prices
    private void updateSalesPrice(Price _newPrice)
    {
        SalesPrice salesPrice;

        update_recordset salesPrice
            setting Price = _newPrice
            where salesPrice.ItemId == this.ItemId
            && salesPrice.ToDate >= DateTimeUtil::date(DateTimeUtil::utcNow());
    }
}

