// On InventTable table - Calculate available inventory across all warehouses
public class InventTableDisplayMethods
{
    private static Map inventAvailabilityCache;
    private static utcDateTime lastCacheRefresh;
    private static final int CACHE_VALIDITY_MINUTES = 5;

    [SysClientCacheDataMethodAttribute(true)]
    display InventQty displayAvailableInventory()
    {
        ItemId itemId = this.ItemId;
        InventQty availableQty;
        utcDateTime currentTime = DateTimeUtil::getSystemDateTime();

        // Initialize cache if needed
        if (!inventAvailabilityCache)
        {
            inventAvailabilityCache = new Map(Types::String, Types::Real);
            lastCacheRefresh = currentTime;
        }

        // Check if cache needs refresh (every 5 minutes)
        if (DateTimeUtil::getDifference(currentTime, lastCacheRefresh) > (CACHE_VALIDITY_MINUTES * 60))
        {
            inventAvailabilityCache.clear();
            lastCacheRefresh = currentTime;
        }

        // Try to get from cache first
        if (inventAvailabilityCache.exists(itemId))
        {
            availableQty = inventAvailabilityCache.lookup(itemId);
        }
        else
        {
            // Calculate expensive inventory sum
            InventSum inventSum;

            select sum(AvailPhysical) from inventSum
                where inventSum.ItemId == itemId
                   && inventSum.Closed == NoYes::No;

            availableQty = inventSum.AvailPhysical;

            // Cache the result
            inventAvailabilityCache.insert(itemId, availableQty);
        }

        return availableQty;
    }

    // Method to invalidate cache for specific item
    public static void invalidateItemCache(ItemId _itemId)
    {
        if (inventAvailabilityCache && inventAvailabilityCache.exists(_itemId))
        {
            inventAvailabilityCache.remove(_itemId);
        }
    }
}

