// On InventTable table
private static Map inventAvailabilityCache;

[Display]
public str availabilityDisplay()
{
    str             availability;
    InventSum       inventSum;
    InventDim       inventDim;
    real            physicalQty, reservedQty, availableQty;
    str             cacheKey;

    // Initialize cache if not exists
    if (!InventTable::inventAvailabilityCache)
    {
        InventTable::inventAvailabilityCache = new Map(Types::String, Types::String);
    }

    // Create cache key based on item and current datetime
    cacheKey = this.ItemId + "#" + DateTimeUtil::toStr(DateTimeUtil::utcNow());

    // Check cache first (5 minute cache)
    if (InventTable::inventAvailabilityCache.exists(cacheKey))
    {
        return InventTable::inventAvailabilityCache.lookup(cacheKey);
    }

    try
    {
        // Get default inventory dimension
        inventDim = InventDim::findOrCreate(InventTable::inventDimFieldsBlank());

        // Calculate availability across all sites
        while select sum(PhysicalInvent), sum(ReservPhysical) from inventSum
            where inventSum.ItemId == this.ItemId
            && inventSum.Closed == NoYes::No
        {
            physicalQty += inventSum.PhysicalInvent;
            reservedQty += inventSum.ReservPhysical;
        }

        availableQty = physicalQty - reservedQty;

        // Format availability string with status icon
        if (availableQty <= 0)
        {
            availability = "⚠️ " + strFmt("@SYS325898", abs(availableQty)); // Out of stock (Backorder: %1)
        }
        else if (availableQty < this.MinInventQty())
        {
            availability = "⚡ " + strFmt("@SYS325899", availableQty); // Low stock: %1
        }
        else
        {
            availability = "✅ " + strFmt("@SYS325900", availableQty); // Available: %1
        }

        // Cache the result
        InventTable::inventAvailabilityCache.insert(cacheKey, availability);
    }
    catch (Exception::Error)
    {
        availability = "❌ @SYS325901"; // Error retrieving availability
        error("Error calculating availability for item " + this.ItemId);
    }

    return availability;
}

// Cache cleanup method (call from form close or periodic job)
static void clearAvailabilityCache()
{
    if (InventTable::inventAvailabilityCache)
    {
        InventTable::inventAvailabilityCache = null;
    }
}

