    Real            taxRate;

    try
    {
        if (_taxAmount < 0)
        {
            throw error("Tax amount cannot be negative");
        }

        // Validate against maximum allowed tax
        calculatedTax = TaxCalculation::calcLineTax(this.SalesId, this.LineNum);

        if (_taxAmount > calculatedTax * 1.1) // 10% tolerance
        {
            if (!Box::yesNo(strFmt("Tax amount %1 exceeds calculated tax %2. Continue?",
                                 num2Str(_taxAmount, 0, 2, 1, 1),
                                 num2Str(calculatedTax, 0, 2, 1, 1)),
                          DialogButton::No))
            {
                return this.TaxAmount; // Return original value
            }
        }

        // Update the field
        this.TaxAmount = _taxAmount;

        // Trigger dependent field calculations
        this.LineAmount = this.calcLineAmount();

        // Update header totals if this is part of a form transaction
        salesTable = SalesTable::find(this.SalesId, true);
        if (salesTable.RecId)
        {
            salesTable.reread();
            salesTable.calc();
            salesTable.doUpdate();
        }
    }
    catch (Exception::Error)
    {
        // Reset to original value on error
        return this.TaxAmount;
    }

    return this.TaxAmount;
}

// Helper method for tax calculation
private TaxAmount calcLineTax()
{
    TmpTaxWorkTrans     tmpTaxWorkTrans;
    TaxAmount          totalTax = 0;

    // Use standard tax engine
    Tax::calcTax(tmpTaxWorkTrans, this);

    while select tmpTaxWorkTrans
    {
        totalTax += tmpTaxWorkTrans.TaxAmount;
    }

    return totalTax;
}

// On InventTable table - cached inventory availability display
class InventTable_Extension
{
    private Map availabilityCache;
    private UtcDateTime lastCacheUpdate;
    private static final int CACHE_TIMEOUT_MINUTES = 5;

    [SysClientCacheDataMethodAttribute(true)]
    display Qty availableInventory()
    {
        InventDim           inventDim;
        InventSum           inventSum;
        Qty                 available = 0;
        UtcDateTime         currentTime = DateTimeUtil::utcNow();
        str                 cacheKey;

        try
        {
            // Initialize cache if needed
            if (!this.availabilityCache)
            {
                this.availabilityCache = new Map(Types::String, Types::Real);
                this.lastCacheUpdate = currentTime;
            }

            cacheKey = strFmt("%1_%2", this.ItemId, this.dataAreaId);

            // Check cache validity (5 minute timeout)
            if (this.lastCacheUpdate && 
                DateTimeUtil::getDifference(currentTime, this.lastCacheUpdate) < (CACHE_TIMEOUT_MINUTES * 60))
            {
                if (this.availabilityCache.exists(cacheKey))
                {
                    return this.availabilityCache.lookup(cacheKey);
                }
            }
            else
            {
                // Clear expired cache
                this.availabilityCache = new Map(Types::String, Types::Real);
                this.lastCacheUpdate = currentTime;
            }

            // Calculate fresh availability
            inventDim.clear();
            inventDim.initFromInventTable(this);

            select sum(PostedQty), sum(ReservedQty) from inventSum
                where inventSum.ItemId == this.ItemId
                && inventSum.Closed == NoYes::No
                exists join inventDim
                    where inventDim.inventDimId == inventSum.InventDimId;

            available = inventSum.PostedQty - inventSum.ReservedQty;

            // Cache the result
            this.availabilityCache.insert(cacheKey, available);

            // Log cache miss for monitoring
            if (isRunningOnServer())
            {
                Info(strFmt("Cache miss for item %1 - calculated availability: %2", 
                     this.ItemId, num2Str(available, 0, 2, 1, 1)));
            }
        }
        catch (Exception::Error)
        {
            warning(strFmt("Error calculating availability for item %1", this.ItemId));
            available = 0;
        }

        return available;
    }

    // Method to invalidate cache when inventory changes
    public void invalidateAvailabilityCache()
    {
        if (this.availabilityCache)
        {
            str cacheKey = strFmt("%1_%2", this.ItemId, this.dataAreaId);
            this.availabilityCache.remove(cacheKey);
        }
    }
}

