[ExtensionOf(tableStr(InventTrans))]
final class InventTrans_Extension
{
    /// <summary>
    /// Edit method for batch quantity allocation
    /// Allows users to specify quantity and auto-distributes to available batches
    /// </summary>
    edit InventQty batchQtyAllocation(boolean _set = false, InventQty _qty = 0)
    {
        InventQty currentQty, remainingQty;
        InventBatch inventBatch;
        InventSum inventSum;
        InventDim inventDim;

        if (_set)
        {
            // Setter logic - distribute quantity across available batches
            ttsbegin;
            try
            {
                remainingQty = _qty;

                // Clear existing allocations
                delete_from inventTrans
                    where inventTrans.InventTransOrigin == this.InventTransOrigin
                       && inventTrans.StatusReceipt == StatusReceipt::None;

                if (remainingQty > 0)
                {
                    // Find available batches with FEFO logic
                    while select inventBatch
                        order by inventBatch.ProdDate asc
                        join inventSum
                        where inventSum.ItemId == this.ItemId
                           && inventSum.InventDimId == inventBatch.inventDimId()
                           && inventSum.PhysicalInvent > 0
                    {
                        InventQty batchQty = min(remainingQty, inventSum.PhysicalInvent);

                        if (batchQty > 0)
                        {
                            // Create allocation record
                            InventTrans allocTrans;
                            allocTrans.clear();
                            allocTrans.initValue();
                            allocTrans.InventTransOrigin = this.InventTransOrigin;
                            allocTrans.ItemId = this.ItemId;
                            allocTrans.Qty = -batchQty; // Negative for allocation
                            allocTrans.InventDimId = inventBatch.inventDimId();
                            allocTrans.StatusIssue = StatusIssue::ReservPhysical;
                            allocTrans.insert();

                            remainingQty -= batchQty;

                            if (remainingQty <= 0)
                            {
                                break;
                            }
                        }
                    }
                }

                if (remainingQty > 0)
                {
                    warning(strFmt("Could not allocate %1 units - insufficient batch inventory", remainingQty));
                }

                ttscommit;
            }
            catch (Exception::Error)
            {
                ttsabort;
                error("Failed to allocate batch quantities");
                return 0;
            }
        }

        // Getter logic - return current total allocated quantity
        select sum(Qty) from inventTrans
            where inventTrans.InventTransOrigin == this.InventTransOrigin
               && inventTrans.StatusReceipt == StatusReceipt::None;

        return abs(inventTrans.Qty);
    }

    /// <summary>
    /// Display method showing batch allocation details
    /// </summary>
    display BatchAllocationDetails batchAllocationSummary()
    {
        InventTrans allocTrans;
        InventDim inventDim;
        str summary = "";
        int batchCount = 0;

        while select allocTrans
            join inventDim
            where allocTrans.InventTransOrigin == this.InventTransOrigin
               && allocTrans.StatusReceipt == StatusReceipt::None
               && inventDim.inventDimId == allocTrans.InventDimId
               && inventDim.InventBatchId
        {
            if (batchCount > 0)
            {
                summary += "; ";
            }

            summary += strFmt("%1: %2", inventDim.InventBatchId, abs(allocTrans.Qty));
            batchCount++;

            if (batchCount >= 3) // Limit display length
            {
                summary += "...";
                break;
            }
        }

        return summary ? summary : "No allocations";
    }
}

[ExtensionOf(tableStr(SalesTable))]
final class SalesTable_Extension
{
    private Map displayMethodCache;

    /// <summary>
    /// Cached display method for sales order profitability analysis
    /// </summary>
    display ProfitMarginPct profitMargin()
    {
        str cacheKey = "ProfitMargin";
        ProfitMarginPct cachedValue;

        // Check cache first
        if (!this.displayMethodCache)
        {
            this.displayMethodCache = new Map(Types::String, Types::Real);
        }

        if (this.displayMethodCache.exists(cacheKey))
        {
            return this.displayMethodCache.lookup(cacheKey);
        }

        // Calculate profit margin with server-side execution
        cachedValue = this.calculateProfitMarginServer();

        // Cache the result
        this.displayMethodCache.insert(cacheKey, cachedValue);

        return cachedValue;
    }

    /// <summary>
    /// Server method for profit margin calculation
    /// </summary>
    private server ProfitMarginPct calculateProfitMarginServer()
    {
        SalesLine salesLine;
        InventTable inventTable;
        InventTableModule inventTableModule;
        AmountMST totalRevenue = 0;
        AmountMST totalCost = 0;
        ProfitMarginPct marginPct = 0;

        try
        {
            while select salesLine
                join inventTable
                    where inventTable.ItemId == salesLine.ItemId
                join inventTableModule
                    where inventTableModule.ItemId == inventTable.ItemId
                       && inventTableModule.ModuleType == ModuleInventPurchSales::Purch
                where salesLine.SalesId == this.SalesId
                   && salesLine.SalesStatus != SalesStatus::Canceled
            {
                AmountMST lineRevenue = salesLine.calcLineAmountExclTax();
                AmountMST lineCost = salesLine.InventQty * inventTableModule.Price;

                totalRevenue += lineRevenue;
                totalCost += lineCost;
            }

            if (totalRevenue != 0)
            {
                marginPct = ((totalRevenue - totalCost) / totalRevenue) * 100;
            }
        }
        catch (Exception::Error)
        {
            error("Error calculating profit margin for sales order " + this.SalesId);
            marginPct = 0;
        }

        return marginPct;
    }

    /// <summary>
    /// Clears display method cache when order is modified
    /// </summary>
    public void update()
    {
        super();

        // Clear cache on update
        if (this.displayMethodCache)
        {
            this.displayMethodCache = null;
        }
    }

    /// <summary>
    /// Display method with conditional server execution
    /// </summary>
    display str deliveryPerformance()
    {
        str performance;

        // Execute on server for data-intensive operations
        if (isConfigurationkeyEnabled(configurationkeyNum(LogisticsAdvanced)))
        {
            performance = this.calculateDeliveryPerformanceServer();
        }
        else
        {
            performance = "Advanced logistics required";
        }

        return performance;
    }

    private server str calculateDeliveryPerformanceServer()
    {
        SalesLine salesLine;
        int totalLines = 0;
        int onTimeLines = 0;
        date requestedDate, confirmedDate;

        select count(RecId) from salesLine
            where salesLine.SalesId == this.SalesId;
        totalLines = salesLine.RecId;

        while select salesLine
            where salesLine.SalesId == this.SalesId
        {
            requestedDate = salesLine.RequestedReceiptDate;
            confirmedDate = salesLine.ConfirmedDlv;

            if (confirmedDate && confirmedDate <= requestedDate)
            {
                onTimeLines++;
            }
        }

        if (totalLines > 0)
        {
            Real performancePct = (real2int(onTimeLines) / real2int(totalLines)) * 100;
            return strFmt("%1% (%2/%3)", decround(performancePct, 1), onTimeLines, totalLines);
        }

        return "No deliveries";
    }
}

