edit CreditMax editCreditLimit(boolean _set = false, CreditMax _creditLimit = 0)
{
    CustCreditLimitHistory  historyRecord;
    NumberSeq              numberSeq;

    if (_set)
    {
        try
        {
            ttsbegin;

            // Validate new credit limit
            if (_creditLimit < 0)
            {
                throw error("@SYS318447"); // Credit limit cannot be negative
            }

            // Check authorization for large credit limits
            if (_creditLimit > 100000 && !SecurityRights::hasMenuItemAccess(
                menuItemActionStr(CustTableListPage), MenuItemType::Action))
            {
                throw error("Insufficient privileges for credit limit above 100,000");
            }

            // Create audit trail record
            if (this.CreditMax != _creditLimit)
            {
                historyRecord.clear();
                historyRecord.initValue();
                historyRecord.AccountNum = this.AccountNum;
                historyRecord.OldCreditLimit = this.CreditMax;
                historyRecord.NewCreditLimit = _creditLimit;
                historyRecord.ModifiedDateTime = DateTimeUtil::getSystemDateTime();
                historyRecord.ModifiedBy = curUserId();

                numberSeq = NumberSeq::newGetNum(CustParameters::numRefCreditLimitHistory());
                historyRecord.RecId = numberSeq.num();
                historyRecord.insert();

                // Update the actual field
                this.CreditMax = _creditLimit;

                // Trigger workflow if configured
                if (CustParameters::find().WorkflowCreditLimitEnabled)
                {
                    CustCreditLimitWorkflow::submitToWorkflow(this, historyRecord.RecId);
                }

                info(strFmt("Credit limit updated from %1 to %2", 
                    this.CreditMax, _creditLimit));
            }

            ttscommit;
        }
        catch (Exception::Error)
        {
            error("Failed to update credit limit");
            return this.CreditMax; // Return current value on error
        }
    }

    return this.CreditMax;
}

