[SysClientCacheDataMethodAttribute(true)]
display AmountMST displayTotalSalesYTD()
{
    AmountMST           totalSales;
    CustTrans           custTrans;
    TransDate           yearStart;
    container           cacheKey;
    Global              globalCache;
    str                 cacheKeyStr;

    try
    {
        // Build cache key including year to handle year-end transitions
        yearStart = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
        yearStart = mkDate(1, 1, year(yearStart));
        cacheKey = [this.AccountNum, yearStart, curExt()];
        cacheKeyStr = con2Str(cacheKey, '|');

        // Check global cache first (persists across sessions)
        globalCache = Global::find();
        if (globalCache)
        {
            totalSales = globalCache.parmValueAmountMST(cacheKeyStr);
            if (totalSales != 0)
            {
                return totalSales;
            }
        }

        // Calculate total sales for current year
        select crossCompany sum(AmountMST) from custTrans
            where custTrans.AccountNum == this.AccountNum
               && custTrans.TransDate >= yearStart
               && custTrans.TransDate <= today()
               && custTrans.TransType == LedgerTransType::Sales;

        totalSales = custTrans.AmountMST;

        // Cache result for 1 hour
        if (globalCache)
        {
            globalCache.parmValueAmountMST(cacheKeyStr, totalSales, 
                DateTimeUtil::addHours(DateTimeUtil::getSystemDateTime(), 1));
        }

        return totalSales;
    }
    catch (Exception::Error)
    {
        warning(strFmt("Could not calculate YTD sales for customer %1", this.AccountNum));
        return 0;
    }
}

