public edit AmountMST lineTotal(AmountMST _lineTotal = this.calcLineAmount())
{
    AmountMST newUnitPrice;

    // Getter: return calculated value
    if (prmIsDefault(_lineTotal))
    {
        return this.calcLineAmount(); // Use existing calculation method
    }

    // Setter: validate and update underlying fields
    if (_lineTotal < 0)
    {
        error("@SYS26332"); // Line total cannot be negative
        return this.calcLineAmount();
    }

    // Calculate new unit price based on desired total
    if (this.SalesQty != 0)
    {
        newUnitPrice = _lineTotal / this.SalesQty;

        ttsbegin;
        this.SalesPrice = newUnitPrice;
        // Recalculate dependent fields
        this.calcLineDisc();
        this.modifiedField(fieldNum(SalesLine, SalesPrice));
        ttscommit;
    }

    return this.calcLineAmount();
}

public edit Percent discountPercent(Percent _discountPct = this.calcDiscountPercent())
{
    AmountMST discountAmount;

    if (prmIsDefault(_discountPct))
    {
        return this.calcDiscountPercent();
    }

    // Validate percentage range
    if (_discountPct < 0 || _discountPct > 100)
    {
        error("Discount percentage must be between 0 and 100");
        return this.calcDiscountPercent();
    }

    try
    {
        ttsbegin;

        // Calculate and set discount amount
        discountAmount = (this.SalesPrice * this.SalesQty) * (_discountPct / 100);
        this.LineDisc = discountAmount;

        // Trigger recalculation of dependent methods
        this.modifiedField(fieldNum(SalesLine, LineDisc));

        ttscommit;
    }
    catch (Exception::Error)
    {
        error("Failed to update discount percentage");
    }

    return _discountPct;
}

