        query = new Query();
        qbds = query.addDataSource(tableNum(PurchLine));
        qbds.addSortField(fieldNum(PurchLine, CreatedDateTime), SortOrder::Descending);

        qbr = qbds.addRange(fieldNum(PurchLine, RecId));
        qbr.value(strFmt("(SELECT TOP 1 PurchLine.RecId FROM %1 PurchLine "
                        + "JOIN %2 PurchTable ON PurchLine.PurchId == PurchTable.PurchId "
                        + "WHERE PurchTable.OrderAccount == '%3' "
                        + "ORDER BY PurchLine.CreatedDateTime DESC)",
                        purchLine.TableId, purchTable.TableId, this.AccountNum));

        queryRun = new QueryRun(query);

        if (queryRun.next())
        {
            purchLine = queryRun.get(tableNum(PurchLine));
            lastItem = purchLine.ItemId;
