// On SalesTable table
public edit DiscPercent salesLineDiscountPercent(boolean _set, DiscPercent _discPercent)
{
    DiscPercent currentDiscPercent;
    SalesLine salesLine;

    if (_set)
    {
        try
        {
            ttsbegin;

            // Validate discount percentage
            if (_discPercent < 0 || _discPercent > 100)
            {
                throw error("Discount percentage must be between 0 and 100");
            }

            // Check authorization for high discounts
            if (_discPercent > 20 && !SecurityUtil::hasPermission(securitykeyNum(HighDiscountApproval)))
            {
                throw error("High discount approval required for discounts over 20%");
            }

            // Update all related sales lines
            while select forupdate salesLine
                where salesLine.SalesId == this.SalesId
                   && salesLine.SalesStatus == SalesStatus::Backorder
            {
                salesLine.DiscPercent = _discPercent;

                // Recalculate line amount
                salesLine.calcLineAmount();

                if (salesLine.validateWrite())
                {
                    salesLine.update();
                }
                else
                {
                    throw error("Failed to update sales line %1", salesLine.ItemId);
                }
            }

            // Update header totals
            this.calcTotals();

            // Log the change for audit
            info(strFmt("Applied %1%% discount to %2 sales lines in order %3", 
                      _discPercent, SysQuery::countTotal(salesLine), this.SalesId));

            ttscommit;
        }
        catch (Exception::Error)
        {
            ttsabort;
            // Re-throw to show user the error
            throw;
        }
    }
    else
    {
        // Getter: Calculate average discount from lines
        select avg(DiscPercent) from salesLine
            where salesLine.SalesId == this.SalesId;

        currentDiscPercent = salesLine.DiscPercent;
    }

    return currentDiscPercent;
}

// On PurchTable table
[DisplayCache(false)] // Don't cache due to workflow state changes
public display container purchOrderStatusDisplay()
{
    container statusContainer;
    str statusText;
    int colorIndex;
    PurchStatus baseStatus;
    WorkflowStatus workflowStatus;
    boolean hasReceiptDiscrepancies;

    try
    {
        baseStatus = this.PurchStatus;
        workflowStatus = this.WorkflowStatus;

        // Check for receiving discrepancies
        hasReceiptDiscrepancies = this.hasReceivingDiscrepancies();

        // Determine display status based on complex business rules
        switch (baseStatus)
        {
            case PurchStatus::Backorder:
                if (workflowStatus == WorkflowStatus::Pending)
                {
                    statusText = "Pending Approval";
                    colorIndex = 3; // Yellow
                }
                else if (this.isOverdue())
                {
                    statusText = "Overdue";
                    colorIndex = 1; // Red
                }
                else
                {
                    statusText = "Open";
                    colorIndex = 0; // Default
                }
                break;

            case PurchStatus::Received:
                if (hasReceiptDiscrepancies)
                {
                    statusText = "Received - Discrepancies";
                    colorIndex = 2; // Orange
                }
                else
                {
                    statusText = "Received";
                    colorIndex = 4; // Green
                }
                break;

            case PurchStatus::Invoiced:
                statusText = "Complete";
                colorIndex = 4; // Green
                break;

            default:
                statusText = enum2Str(baseStatus);
                colorIndex = 0;
                break;
        }

        // Add urgency indicator for expedited orders
        if (this.DeliveryMode && DlvMode::find(this.DeliveryMode).IsExpedited)
        {
            statusText = "⚡ " + statusText;
        }

        // Return container with text and color hint for form control
        statusContainer = [statusText, colorIndex];
    }
    catch (Exception::Error)
    {
        error("Error determining purchase order status for %1", this.PurchId);
        statusContainer = ["Error", 1];
    }

    return statusContainer;
}

// Helper method for workflow integration
private boolean isOverdue()
{
    return this.DeliveryDate < DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()) 
           && this.PurchStatus == PurchStatus::Backorder;
}
